async function hashPass(str){
  const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(str));
  return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,'0')).join('');
}

async function tryAdminLogin(){
  const u=(document.getElementById('aUser')?.value||'').trim().toLowerCase();
  const p=(document.getElementById('aPass')?.value||'').trim();
  if(!u||!p){ showLoginErrAdmin('Username aur Password daalein'); return; }

  const rl = checkRateLimit('admin');
  if(!rl.ok){ showLoginErrAdmin('🔒 ' + rl.msg); return; }

  const btn=document.getElementById('aLoginBtn')||(document.querySelector('#adminLoginPanel .big-btn'));
  if(btn){ btn.innerHTML='⏳ Login ho raha hai...'; btn.style.opacity='0.7'; btn.style.pointerEvents='none'; }
  const restoreBtn=()=>{ if(btn){ btn.innerHTML='🔐 Login करें'; btn.style.opacity='1'; btn.style.pointerEvents='auto'; } };

  try{
    const passHash = await hashPass(u+':'+p+':MP_ADMIN');
    let adminInfo = null;

    // ── STEP 1: Direct Firebase check (fast, reliable, was always working) ──
    try{
      const fbAuthData = await fbGet('adminAuth');
            if(fbAuthData && fbAuthData[u]){
        if(fbAuthData[u].h === passHash){
          adminInfo = {name:fbAuthData[u].name||u.toUpperCase(), role:'Admin'};
        }
      }
    }catch(e){ console.warn('[adminLogin] Firebase read failed:', e.message); }

    // SECURITY: No client-side emergency password fallback (hashes must not ship in the bundle).
    // If Firebase is unreachable, admin login fails closed — use Console / network recovery.

    if(!adminInfo){
      recordFailedAttempt('admin');
      showLoginErrAdmin('❌ Username ya Password galat hai');
      restoreBtn(); return;
    }

    // ── STEP 2: Get Firebase Auth token (Cloud Function or anonymous) ──
    // This runs AFTER password is verified — so login is not blocked by slow CF
    try{
      const result = await Promise.race([
        window._fbCall('adminLogin', { username: u, passHash }),
        new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), 8000))
      ]);
      if(result.data && result.data.token){
        await window._fbSignInWithToken(result.data.token);
      }
    }catch(cfErr){
      console.warn('[adminLogin] CF auth failed, using anonymous:', cfErr.message);
      try{ await window._fbSignInAnon(); }catch(e){}
    }

    resetAttempts('admin');
    SESSION = {
      role:'admin', name:adminInfo.name||u.toUpperCase(),
      empId:u, empObjId:'admin_'+u,
      adminRole:adminInfo.role||'Admin',
      loginAt:new Date().toISOString()
    };
    saveSession();
    restoreBtn();
    writeIntegrityToken();
    localStorage.setItem('mp_int_ok','1');
    // Google Analytics — admin login
    try{
      if(typeof window._fbLogEvent === 'function'){
        window._fbLogEvent('admin_login', {
          method: 'password',
          admin_user: u,
          admin_name: adminInfo.name || u,
          app_name: 'Man Power'
        });
        window._fbLogEvent('login', { method: 'admin_password' });
      }
    }catch(e){ console.warn('[analytics] admin_login', e); }
    launchApp();
    listenAdminNotifications();
    setTimeout(()=>registerFingerprint(adminInfo.name||u.toUpperCase(), 'admin_'+u), 1500);
  }catch(err){
    console.error('Admin login error:',err);
    showLoginErrAdmin('❌ Error: '+err.message);
    restoreBtn();
  }
}

async function proceedFromCode(){
  // Members must login with Mobile Number only (step 1) — Emp Code is no longer the entry point
  toast('📱 Member login: पहले Mobile Number डालें');
  try{ showStep(1); document.getElementById('loginMobile')?.focus(); }catch(e){}
  return;
  const code=(document.getElementById('wCode')?.value||'').trim().toUpperCase();
  if(!code||code.length<3){ showLoginErrStep(2,'Employee Code डालें (कम से कम 3 characters)'); return; }
  _step1Code=code;
  _step1Company='Man Power';

  const btn=document.getElementById('step2Btn');
  if(btn){ btn.innerHTML='⏳ जाँच रहे हैं...'; btn.style.opacity='0.7'; btn.style.pointerEvents='none'; }
  const restoreBtn=()=>{ if(btn){ btn.innerHTML='Proceed →'; btn.style.opacity='1'; btn.style.pointerEvents='auto'; } };

  try{
    let empData=null;
    try{ empData=await fbGet('employees'); }catch(e){}
    const emps=empData?Object.values(empData):(_cache.employees||[]);
    if(emps.length) _cache.employees=emps;

    const match=emps.find(e=>e.empId&&e.empId.trim().toUpperCase()===code);

    if(match){
      try{
        const appr=await fbGet('userApprovals/'+match.id);
        if(appr&&appr.status==='revoked'){
          showLoginErrStep(2,'❌ आपकी access Admin ने बंद की है। +91-8929394920 पर संपर्क करें।');
          restoreBtn(); return;
        }
      }catch(e){}

      // ── SMART LOGIN: Check if device already approved ──
      const deviceId = getDeviceId();
      const savedPw = localStorage.getItem('mp_pw_'+match.id);
      let dRec = null;
      try{ dRec = await fbGet('deviceApprovals/'+match.id); }catch(e){}
      if(dRec && dRec.approvedDeviceId === deviceId && new Date(dRec.validTill) > new Date()){
        restoreBtn();
        if(savedPw){
          showPasswordLoginScreen(match, deviceId);
        } else {
          showSetPasswordScreen(match, deviceId);
        }
        return;
      }

      // ── OTHER DEVICE LOGIN (no OTP): already logged in elsewhere → ask that device ──
      if(dRec && dRec.approvedDeviceId && dRec.approvedDeviceId !== deviceId){
        restoreBtn();
        showOtherDeviceLoginRequest(match, dRec, deviceId);
        return;
      }

      // ── OTP LOGIN: phone on file — but prefer password if this device was recently verified ──
      let freshEmp = match;
      try{ const fe = await fbGet('employees/'+match.id); if(fe && fe.phone) freshEmp = fe; }catch(e){}
      if(freshEmp.phone && freshEmp.phone.length === 10){
        restoreBtn();
        const savedPw = localStorage.getItem('mp_pw_'+match.id);
        let verifiedAt = 0;
        try{ verifiedAt = parseInt(localStorage.getItem('mp_device_verified_at')||'0',10); }catch(e){}
        const recentVerify = verifiedAt && (Date.now() - verifiedAt) < 30*24*60*60*1000; // 30 days
        const phoneMatch = (localStorage.getItem('mp_device_phone')||'').replace(/\D/g,'').endsWith(String(freshEmp.phone).slice(-10));
        // Friction reduction: known device + password → password screen (skip OTP)
        if(savedPw && recentVerify && phoneMatch){
          showPasswordLoginScreen(freshEmp, deviceId);
          return;
        }
        showOTPLoginScreen(freshEmp, deviceId);
        return;
      }

      restoreBtn();
      showLoginApprovalOverlay(match, null);
    } else {
      let regData=null;
      try{ regData=await fbGet('regRequests'); }catch(e){}
      const regsAll=regData?Object.values(regData):[];
      const existingReg=regsAll.find(r=>r.empId===code&&(r.company==='Man Power'||!r.company));

      if(existingReg){
        if(existingReg.status==='approved'){
          const fakeMatch={id:existingReg.linkedEmpId||code,name:existingReg.name,empId:code,sec:existingReg.sec||existingReg.dept||'MET'};
          restoreBtn(); showLoginApprovalOverlay(fakeMatch, existingReg); return;
        } else if(existingReg.status==='pending'){
          restoreBtn(); showPendingBox(); return;
        } else {
          showLoginErrStep(2,'❌ Registration अस्वीकार। +91-8929394920 पर संपर्क करें।');
          restoreBtn(); return;
        }
      }
      restoreBtn();
      showNewEmpRegistrationForm(code);
    }
  }catch(err){
    console.error('proceedFromCode error:',err);
    showLoginErrStep(2,'❌ Error: '+err.message);
    restoreBtn();
  }
}

async function tryWorkerLogin(){ await proceedFromCode(); }

let _loginApprovalKey=null;
let _loginApprovalTimeout=null;
let _loginApprovalPoller=null;

