function _sessionSecurityIds(){
  const mob = _normMobileKey(SESSION.mobile||SESSION.uid||'');
  const empObjId = SESSION.empObjId || '';
  const uid = empObjId || (mob ? ('m_'+mob) : 'user');
  return { mob, empObjId, uid, name: SESSION.name||'User' };
}

