// 🔑 MANAGER / MEMBER REGISTRATION APPROVALS (Admin Panel)
// ════════════════════════════════════════
function renderManagerApprovals(){
  const el=document.getElementById('mgrApprovalsSection');
  if(!el) return;
  fbGet('mobileUsers').then(data=>{
    if(!data){ el.innerHTML='<div class="empty-text" style="font-size:12px;padding:12px">कोई pending registration नहीं</div>'; return; }
    const entries=Object.entries(data).filter(([k,v])=>v.status==='pending'&&v.role==='manager');
    if(!entries.length){ el.innerHTML='<div class="empty-text" style="font-size:12px;padding:12px">कोई pending Manager registration नहीं</div>'; return; }
    el.innerHTML=entries.map(([mobile,u])=>`
      <div class="card" style="margin-bottom:10px">
        <div class="card-row">
          <div class="card-ico" style="background:rgba(249,115,22,.12)">👔</div>
          <div class="card-body">
            <div class="card-name">${u.name} <span style="font-size:10px;background:rgba(249,115,22,.15);color:#f97316;padding:2px 6px;border-radius:4px;margin-left:4px">MANAGER</span></div>
            <div class="card-sub">📱 ${u.mobile} &nbsp;·&nbsp; 🏢 ${u.company||'—'}</div>
            ${u.designation?'<div class="card-meta">'+u.designation+(u.department?' · '+u.department:'')+'</div>':''}
            <div class="card-meta">${new Date(u.registeredAt).toLocaleString('hi-IN')}</div>
          </div>
        </div>
        <div class="action-row">
          <button class="act-btn approve" onclick="approveMobileUser('${mobile}')">✅ Approve</button>
          <button class="act-btn reject"  onclick="rejectMobileUser('${mobile}','${u.name}')">❌ Reject</button>
        </div>
      </div>`).join('');
  });
}

async function approveMobileUser(mobile){
  try{
    await fbUpdate('mobileUsers/'+mobile,{status:'approved',approvedAt:new Date().toISOString(),approvedBy:SESSION.name});
    toast('✅ User approve हो गया!');
    renderManagerApprovals();
    renderMyTeamApprovals();
  }catch(e){ toast('❌ Error: '+e.message); }
}

async function rejectMobileUser(mobile,name){
  const ok=await confirmModal('Reject करें?','<b>'+name+'</b> का registration reject करें?','❌ Reject','रद्द');
  if(!ok) return;
  try{
    await fbUpdate('mobileUsers/'+mobile,{status:'rejected',rejectedAt:new Date().toISOString(),rejectedBy:SESSION.name});
    toast('❌ '+name+' का registration reject हो गया');
    renderManagerApprovals();
    renderMyTeamApprovals();
  }catch(e){ toast('❌ Error: '+e.message); }
}

// ── Manager approves their OWN pending team Members ──
function renderMyTeamApprovals(){
  const block=document.getElementById('myTeamApprovalsBlock');
  const el=document.getElementById('myTeamApprovalsSection');
  if(!block||!el) return;
  if(SESSION.role!=='manager'){ block.style.display='none'; return; }
  block.style.display='block';
  const myKey=(SESSION.mobile||'').replace('+91','').replace(/[^0-9]/g,'');
  fbGet('mobileUsers').then(data=>{
    if(!data){ el.innerHTML='<div class="empty-text" style="font-size:12px;padding:12px">कोई pending member नहीं</div>'; return; }
    const entries=Object.entries(data).filter(([k,v])=>v.status==='pending'&&v.role==='member'&&v.managerId===myKey);
    if(!entries.length){ el.innerHTML='<div class="empty-text" style="font-size:12px;padding:12px">कोई pending member नहीं</div>'; return; }
    el.innerHTML=entries.map(([mobile,u])=>`
      <div class="card" style="margin-bottom:10px">
        <div class="card-row">
          <div class="card-ico" style="background:rgba(96,165,250,.12)">👤</div>
          <div class="card-body">
            <div class="card-name">${u.name} <span style="font-size:10px;background:rgba(96,165,250,.15);color:#60a5fa;padding:2px 6px;border-radius:4px;margin-left:4px">MEMBER</span></div>
            <div class="card-sub">📱 ${u.mobile} &nbsp;·&nbsp; 🏢 ${u.company||'—'}</div>
            <div class="card-meta">${new Date(u.registeredAt).toLocaleString('hi-IN')}</div>
          </div>
        </div>
        <div class="action-row">
          <button class="act-btn approve" onclick="approveMobileUser('${mobile}')">✅ Approve</button>
          <button class="act-btn reject"  onclick="rejectMobileUser('${mobile}','${u.name}')">❌ Reject</button>
        </div>
      </div>`).join('');
  });
}

// ── Admin: Managers & their Teams hierarchy view ──
function renderAdminTeamHierarchy(){
  const block=document.getElementById('adminTeamHierarchyBlock');
  const el=document.getElementById('adminTeamHierarchySection');
  if(!block||!el) return;
  if(!isAdmin()){ block.style.display='none'; return; }
  block.style.display='block';
  fbGet('mobileUsers').then(data=>{
    if(!data){ el.innerHTML='<div class="empty-text" style="font-size:12px;padding:12px">कोई registered Manager नहीं</div>'; return; }
    try{ _cache.mobileUsers = data; }catch(e){}
    // Always start from full list — do NOT pre-filter members by company (they may have blank/different casing)
    const allRaw = Object.entries(data);
    const viewCid = SESSION.viewCompanyId || 'ALL';
    const mgrKeyNorm = (k)=> (typeof _normMobileKey==='function' ? _normMobileKey(k) : String(k||'').replace(/\D/g,'').slice(-10));

    // Managers: match company case-insensitively (empty company still shows when filter is ALL only)
    const managers = allRaw.filter(([k,v])=>{
      if(v.role!=='manager' || v.status==='rejected') return false;
      if(!viewCid || viewCid==='ALL') return true;
      const n = _normCompanyId(v.company);
      const vcid = _normCompanyId(viewCid);
      // Manager must belong to selected company (or have no company set but we still show if name soft-match)
      return n === vcid || n === 'default';
    });
    const managerKeys = new Set(managers.map(([k])=>mgrKeyNorm(k)));
    // Also keep original keys for display
    const managerKeySet = new Set(managers.map(([k])=>k));

    // Uncategorised: members not linked to a visible manager
    const uncategorised = allRaw.filter(([k,v])=>{
      if(v.role!=='member' || v.status==='rejected') return false;
      if(!_companyMatchesView(v.company, viewCid)) return false;
      const mk = mgrKeyNorm(v.managerId);
      if(!v.managerId) return true;
      return !managerKeys.has(mk) && !managerKeySet.has(v.managerId);
    });

    if(!managers.length && !uncategorised.length){
      el.innerHTML='<div class="empty-text" style="font-size:12px;padding:12px">कोई registered Manager/Member नहीं</div>'; return;
    }

    let html=managers.map(([mgrKey,mgr])=>{
      const mk = mgrKeyNorm(mgrKey);
      // Members under this manager by mobile key (normalized) — company filter is soft
      const members=allRaw.filter(([k,v])=>{
        if(v.role!=='member' || v.status==='rejected') return false;
        const mid = mgrKeyNorm(v.managerId);
        if(!(mid === mk || v.managerId === mgrKey)) return false;
        return _companyMatchesView(v.company, viewCid);
      });
      const statusBadge=_mobileStatusBadge(mgr);
      const membersHtml=members.length?members.map(([memKey,mem])=>`
          <div style="padding:10px 12px;border-top:1px solid var(--border2);display:flex;align-items:center;gap:8px">
            <div style="flex:1;min-width:0">
              <div style="font-size:13px;font-weight:700;color:var(--text)">&#128100; ${mem.name}</div>
              <div style="font-size:11px;color:#64748b">📱 ${mem.mobile}</div>
            </div>
            ${_mobileStatusBadge(mem)}
            ${_mobileActionButtons(memKey,mem.name,mem.status)}
          </div>`).join(''):
        '<div style="padding:10px 12px;border-top:1px solid var(--border2);font-size:11px;color:#64748b">इस Manager के अंतर्गत कोई Member नहीं</div>';
      return `
      <div class="card" style="margin-bottom:12px;padding:0;overflow:hidden">
        <div style="padding:12px;background:rgba(249,115,22,.06);display:flex;align-items:center;gap:8px">
          <div style="flex:1;min-width:0">
            <div style="font-size:14px;font-weight:900;color:var(--text)">👔 ${mgr.name} <span style="font-size:10px;color:#64748b;font-weight:600">(${members.length} members)</span></div>
            <div style="font-size:11px;color:#64748b">📱 ${mgr.mobile} &nbsp;·&nbsp; 🏢 ${mgr.company||'—'}</div>
          </div>
          ${statusBadge}
          ${_mobileActionButtons(mgrKey,mgr.name,mgr.status)}
        </div>
        ${membersHtml}
      </div>`;
    }).join('');

    // ── Uncategorised Members: no Manager, or their Manager was removed/rejected ──
    if(uncategorised.length){
      html+=`
      <div style="font-size:12px;font-weight:800;color:#f97316;letter-spacing:.5px;margin:18px 0 8px">
        &#10067; UNCATEGORISED MEMBERS <span style="color:#64748b;font-weight:600">(${uncategorised.length})</span>
      </div>
      <div class="card" style="margin-bottom:12px;padding:0;overflow:hidden;border-color:rgba(249,115,22,.3)">
        ${uncategorised.map(([memKey,mem])=>`
          <div style="padding:10px 12px;border-top:1px solid var(--border2);display:flex;align-items:center;gap:8px">
            <div style="flex:1;min-width:0">
              <div style="font-size:13px;font-weight:700;color:var(--text)">&#128100; ${mem.name}</div>
              <div style="font-size:11px;color:#64748b">📱 ${mem.mobile} &nbsp;·&nbsp; 🏢 ${mem.company||'—'}</div>
            </div>
            ${_mobileStatusBadge(mem)}
            ${_mobileActionButtons(memKey,mem.name,mem.status)}
          </div>`).join('').replace('border-top:1px solid var(--border2);','')}
      </div>`;
    }

    el.innerHTML=html;
  });
}

function _mobileStatusBadge(u){
  const map={approved:['#22c55e','Active'],revoked:['#f43f5e','Revoked'],pending:['#f97316','Pending']};
  const [color,label]=map[u.status]||['#64748b',u.status||'—'];
  let extra='';
  if(u.status==='approved'&&u.validTill){
    const daysLeft=Math.ceil((new Date(u.validTill)-new Date())/86400000);
    extra=daysLeft>=0?` · ${daysLeft}d left`:' · Expired';
  }
  return `<span style="font-size:10px;background:${color}22;color:${color};padding:3px 7px;border-radius:5px;font-weight:700;white-space:nowrap">${label}${extra}</span>`;
}

function _mobileActionButtons(key,name,status){
  const safeName=name.replace(/'/g,"\\'");
  if(status==='revoked'){
    return `<button onclick="adminRestoreMobileUser('${key}','${safeName}')" style="font-size:10px;padding:5px 8px;border-radius:6px;border:1px solid rgba(34,197,94,.3);background:rgba(34,197,94,.08);color:#22c55e;font-weight:700;cursor:pointer;white-space:nowrap">↺ Restore</button>`;
  }
  if(status==='approved'){
    return `<div style="display:flex;gap:4px">
      <button onclick="adminExtendMobileValidity('${key}','${safeName}',30)" style="font-size:10px;padding:5px 8px;border-radius:6px;border:1px solid rgba(96,165,250,.3);background:rgba(96,165,250,.08);color:#60a5fa;font-weight:700;cursor:pointer;white-space:nowrap">+30d</button>
      <button onclick="adminRevokeMobileUser('${key}','${safeName}')" style="font-size:10px;padding:5px 8px;border-radius:6px;border:1px solid rgba(244,63,94,.3);background:rgba(244,63,94,.08);color:#f43f5e;font-weight:700;cursor:pointer;white-space:nowrap">🚫 Revoke</button>
    </div>`;
  }
  return '';
}

async function adminRevokeMobileUser(mobile,name){
  const ok=await confirmModal('Access Revoke करें?',`<b>${name}</b> की App access revoke होगी। वो login नहीं कर पाएंगे।`,'🚫 हाँ, Revoke करें','रद्द करें');
  if(!ok) return;
  try{
    await fbUpdate('mobileUsers/'+mobile,{status:'revoked',revokedBy:SESSION.name,revokedAt:new Date().toISOString()});
    toast('🚫 '+name+' की access revoke कर दी');
    renderAdminTeamHierarchy();
  }catch(e){ toast('❌ Error: '+e.message); }
}

async function adminRestoreMobileUser(mobile,name){
  try{
    await fbUpdate('mobileUsers/'+mobile,{status:'approved',restoredBy:SESSION.name,restoredAt:new Date().toISOString()});
    toast('✅ '+name+' की access restore हो गई');
    renderAdminTeamHierarchy();
  }catch(e){ toast('❌ Error: '+e.message); }
}

async function adminExtendMobileValidity(mobile,name,days){
  try{
    const rec=await fbGet('mobileUsers/'+mobile).catch(()=>null);
    const base=rec&&rec.validTill&&new Date(rec.validTill)>new Date()?new Date(rec.validTill):new Date();
    const newExp=new Date(base.getTime()+days*86400000);
    await fbUpdate('mobileUsers/'+mobile,{validTill:newExp.toISOString(),extendedBy:SESSION.name,extendedAt:new Date().toISOString()});
    toast('✅ '+name+' की expiry '+days+' दिन बढ़ाई → '+newExp.toLocaleDateString('en-IN'));
    renderAdminTeamHierarchy();
  }catch(e){ toast('❌ Error: '+e.message); }
}


// ── Login Request Approval (new flow) ──
async function approveLoginRequest(reqKey, empObjId, deviceId, empName){
  try{
    if(typeof _ensureWriteAuth==='function'){
      const ok = await _ensureWriteAuth();
      if(!ok){ toast('❌ Login/auth required — try again'); return; }
    }
    // Get login request data to fetch selfieUrl and phone
    let selfieUrl = '';
    let phone = '';
    try{
      const req = await fbGet('loginRequests/'+reqKey);
      selfieUrl = req?.selfieUrl || '';
      phone = req?.phone || '';
    }catch(e2){}

    await fbUpdate('loginRequests/'+reqKey, {
      status:'approved', approvedBy:SESSION.name, approvedAt:new Date().toISOString()
    });
    if(empObjId && deviceId){
      await fbUpdate('deviceApprovals/'+empObjId,{
        approvedDeviceId:deviceId, approvedAt:new Date().toISOString(),
        validTill:new Date(Date.now()+365*86400000).toISOString(),
        empName, approvedBy:SESSION.name
      });
    }
    // Save selfie photo to employee record so it shows in team section
    if(empObjId && selfieUrl){
      try{ await fbUpdate('employees/'+empObjId, { photo: selfieUrl }); }catch(e2){}
    }
    // Save phone number to employee record so WhatsApp notifications work
    if(empObjId && phone && phone.length === 10){
      try{ await fbUpdate('employees/'+empObjId, { phone: phone }); }catch(e2){}
    }
    toast('✅ '+empName+' ka login approve ho gaya!');
    renderPending();
  }catch(e){
    toast('❌ Error: '+e.message);
  }
}

async function rejectLoginRequest(reqKey, empName){
  try{
    if(typeof _ensureWriteAuth==='function'){ const ok=await _ensureWriteAuth(); if(!ok){ toast('❌ Auth required'); return; } }
    await fbUpdate('loginRequests/'+reqKey, {
      status:'rejected', rejectedBy:SESSION.name, rejectedAt:new Date().toISOString()
    });
    toast('❌ '+empName+' ka login reject kiya gaya');
    renderPending();
  }catch(e){
    toast('❌ Error: '+e.message);
  }
}

function renderPending(){
  try{ if(typeof renderDeviceTransferRequests==='function') renderDeviceTransferRequests(); }catch(e){}
  // ── Login Requests (Admin/Manager) — includes manager_login_approval for team members ──
  if(isAdminOrMgr()){
    const lrEl = document.getElementById('pendingLoginRequests');
    // Show pending block for managers + admins (login requests live here)
    try{
      const adminBlock = document.getElementById('adminOnlyPendingBlock');
      if(adminBlock && (isAdmin() || isMgr())) adminBlock.style.display='block';
    }catch(e){}
    fbGet('loginRequests').then(data=>{
      let reqs = data ? Object.entries(data).filter(([k,v])=>v && v.status==='pending') : [];
      // Managers only see their team / phone-matched requests
      if(isMgr() && !isAdmin()){
        reqs = reqs.filter(([k,v])=>{
          if(v.type==='manager_login_approval'){
            return _isMyTeamLoginRequest(v);
          }
          if(v.type==='device_transfer') return false; // handled in deviceTransferRequests for self
          return false; // managers do not see other login types unless admin
        });
      }
      if(!lrEl) return;
      if(!reqs.length){
        lrEl.innerHTML='<div class="empty" style="padding:16px"><div class="empty-text" style="font-size:12px">&#128100; कोई Login Request नहीं</div></div>'; return;
      }
      lrEl.innerHTML = reqs.map(([k,v])=>{
        const isMgrAppr = v.type==='manager_login_approval';
        return `
        <div class="card" style="border-left:3px solid #f97316">
          <div class="card-row">
            <div class="card-ico" style="background:rgba(249,115,22,.15)">&#128241;</div>
            <div class="card-body">
              <div class="card-name">${v.empName||v.phone||'Member'}</div>
              <div class="card-sub">${isMgrAppr?'Manager login approval':('Code: '+(v.empId||'—'))}${v.phone?' · 📱 '+v.phone:''}</div>
              <div class="card-meta">${v.requestedAt?new Date(v.requestedAt).toLocaleString('hi-IN'):''}</div>
              ${isMgrAppr?'<div style="font-size:11px;color:#38bdf8;font-weight:700">Registered member — approve to login without OTP</div>':''}
              ${v.isNewReg?'<div style="font-size:11px;color:#f97316;font-weight:700">&#128100; Newly Registered Employee</div>':''}
              ${v.selfieUrl?`<div style="margin-top:8px;display:flex;align-items:center;gap:8px"><img src="${v.selfieUrl}" style="width:72px;height:72px;border-radius:10px;object-fit:cover;border:2px solid rgba(249,115,22,.5);cursor:pointer" onclick="window.open('${v.selfieUrl}','_blank')"><span style="font-size:11px;color:#94a3b8">📸 Selfie</span></div>`:''}
            </div>
          </div>
          <div class="action-row">
            <button class="act-btn approve" onclick="${isMgrAppr?`approveManagerLoginRequest('${k}')`:`approveLoginRequest('${k}','${v.empObjId||''}','${v.deviceId||''}','${(v.empName||'').replace(/'/g,"\'")}')`}">&#9989; Approve</button>
            <button class="act-btn reject"  onclick="${isMgrAppr?`rejectManagerLoginRequest('${k}')`:`rejectLoginRequest('${k}','${(v.empName||'').replace(/'/g,"\'")}')`}">&#10060; Reject</button>
          </div>
        </div>`;
      }).join('');
    }).catch(()=>{ if(lrEl) lrEl.innerHTML=''; });
  }
  // Shift change requests (members → manager)
  try{ _renderPendingShiftChangeRequests(); }catch(e){}
  // Device change requests
  renderPendingDevices();
  // Registration requests
  const regs=getRegs().filter(r=>r.status==='pending');
  document.getElementById('pendingRegs').innerHTML = regs.length ? regs.map(r=>`
    <div class="card">
      <div class="card-row">
        <div class="card-ico" style="background:${r.isExternal?'rgba(56,189,248,.12)':'var(--daybg)'}">${r.isExternal?(r.companyIco||'🏢'):'👤'}</div>
        <div class="card-body">
          <div class="card-name">${r.name||r.empId}</div>
          <div class="card-sub">Code: ${r.empId} · ${secName(r.sec)||r.dept||''} ${r.phone?'· 📱 '+r.phone:''}</div>
          <div class="card-meta">${new Date(r.requestedAt).toLocaleString('hi-IN')}</div>
          ${r.selfieUrl?`<div style="margin-top:8px;display:flex;align-items:center;gap:8px"><img src="${r.selfieUrl}" style="width:72px;height:72px;border-radius:10px;object-fit:cover;border:2px solid rgba(249,115,22,.5);cursor:pointer" onclick="window.open('${r.selfieUrl}','_blank')"><span style="font-size:11px;color:#94a3b8">📸 Selfie<br><span style="font-size:10px;color:#64748b">Tap to zoom</span></span></div>`:'<div style="margin-top:6px;font-size:11px;color:#f43f5e">⚠️ कोई Selfie नहीं</div>'}
        </div>
      </div>
      <div class="action-row">
        <button class="act-btn approve" onclick="actReg('${r._key||r.id}','approved')">✅ मंजूर करें</button>
        <button class="act-btn reject"  onclick="actReg('${r._key||r.id}','rejected')">❌ अस्वीकार</button>
      </div>
    </div>`).join('') :
    '<div class="empty"><div class="empty-icon">👤</div><div class="empty-text">कोई नया रजिस्ट्रेशन नहीं</div></div>';

  // Pending leaves
  const leaves=getLeaves().filter(l=>l.status==='pending');
  const _pgLeave=document.getElementById('pendingLeaves');
  if(_pgLeave && !_pgLeave.previousElementSibling?.classList?.contains('pending-group-title')){
    const h=document.createElement('div'); h.className='pending-group-title'; h.textContent='Leave requests';
    _pgLeave.parentNode.insertBefore(h, _pgLeave);
  }
  document.getElementById('pendingLeaves').innerHTML = leaves.length ? leaves.map(l=>`
    <div class="card">
      <div class="card-row">
        <div class="card-ico" style="background:var(--daybg)">📅</div>
        <div class="card-body">
          <div class="card-name">${l.empName}</div>
          <div class="card-sub">${l.leaveType} · ${l.days} दिन${l.coffDate?` · <span style="color:#f97316">📅 Shift था: ${l.coffDate}</span>`:''}</div>
          <div class="card-meta">${fmtDate(l.from)}${l.from!==l.to?' → '+fmtDate(l.to):''}</div>
          ${l.reason?`<div style="margin-top:6px;padding:7px 10px;background:var(--card2);border-left:3px solid var(--day);border-radius:0 8px 8px 0;font-size:12px;color:var(--text);font-weight:600">📝 ${escHtml(l.reason)}</div>`:'<div style="margin-top:4px;font-size:11px;color:var(--lv);font-weight:600">⚠️ कारण नहीं दिया गया</div>'}
        </div>
      </div>
      <div class="action-row">
        <button type="button" class="act-btn approve" data-leave-key="${l._key||l.id||''}" onclick="event.stopPropagation();actLeave(this.getAttribute('data-leave-key')||'','approved')">✅ Approve</button>
        <button type="button" class="act-btn reject"  data-leave-key="${l._key||l.id||''}" onclick="event.stopPropagation();actLeave(this.getAttribute('data-leave-key')||'','rejected')">❌ Reject</button>
      </div>
    </div>`).join('') :
    '<div class="empty"><div class="empty-icon">🌴</div><div class="empty-text">कोई छुट्टी पेंडिंग नहीं</div></div>';

  // Pending reports
  const reports=getReports().filter(r=>r.status==='pending');
  document.getElementById('pendingReports').innerHTML = reports.length ? reports.map(r=>{
    const rt=REPORT_TYPES[r.type]||REPORT_TYPES.ncr;
    return `<div class="card">
      <div class="card-row">
        <div class="card-ico" style="background:${rt.bg}">${rt.ico}</div>
        <div class="card-body">
          <div class="card-name">${r.aboutName}</div>
          <div class="card-sub">${rt.label} · ${fmtDate(r.date)}</div>
          <div class="card-meta">${r.description}</div>
          <div class="card-meta">रिपोर्ट: ${r.reportedByName}</div>
        </div>
      </div>
      <div class="action-row">
        <button class="act-btn approve" onclick="actReport('${r._key}','approved')">✅ मंजूर</button>
        <button class="act-btn reject"  onclick="actReport('${r._key}','rejected')">❌ अस्वीकार</button>
      </div>
    </div>`;
  }).join('') :
  '<div class="empty"><div class="empty-icon">📋</div><div class="empty-text">कोई रिपोर्ट पेंडिंग नहीं</div></div>';

  updatePendingBadge();
}

async function actReg(key, status){
  const regs = getRegs();
  let reg = regs.find(r=>r._key===key||r.id===key);

  // If not in local cache, fetch directly from Firebase
  if(!reg){
    try{
      const snap = await fbGet('regRequests/'+key);
      if(snap) reg = {...snap, _key:key};
    }catch(e){}
  }

  if(status === 'approved'){
    if(!reg){ toast('❌ Data नहीं मिला — page refresh करें'); return; }
    const displayName = (reg.name && reg.name !== reg.empId) ? reg.name : reg.empId;
    const newId = 'e' + Date.now().toString(36);
    const newEmp = {
      id: newId,
      name: displayName,
      empId: reg.empId,
      sec: reg.sec || reg.dept || 'MET',
      mc: reg.mc || '—',
      resp: 'Operation',
      woff: 'SUN',
      status: 'active',
      phone: reg.phone || '',
      ms: Array(31).fill('D')
    };
    try{
      await fbUpdate('employees/'+newId, newEmp);
    }catch(e){
      toast('❌ Employee add नहीं हुआ: '+e.message); return;
    }
    if(reg.passHash){
      try{ await fbSet('workerPasswords/'+newId, reg.passHash); }catch(e){}
    }
    await fbUpdate('regRequests/'+key, {
      status:'approved',
      actionAt: new Date().toISOString(),
      linkedEmpId: newId,
      approvedBy: SESSION.name || 'admin'
    });
    // In-app notification to new employee
    try{
      await fbPush('userNotifications/'+newId, {
        title: '✅ Registration Approved!',
        body: 'आपका registration approve हो गया। अब login करें।',
        read: false,
        at: new Date().toISOString()
      });
    }catch(e){}
    toast('✅ '+displayName+' ('+reg.empId+') approved! Team में add हो गए।');
  } else {
    await fbUpdate('regRequests/'+key, {
      status, actionAt: new Date().toISOString(),
      actionBy: SESSION.name || 'admin'
    });
    toast('❌ रजिस्ट्रेशन अस्वीकार किया');
  }
  renderPending();
}

// ════════════════════════════════════════
// TEAM
// ════════════════════════════════════════
let _teamSec='ALL';
function setTeamSec(s,el){ _teamSec=s; document.querySelectorAll('#teamFilter .chip').forEach(c=>c.classList.remove('on')); el.classList.add('on'); renderTeam(); document.getElementById('tab-team')?.scrollIntoView({behavior:'smooth',block:'start'}); }

function classifyResponsibility(resp){
  const r=(resp||'').toString().toLowerCase();
  if(/manag/.test(r)) return _lang==='en'?'Managers':'Managers';
  if(/engineer/.test(r)) return _lang==='en'?'Engineers':'Engineers';
  if(/assist/.test(r)) return _lang==='en'?'Assistants':'Assistants';
  if(/operat/.test(r)) return _lang==='en'?'Operators':'Operators';
  return _lang==='en'?'Others':'Others';
}

function renderTeam(search=''){
  try{
    const host = document.getElementById('teamPage') || document.getElementById('teamList') || document.getElementById('teamBody');
    if(host && !document.getElementById('mgrEmptyTeamBanner')){
      const h = _managerEmptyTeamHtml();
      if(h){ const d=document.createElement('div'); d.id='mgrEmptyTeamBanner'; d.innerHTML=h; host.prepend(d); }
    } else if(host && document.getElementById('mgrEmptyTeamBanner')){
      const h = _managerEmptyTeamHtml();
      if(!h) document.getElementById('mgrEmptyTeamBanner').remove();
      else document.getElementById('mgrEmptyTeamBanner').innerHTML=h;
    }
  }catch(e){}

  _renderDynamicChips('teamFilter', _buildMachineChips('team'), _teamSec, 'setTeamSec');
  document.getElementById('teamAddBtn').innerHTML = isAdminOrMgr()
    ? `<div style="display:flex;gap:8px;margin-bottom:14px">
        <button class="action-primary team-btn-add" style="flex:1;background:linear-gradient(135deg,#ea580c,#c2410c);color:#fff;border:none;font-weight:900;font-size:14px;padding:14px 12px;border-radius:12px;box-shadow:0 2px 8px rgba(234,88,12,.35)" onclick="openAddEmpForm()">+ नया कर्मचारी जोड़ें</button>
        <button class="action-primary team-btn-import" style="flex:1;background:linear-gradient(135deg,#16a34a,#15803d);color:#fff;border:none;font-weight:900;font-size:14px;padding:14px 12px;border-radius:12px;box-shadow:0 2px 8px rgba(22,163,74,.35)" onclick="openBulkImportTeam()">📊 Excel से Team Import</button>
      </div>${SESSION.role==='manager'?`<button class="action-primary team-btn-delete" style="width:100%;margin-bottom:14px;background:linear-gradient(135deg,#e11d48,#be123c);color:#fff;border:none;font-weight:900;font-size:14px;padding:14px 12px;border-radius:12px;box-shadow:0 2px 8px rgba(225,29,72,.3)" onclick="startDeleteAllMembersFlow()">🗑️ सभी Members Delete करें (OTP verify)</button>`:''}` : '';

  // Active employees only — those in the shift schedule (have ms array)
  let list = getEmps().filter(e => e.status !== 'resigned' && e.status !== 'left' && Array.isArray(e.ms) && e.ms.length > 0);
  const totalAll = list.length;
  if(_teamSec !== 'ALL') list = list.filter(e => e.sec === _teamSec);
  if(search) list = list.filter(e => e.name.toLowerCase().includes(search.toLowerCase()) || (e.empId||'').includes(search));

  // Show total count
  const totalLabel = _teamSec === 'ALL' 
    ? `कुल <b style="color:var(--m1)">${list.length}</b> कर्मचारी (Active — Schedule में)` 
    : `${secName(_teamSec)}: <b style="color:var(--m1)">${list.length}</b> / ${totalAll} कुल`;
  
  const countDiv = document.getElementById('teamCount');
  if(countDiv) countDiv.innerHTML = totalLabel;
  else {
    const tc = document.createElement('div');
    tc.id = 'teamCount';
    tc.style.cssText = 'font-size:14px;color:var(--muted2);margin-bottom:10px;font-weight:700';
    tc.innerHTML = totalLabel;
    const teamFilter = document.getElementById('teamFilter');
    if(teamFilter) teamFilter.after(tc);
  }

  // Build groups in fixed order: M1 → M2 → S1 → S2 → SUP → MGR → OTHER
  const SEC_ORDER = ['M1','M2','S1','S2','SUP','MGR'];
  const groups = {};
  SEC_ORDER.forEach(k => { groups[k] = []; });
  list.forEach(e => {
    const k = e.sec || 'OTHER';
    if(!groups[k]) groups[k] = [];
    groups[k].push(e);
  });

  let html = '';
  // Render in fixed order, skip empty sections
  const renderOrder = [...SEC_ORDER, ...Object.keys(groups).filter(k => !SEC_ORDER.includes(k))];
  renderOrder.forEach(sec => {
    const members = groups[sec];
    if(!members || !members.length) return;
    const s = getSectionMeta(sec);
    html += `<div class="stitle">${s.icon||'👤'} ${s.hi||sec} <span style="color:${s.color||'#94a3b8'};font-size:13px">(${members.length})</span></div>`;
    // Sub-group by Responsibility: Operators → Assistants → Engineers → Managers → Others
    const RESP_ORDER=['Operators','Assistants','Engineers','Managers','Others'];
    const respGroups={};
    RESP_ORDER.forEach(k=>{ respGroups[k]=[]; });
    members.forEach(e=>respGroups[classifyResponsibility(e.resp)].push(e));
    RESP_ORDER.forEach(respKey=>{
      const subMembers=respGroups[respKey];
      if(!subMembers.length) return;
      if(RESP_ORDER.filter(k=>respGroups[k].length).length>1){
        html += `<div style="font-size:11px;font-weight:800;color:#64748b;margin:8px 0 4px 4px;letter-spacing:.5px">${respKey} (${subMembers.length})</div>`;
      }
      html += _renderTeamMemberCards(subMembers, s);
    });
    return;
  });
  function _renderTeamMemberCards(members, s){
    return members.map(e=>{
      const ini=e.name.split(' ').map(n=>n[0]).join('').substring(0,2);
      const sh=getShift(e,TODAY_STR);
      const isMe=e.id===SESSION.empObjId;
      const ncrs=getNcrForEmp(e.id);
      const ncrBadge = ncrs.length>0
        ? `<span onclick="showEmpNcrs('${e.id}')" style="font-size:10px;font-weight:900;background:rgba(244,63,94,.15);color:var(--lv);border:1px solid rgba(244,63,94,.35);border-radius:5px;padding:2px 7px;cursor:pointer;flex-shrink:0">⚠️ NCR: ${ncrs.length}</span>` : '';
      const avatarHtml = e.photo
        ? `<img src="${e.photo}" style="width:44px;height:44px;border-radius:10px;object-fit:cover;border:2px solid ${s.color||'rgba(255,255,255,.2)'};flex-shrink:0;cursor:pointer" onclick="window.open('${e.photo}','_blank')">`
        : `<div style="width:44px;height:44px;border-radius:10px;background:${s.bg||'rgba(148,163,184,.1)'};display:flex;align-items:center;justify-content:center;font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:19px;color:${s.color||'#fff'};flex-shrink:0">${ini}</div>`;
      return `<div class="card" id="teamcard_${e.id}" style="${isMe?'border-color:rgba(249,115,22,.4);background:rgba(249,115,22,.04);':''}">
        <div class="card-row">
          ${avatarHtml}
          <div class="card-body">
            <div class="card-name">${e.name}${isMe?' <span style="font-size:10px;color:var(--m1)">(आप)</span>':''}</div>
            <div class="card-sub">${e.empId||'—'} · ${e.mc||'—'} · ${e.resp||'—'}${e.designation?` · <span style="color:var(--desig-color,#7c3aed)">${escHtml(e.designation)}</span>`:''}</div>
            <div style="margin-top:5px;display:flex;align-items:center;gap:6px;flex-wrap:wrap">
              <span class="shc ${cellClass(sh)}">${cellDisp(sh)}</span>
              <span style="font-size:10px;color:var(--muted)">W-OFF: ${e.woff||'—'}</span>
              ${e.phone?`<span style="font-size:10px;color:var(--green)">📱 ${e.phone}</span>`:''}
              ${ncrBadge}
            </div>
            ${(()=>{const jd=getJoiningDate(e);return jd?`<div style="font-size:10px;color:var(--muted2);margin-top:3px">📅 Joining: <b style="color:var(--green)">${new Date(jd+'T00:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}</b></div>`:'';})()}
            ${(()=>{
              const showSalary = isAdmin() || (isMgr() && (_cache.settings?.showSalaryToManager === true));
              return showSalary && e.monthlySalary
                ? `<div style="font-size:10px;color:var(--muted2);margin-top:3px">💰 Salary: <b style="color:var(--salary-color,#d97706)">₹${Number(e.monthlySalary).toLocaleString('en-IN')}/month</b></div>`
                : '';
            })()}
            ${isAdmin()?`<div id="devinfo_${e.id}" style="margin-top:6px;font-size:11px;color:var(--muted2)">⏳ device info...</div>`:(isMgr()?`<div id="devinfo_${e.id}" style="margin-top:6px;font-size:11px;color:var(--muted2)">⏳ device info...</div>`:'')}
          </div>
          ${(isAdmin() || isMgr())?`<div style="display:flex;flex-direction:column;gap:5px;flex-shrink:0">
            <button class="act-btn edit" style="padding:7px 10px;font-size:11px" onclick="openEditEmpForm('${e.id}')" title="Edit">✏️</button>
            ${isAdminOrMgr()?`<button class="act-btn del"  style="padding:7px 10px;font-size:11px" onclick="confirmDelEmp('${e.id}','${e.name}')">🗑️</button>`:''}
            <button style="padding:7px 10px;font-size:11px;background:rgba(56,189,248,.1);border:1px solid rgba(56,189,248,.3);border-radius:7px;color:#38bdf8;cursor:pointer" onclick="openDeviceManager('${e.id}','${e.name}')">📱</button>
          </div>`:''}
        </div>
      </div>`;
    }).join('');
  }

  const el = document.getElementById('teamList');
  el.innerHTML = html || '<div class="empty"><div class="empty-icon">🔍</div><div class="empty-text">कोई कर्मचारी नहीं मिला</div></div>';

  // ── Left / Resigned Members Section ──
  // Merge: firebase leftEmployees path + status='resigned' employees from main table
  const leftSec = document.getElementById('leftMembersSection');
  if(leftSec){
    const shouldShow = (isAdmin() || isMgr()) && _teamSec === 'ALL' && !search;
    leftSec.style.display = shouldShow ? 'block' : 'none';
    if(shouldShow){
      // Also collect status='resigned' employees from main employees cache
      const resignedFromCache = getEmps().filter(e => e.status === 'resigned' || e.status === 'left');
      
      // Get count from firebase leftEmployees + cache resigned
      const countEl = document.getElementById('leftMemberCount');
      fbGet('leftEmployees').then(raw => {
        const fbCount = raw ? Object.keys(raw).length : 0;
        // Merged count: firebase left + cache resigned that aren't already in firebase left
        const totalLeft = fbCount + resignedFromCache.filter(e => {
          // Don't double-count if same empId exists in leftEmployees
          const empId = e.empId || e.id;
          return !raw || !Object.values(raw).some(v => v.empId === empId || v.empCode === empId);
        }).length;
        if(countEl) countEl.textContent = totalLeft || resignedFromCache.length;
      }).catch(()=>{ 
        if(countEl) countEl.textContent = resignedFromCache.length;
      });
    }
  }

  // Show Salary Cost section — Admin and Manager
  const scSec = document.getElementById('salaryCostSection');
  if(scSec){
    scSec.style.display = isAdminOrMgr() ? 'block' : 'none';
    if(isAdminOrMgr()){
      const monthInput = document.getElementById('salaryCostMonth');
      if(monthInput && !monthInput.value){
        const now = new Date();
        monthInput.value = now.getFullYear() + '-' + String(now.getMonth()+1).padStart(2,'0');
        renderSalaryCost();
      }
    }
  }

  // Load device info for each employee asynchronously (admin and manager)
  if(isAdminOrMgr()){
    list.forEach(e=>{ loadDeviceInfoForCard(e.id, e.name); });
  }
}

// ════════════════════════════════════════
// SALARY COST CALCULATOR — Admin only
// Formula: Net = Monthly Salary - (Ab days × Monthly Salary ÷ 26)
// window._manpowerCostData exported for future embedded app
// ════════════════════════════════════════
function renderSalaryCost(){
  if(!isAdminOrMgr()) return;
  const monthInput = document.getElementById('salaryCostMonth');
  const tableEl    = document.getElementById('salaryCostTable');
  if(!monthInput || !tableEl) return;

  const monthVal = monthInput.value;
  if(!monthVal){ tableEl.innerHTML='<div style="padding:16px;text-align:center;color:var(--muted2)">Month चुनें</div>'; return; }

  const [yr, mo] = monthVal.split('-').map(Number);
  const daysInMonth = new Date(yr, mo, 0).getDate();
  const allDates = [];
  for(let d = 1; d <= daysInMonth; d++){
    allDates.push(`${yr}-${String(mo).padStart(2,'0')}-${String(d).padStart(2,'0')}`);
  }

  const emps      = getEmps().filter(e => e.status !== 'resigned' && e.monthlySalary);
  const overrides = getOverrides();
  const schedules = getSchedules();

  const getShiftForCalc = (emp, date) => {
    const ovKey = emp.id + '_' + date;
    if(overrides[ovKey]) return overrides[ovKey];
    const sched = schedules[emp.id];
    if(sched && sched[date]) return sched[date];
    const dayOfMonth = new Date(date).getDate() - 1;
    if(emp.ms && emp.ms[dayOfMonth]) return emp.ms[dayOfMonth];
    return null;
  };

  const WORKING_DAYS = 26;
  const rows = [];
  let totalGross = 0, totalDeduct = 0, totalNet = 0;

  emps.forEach(emp => {
    const monthlySalary = Number(emp.monthlySalary) || 0;
    if(!monthlySalary) return;
    const perDaySalary = monthlySalary / WORKING_DAYS;
    let absentDays = 0;
    allDates.forEach(date => { if(getShiftForCalc(emp, date) === 'Ab') absentDays++; });
    const deduction = Math.round(perDaySalary * absentDays);
    const netSalary  = monthlySalary - deduction;
    totalGross  += monthlySalary;
    totalDeduct += deduction;
    totalNet    += netSalary;
    rows.push({ emp, monthlySalary, absentDays, deduction, netSalary, perDaySalary });
  });

  rows.sort((a,b) => {
    if(a.emp.sec !== b.emp.sec) return (a.emp.sec||'').localeCompare(b.emp.sec||'');
    return a.emp.name.localeCompare(b.emp.name);
  });

  // ── Export object for future embedded app ──
  window._manpowerCostData = {
    month: monthVal, year: yr, monthNum: mo,
    workingDays: WORKING_DAYS,
    totalGross, totalDeduct, totalNet,
    perEmployee: rows.map(r=>({
      id: r.emp.id, empId: r.emp.empId, name: r.emp.name, section: r.emp.sec,
      monthlySalary: r.monthlySalary, perDaySalary: Math.round(r.perDaySalary),
      absentDays: r.absentDays, deduction: r.deduction, netSalary: r.netSalary,
    })),
    generatedAt: new Date().toISOString(), generatedBy: SESSION.name
  };

  // ── Summary cards ──
  const fmt = n => '₹' + Math.round(n).toLocaleString('en-IN');
  const scG = document.getElementById('scTotalGross');
  const scD = document.getElementById('scTotalDeduct');
  const scN = document.getElementById('scTotalNet');
  if(scG) scG.textContent = fmt(totalGross);
  if(scD) scD.textContent = fmt(totalDeduct);
  if(scN) scN.textContent = fmt(totalNet);

  if(rows.length === 0){
    tableEl.innerHTML = `<div style="padding:20px;text-align:center;color:var(--muted2);font-size:13px">
      ⚠️ किसी employee की Monthly Salary upload नहीं है।<br>
      <span style="font-size:11px">Team tab → Excel Update → Monthly Salary column add करें</span>
    </div>`;
    return;
  }

  const monthName = new Date(yr, mo-1, 1).toLocaleDateString('en-IN',{month:'long',year:'numeric'});
  let html = `
    <div style="padding:10px 12px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between">
      <div style="font-size:11px;font-weight:800;color:var(--muted2)">${monthName} · ${rows.length} Employees</div>
      <div style="font-size:10px;color:var(--muted)">26 working days</div>
    </div>
    <div style="overflow-x:auto">
    <table style="width:100%;border-collapse:collapse;font-size:11px;min-width:480px">
      <thead>
        <tr style="background:var(--card2)">
          <th style="padding:8px 10px;text-align:left;color:var(--muted2);font-size:10px">Employee</th>
          <th style="padding:8px 6px;text-align:right;color:#fbbf24;font-size:10px">Gross</th>
          <th style="padding:8px 6px;text-align:center;color:var(--lv);font-size:10px">Ab Days</th>
          <th style="padding:8px 6px;text-align:right;color:var(--lv);font-size:10px">Deduction</th>
          <th style="padding:8px 10px;text-align:right;color:var(--green);font-size:10px">Net Pay</th>
        </tr>
      </thead>
      <tbody>`;

  let lastSec = '';
  rows.forEach(r => {
    if(r.emp.sec !== lastSec){
      lastSec = r.emp.sec;
      const s = SEC[r.emp.sec] || {hi:r.emp.sec, color:'#94a3b8'};
      html += `<tr style="background:var(--bg2)"><td colspan="5" style="padding:5px 10px;font-size:9px;font-weight:800;color:${s.color};letter-spacing:1.5px;text-transform:uppercase">${s.hi||r.emp.sec}</td></tr>`;
    }
    const ab = r.absentDays > 0;
    html += `<tr style="border-bottom:1px solid var(--border);${ab?'background:rgba(244,63,94,.03)':''}">
      <td style="padding:8px 10px">
        <div style="font-size:11px;font-weight:700;color:var(--text)">${escHtml(r.emp.name)}</div>
        <div style="font-size:9px;color:var(--muted)">${r.emp.empId||'—'}</div>
      </td>
      <td style="padding:8px 6px;text-align:right;color:#fbbf24;font-weight:700">₹${r.monthlySalary.toLocaleString('en-IN')}</td>
      <td style="padding:8px 6px;text-align:center">${ab?`<span style="background:rgba(244,63,94,.15);color:var(--lv);border-radius:5px;padding:2px 8px;font-weight:800">${r.absentDays}</span>`:`<span style="color:var(--muted)">0</span>`}</td>
      <td style="padding:8px 6px;text-align:right;color:${ab?'var(--lv)':'var(--muted)'}">${ab?`−₹${r.deduction.toLocaleString('en-IN')}`:'—'}</td>
      <td style="padding:8px 10px;text-align:right;font-weight:800;color:${ab?'var(--green)':'var(--muted2)'}">₹${r.netSalary.toLocaleString('en-IN')}</td>
    </tr>`;
  });

  const totalAb = rows.reduce((s,r)=>s+r.absentDays,0);
  html += `</tbody>
    <tfoot>
      <tr style="background:var(--card2);border-top:2px solid var(--border2)">
        <td style="padding:10px 10px;font-size:12px;font-weight:900;color:var(--text)">TOTAL (${rows.length})</td>
        <td style="padding:10px 6px;text-align:right;font-size:12px;font-weight:900;color:#fbbf24">₹${totalGross.toLocaleString('en-IN')}</td>
        <td style="padding:10px 6px;text-align:center;font-size:12px;font-weight:900;color:var(--lv)">${totalAb}</td>
        <td style="padding:10px 6px;text-align:right;font-size:12px;font-weight:900;color:var(--lv)">−₹${totalDeduct.toLocaleString('en-IN')}</td>
        <td style="padding:10px 10px;text-align:right;font-size:12px;font-weight:900;color:var(--green)">₹${totalNet.toLocaleString('en-IN')}</td>
      </tr>
    </tfoot>
    </table></div>`;

  tableEl.innerHTML = html;
}

function exportSalaryCost(){
  if(!window._manpowerCostData){ toast('⚠️ पहले month select करें'); return; }
  const d = window._manpowerCostData;
  const monthName = new Date(d.year, d.monthNum-1, 1).toLocaleDateString('en-IN',{month:'long',year:'numeric'});
  let csv = `Manpower Cost Report — ${monthName}\n`;
  csv += `Generated: ${new Date(d.generatedAt).toLocaleString('en-IN')} by ${d.generatedBy}\n`;
  csv += `Working Days Basis: ${d.workingDays}\n\n`;
  csv += `Employee Code,Name,Section,Monthly Salary,Per Day Salary,Absent Days,Deduction,Net Payable\n`;
  d.perEmployee.forEach(r => {
    csv += `${r.empId},${r.name},${r.section},${r.monthlySalary},${r.perDaySalary},${r.absentDays},${r.deduction},${r.netSalary}\n`;
  });
  const totalAb = d.perEmployee.reduce((s,r)=>s+r.absentDays,0);
  csv += `\nTOTAL,,,${d.totalGross},,${totalAb},${d.totalDeduct},${d.totalNet}\n`;
  const blob = new Blob([csv], {type:'text/csv;charset=utf-8;'});
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a'); a.href=url; a.download=`Salary_Cost_${d.month}.csv`; a.click();
  URL.revokeObjectURL(url);
  toast('📤 CSV export हो गई!');
}

async function loadDeviceInfoForCard(empId, empName){
  const el=document.getElementById('devinfo_'+empId);
  if(!el) return;
  try{
    const dRec=await fbGet('deviceApprovals/'+empId);
    const revokeRec=await fbGet('userApprovals/'+empId).catch(()=>null);
    // Get access level from employee record
    const emp = getEmps().find(e=>e.id===empId);
    const accessLevel = emp?.accessLevel || 'worker';
    const accessBadge = accessLevel==='manager'?'<span style="color:#a855f7;font-weight:800;font-size:10px">🏅 MANAGER</span>&nbsp;·&nbsp;':
                        accessLevel==='supervisor'?'<span style="color:#38bdf8;font-weight:800;font-size:10px">👁️ SUP</span>&nbsp;·&nbsp;':'';
    if(revokeRec&&revokeRec.status==='revoked'){
      el.innerHTML=`${accessBadge}<span style="color:#f43f5e;font-weight:700">🚫 Access Revoked</span>`;
      return;
    }
    if(!dRec||!dRec.approvedDeviceId){
      el.innerHTML=`${accessBadge}<span style="color:#64748b">📵 No device registered</span>`;
      return;
    }
    const expDate=new Date(dRec.validTill||0);
    const daysLeft=Math.ceil((expDate-Date.now())/86400000);
    const expColor=daysLeft<7?'#f43f5e':daysLeft<30?'#f97316':'#22c55e';
    el.innerHTML=`${accessBadge}<span style="color:#38bdf8">📱 Registered</span>
      &nbsp;·&nbsp;<span style="color:${expColor};font-weight:900">${daysLeft>0?daysLeft+' दिन बाकी':'⚠️ EXPIRED'}</span>
      &nbsp;·&nbsp;<span style="color:#64748b;font-size:10px">${expDate.toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}</span>`;
  }catch(e){
    el.innerHTML='<span style="color:#64748b">📵 No device info</span>';
  }
}

async function openDeviceManager(empId, empName){
  const modal=document.createElement('div');
  modal.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.85);z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px';
  modal.innerHTML=`<div style="background:#1e293b;border:1px solid #334155;border-radius:20px;padding:22px;max-width:360px;width:100%;max-height:90vh;overflow-y:auto">
    <div style="display:flex;align-items:center;gap:12px;margin-bottom:18px">
      <div style="font-size:32px">📱</div>
      <div>
        <div style="font-size:16px;font-weight:900;color:#fff">${empName}</div>
        <div style="font-size:11px;color:#64748b">Device & Access Manager</div>
      </div>
      <button onclick="this.closest('[style*=fixed]').remove()" style="margin-left:auto;background:none;border:none;color:#64748b;font-size:20px;cursor:pointer">✕</button>
    </div>
    <div id="dmContent_${empId}" style="min-height:80px;display:flex;align-items:center;justify-content:center">
      <div style="width:32px;height:32px;border:2px solid rgba(249,115,22,.2);border-top-color:#f97316;border-radius:50%;animation:spin 1s linear infinite"></div>
    </div>
  </div>`;
  document.body.appendChild(modal);
  await loadDeviceManagerContent(empId, empName);
}

async function loadDeviceManagerContent(empId, empName){
  const el=document.getElementById('dmContent_'+empId);
  if(!el) return;
  try{
    const [dRec, revokeRec, loginReqs] = await Promise.all([
      fbGet('deviceApprovals/'+empId).catch(()=>null),
      fbGet('userApprovals/'+empId).catch(()=>null),
      fbGet('loginRequests').catch(()=>null)
    ]);
    const isRevoked=revokeRec&&revokeRec.status==='revoked';
    const expDate=dRec&&dRec.validTill?new Date(dRec.validTill):null;
    const daysLeft=expDate?Math.ceil((expDate-Date.now())/86400000):null;
    const expColor=daysLeft==null?'#64748b':daysLeft<7?'#f43f5e':daysLeft<30?'#f97316':'#22c55e';
    const myLoginReqs=loginReqs?Object.values(loginReqs).filter(r=>r.empObjId===empId):[];
    const pendingReqs=myLoginReqs.filter(r=>r.status==='pending');
    const approvedReqs=myLoginReqs.filter(r=>r.status==='approved');

    el.innerHTML=`
      <!-- Access Status -->
      <div style="background:${isRevoked?'rgba(244,63,94,.1)':'rgba(34,197,94,.08)'};border:1px solid ${isRevoked?'rgba(244,63,94,.3)':'rgba(34,197,94,.2)'};border-radius:12px;padding:14px;margin-bottom:12px">
        <div style="font-size:12px;font-weight:800;color:#64748b;letter-spacing:.5px;margin-bottom:6px">ACCESS STATUS</div>
        <div style="font-size:15px;font-weight:900;color:${isRevoked?'#f43f5e':'#22c55e'}">${isRevoked?'🚫 Revoked':'✅ Active'}</div>
        ${isRevoked?`<div style="font-size:11px;color:#64748b;margin-top:4px">Revoked on ${revokeRec.revokedAt?new Date(revokeRec.revokedAt).toLocaleDateString('en-IN'):'—'}</div>`:''}
        <div style="display:flex;gap:8px;margin-top:10px">
          ${isRevoked
            ? `<button onclick="adminRestoreAccess('${empId}','${empName}')" style="flex:1;padding:10px;background:rgba(34,197,94,.15);border:1px solid rgba(34,197,94,.3);border-radius:9px;color:#22c55e;font-size:13px;font-weight:700;cursor:pointer">✅ Restore Access</button>`
            : `<button onclick="adminRevokeAccess('${empId}','${empName}')" style="flex:1;padding:10px;background:rgba(244,63,94,.1);border:1px solid rgba(244,63,94,.3);border-radius:9px;color:#f43f5e;font-size:13px;font-weight:700;cursor:pointer">🚫 Revoke Access</button>`
          }
        </div>
      </div>

      <!-- Device Info -->
      <div style="background:#0f172a;border:1px solid #334155;border-radius:12px;padding:14px;margin-bottom:12px">
        <div style="font-size:12px;font-weight:800;color:#64748b;letter-spacing:.5px;margin-bottom:8px">REGISTERED DEVICE</div>
        ${dRec&&dRec.approvedDeviceId?`
          <div style="font-size:13px;color:#94a3b8;margin-bottom:6px">Device ID: <span style="color:#fff;font-family:monospace">${dRec.approvedDeviceId.substring(0,18)}...</span></div>
          <div style="font-size:13px;color:#94a3b8">Approved: <span style="color:#fff">${dRec.approvedAt?new Date(dRec.approvedAt).toLocaleDateString('en-IN'):'—'}</span></div>
          <div style="font-size:13px;margin-top:4px">Expiry: <span style="color:${expColor};font-weight:700">${expDate?expDate.toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'—'} (${daysLeft!=null?(daysLeft>0?daysLeft+' days left':'EXPIRED'):'—'})</span></div>
        `:`<div style="color:#64748b;font-size:13px">📵 No device registered yet</div>`}
        ${dRec&&dRec.approvedDeviceId?`
          <div style="display:flex;gap:8px;margin-top:12px;flex-wrap:wrap">
            <button onclick="adminExtendExpiry('${empId}','${empName}',30)" style="flex:1;min-width:100px;padding:9px;background:rgba(249,115,22,.1);border:1px solid rgba(249,115,22,.3);border-radius:9px;color:#f97316;font-size:12px;font-weight:700;cursor:pointer">+30 Days</button>
            <button onclick="adminExtendExpiry('${empId}','${empName}',90)" style="flex:1;min-width:100px;padding:9px;background:rgba(249,115,22,.15);border:1px solid rgba(249,115,22,.4);border-radius:9px;color:#f97316;font-size:12px;font-weight:700;cursor:pointer">+90 Days</button>
            <button onclick="adminExtendExpiry('${empId}','${empName}',365)" style="flex:1;min-width:100px;padding:9px;background:rgba(168,85,247,.1);border:1px solid rgba(168,85,247,.3);border-radius:9px;color:#a855f7;font-size:12px;font-weight:700;cursor:pointer">+1 Year</button>
            <button onclick="adminRemoveDevice('${empId}','${empName}')" style="flex:1;min-width:100px;padding:9px;background:rgba(244,63,94,.1);border:1px solid rgba(244,63,94,.3);border-radius:9px;color:#f43f5e;font-size:12px;font-weight:700;cursor:pointer">🗑️ Remove</button>
          </div>`:''}
      </div>

      <!-- Login History -->
      <div style="background:#0f172a;border:1px solid #334155;border-radius:12px;padding:14px">
        <div style="font-size:12px;font-weight:800;color:#64748b;letter-spacing:.5px;margin-bottom:8px">LOGIN REQUESTS (${myLoginReqs.length} total · ${pendingReqs.length} pending)</div>
        ${myLoginReqs.length===0?`<div style="color:#64748b;font-size:12px">No login requests yet</div>`:
          myLoginReqs.slice(-5).reverse().map(r=>{
            const statusColor={'approved':'#22c55e','rejected':'#f43f5e','pending':'#f97316','cancelled':'#64748b'}[r.status]||'#94a3b8';
            return `<div style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid #1e293b">
              <div style="width:8px;height:8px;border-radius:50%;background:${statusColor};flex-shrink:0"></div>
              <div style="flex:1">
                <div style="font-size:12px;color:#fff;font-weight:700">${r.status.toUpperCase()}</div>
                <div style="font-size:11px;color:#64748b">${r.requestedAt?new Date(r.requestedAt).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'—'}</div>
              </div>
            </div>`;
          }).join('')
        }
      </div>`;
  }catch(e){
    el.innerHTML=`<div style="color:#f43f5e;font-size:13px">Error: ${e.message}</div>`;
  }
}

async function adminExtendExpiry(empId, empName, days){
  try{
    const dRec=await fbGet('deviceApprovals/'+empId).catch(()=>null);
    const base=dRec&&dRec.validTill&&new Date(dRec.validTill)>new Date()?new Date(dRec.validTill):new Date();
    const newExp=new Date(base.getTime()+days*86400000);
    await fbUpdate('deviceApprovals/'+empId,{
      validTill:newExp.toISOString(), extendedBy:SESSION.name,
      extendedAt:new Date().toISOString()
    });
    toast('✅ '+empName+' की expiry '+days+' दिन बढ़ाई → '+newExp.toLocaleDateString('en-IN'));
    loadDeviceManagerContent(empId, empName);
    loadDeviceInfoForCard(empId, empName);
  }catch(e){ toast('❌ Error: '+e.message); }
}

async function adminRemoveDevice(empId, empName){
  const ok = await confirmModal('Device हटाएं?', `<b>${empName}</b> का device हटाया जाएगा।<br>Login के लिए Admin approval लेनी होगी।`, '🗑️ हाँ, हटाएं', 'रद्द करें');
  if(!ok) return;
  try{
    await fbUpdate('deviceApprovals/'+empId,{
      approvedDeviceId:null, removedBy:SESSION.name, removedAt:new Date().toISOString()
    });
    toast('✅ '+empName+' का device हटाया गया');
    loadDeviceManagerContent(empId, empName);
    loadDeviceInfoForCard(empId, empName);
  }catch(e){ toast('❌ Error: '+e.message); }
}

async function adminRevokeAccess(empId, empName){
  const ok = await confirmModal('Access Revoke करें?', `<b>${empName}</b> की App access revoke होगी।<br>वो login नहीं कर पाएंगे।`, '🚫 हाँ, Revoke करें', 'रद्द करें');
  if(!ok) return;
  try{
    await fbUpdate('userApprovals/'+empId,{
      status:'revoked', revokedBy:SESSION.name, revokedAt:new Date().toISOString()
    });
    toast('🚫 '+empName+' की access revoke कर दी');
    loadDeviceManagerContent(empId, empName);
    loadDeviceInfoForCard(empId, empName);
  }catch(e){ toast('❌ Error: '+e.message); }
}

async function adminRestoreAccess(empId, empName){
  try{
    await fbUpdate('userApprovals/'+empId,{
      status:'active', restoredBy:SESSION.name, restoredAt:new Date().toISOString()
    });
    toast('✅ '+empName+' की access restore हो गई');
    loadDeviceManagerContent(empId, empName);
    loadDeviceInfoForCard(empId, empName);
  }catch(e){ toast('❌ Error: '+e.message); }
}

function showEmpNcrs(empId){
  const emp = getEmps().find(e=>e.id===empId);
  if(!emp) return;
  const ncrs = getNcrForEmp(empId);
  if(!ncrs.length){ toast('इस कर्मचारी का कोई NCR नहीं है'); return; }

  // Sort newest first
  const sorted = [...ncrs].sort((a,b)=>b.date.localeCompare(a.date));

  const rows = sorted.map(n=>{
    const d = new Date(n.date).toLocaleDateString('hi-IN',{day:'numeric',month:'short',year:'numeric'});
    const yr = n.year||n.date.substring(0,4);
    return `<div style="background:rgba(244,63,94,.05);border:1px solid rgba(244,63,94,.2);border-radius:10px;padding:11px 13px;margin-bottom:8px">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">
        <span style="background:rgba(244,63,94,.2);color:var(--lv);font-size:11px;font-weight:900;padding:2px 8px;border-radius:5px;flex-shrink:0">NCR #${n.ncr}</span>
        <span style="font-size:11px;color:var(--muted2)">${d}</span>
      </div>
      <div style="font-size:13px;color:var(--text);line-height:1.5">${n.reason}</div>
      ${n.names.length>1?`<div style="font-size:11px;color:var(--muted2);margin-top:5px">👥 साथ: ${n.names.filter(nm=>{const id=NCR_NAME_MAP[nm]; return id&&id!==empId;}).join(', ')||'—'}</div>`:''}
    </div>`;
  }).join('');

  openModal(`<div class="modal-handle"></div>
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:16px">
      <div style="width:42px;height:42px;border-radius:10px;background:rgba(244,63,94,.15);display:flex;align-items:center;justify-content:center;font-size:20px;flex-shrink:0">⚠️</div>
      <div>
        <div style="font-size:17px;font-weight:900;color:#fff">${emp.name}</div>
        <div style="font-size:12px;color:var(--lv)">कुल ${ncrs.length} NCR दर्ज हैं</div>
      </div>
    </div>
    <div style="max-height:60vh;overflow-y:auto;padding-right:4px">
      ${rows}
    </div>
    <button class="cancel-btn" onclick="closeModal()" style="margin-top:10px">बंद करें</button>`);
}


// ════════════════════════════════════════════════════════════════════════
//  EMPLOYEE UPLOAD WIZARD — Step 1: Guide  →  Step 2: Upload  →  Step 3: Preview & Confirm
//  Supports: .xlsx, .xls, .csv
//  Matches existing employees by empId (Employee Code) — UPDATES them
//  New empId → ADDS as new employee (id = 'eu_' + Date.now())
//  DOES NOT touch: leaves, reports, overrides, schedules, deviceApprovals
// ════════════════════════════════════════════════════════════════════════

// ── Role → section mapping ──
const ROLE_TO_SEC = {
  'operator':   null,         // determined by machine
  'assistant':  null,         // determined by machine
  'supervisor': 'SUP',
  'manager':    'MGR',
  'engineer':   'SUP',
  'get':        'SUP',
};

const MC_TO_SEC = {
  // Metalliser-1
  'm-1':'M1','m1':'M1','metalliser-1':'M1','metalliser 1':'M1','met-1':'M1','m-1&2':'M1','met 1':'M1',
  // Metalliser-2
  'm-2':'M2','m2':'M2','metalliser-2':'M2','metalliser 2':'M2','met-2':'M2','met 2':'M2',
  // Slitter-1
  's-1':'S1','s1':'S1','slitter-1':'S1','slitter 1':'S1',
  // Slitter-2
  's-2':'S2','s2':'S2','slitter-2':'S2','slitter 2':'S2',
  // Slitter both (S-1&2, S-1/2 etc.) — assign S1 as primary
  's-1&2':'S1','s-1/2':'S1','s1&2':'S1','s1/2':'S1','s-1 & 2':'S1','slitter':'S1',
  // Metalliser both (M-1&2 etc.) — assign M1 as primary
  'm-1&2':'M1','m1&2':'M1','m-1/2':'M1','metalliser':'M1',
  // Supervisor / Engineer / Manager
  'sup':'SUP','supervisor':'SUP','engg':'SUP','eng':'SUP','engineer':'SUP',
  'met':'M1','all':'MGR','mgr':'MGR','manager':'MGR',
};

const WOFF_VALUES = ['MON','TUE','WED','THU','FRI','SAT','SUN'];

let _empUploadParsed = []; // holds parsed rows before confirm

function openEmpUploadWizard(){
  _empUploadParsed = [];
  openModal(`<div class="modal-handle"></div>
    <div class="modal-title">📤 कर्मचारी List Upload करें</div>

    <!-- FORMAT GUIDE -->
    <div style="background:rgba(249,115,22,.07);border:1px solid rgba(249,115,22,.25);border-radius:12px;padding:14px;margin-bottom:16px">
      <div style="font-size:13px;font-weight:800;color:#f97316;margin-bottom:10px">📋 File Format Guide</div>
      <div style="font-size:11px;color:var(--muted2);line-height:1.8">
        Excel (.xlsx / .xls) या CSV file में नीचे दिए <b style="color:#fff">Column Headers</b> होने चाहिए:<br>
        <span style="display:inline-block;margin-top:8px;line-height:2">
          <span style="background:#1e293b;border-radius:4px;padding:2px 7px;margin:2px;display:inline-block;color:#f97316;font-weight:700;font-size:11px">Name</span>
          <span style="background:#1e293b;border-radius:4px;padding:2px 7px;margin:2px;display:inline-block;color:#f97316;font-weight:700;font-size:11px">Employee Code</span>
          <span style="background:#1e293b;border-radius:4px;padding:2px 7px;margin:2px;display:inline-block;color:#f97316;font-weight:700;font-size:11px">Machine</span>
          <span style="background:#1e293b;border-radius:4px;padding:2px 7px;margin:2px;display:inline-block;color:#22c55e;font-weight:700;font-size:11px">Role</span>
          <span style="background:#1e293b;border-radius:4px;padding:2px 7px;margin:2px;display:inline-block;color:#22c55e;font-weight:700;font-size:11px">Weekly Off</span>
          <span style="background:#1e293b;border-radius:4px;padding:2px 7px;margin:2px;display:inline-block;color:#22c55e;font-weight:700;font-size:11px">Phone</span>
          <span style="background:#1e293b;border-radius:4px;padding:2px 7px;margin:2px;display:inline-block;color:#fbbf24;font-weight:700;font-size:11px">Monthly Salary</span>
          <span style="background:#1e293b;border-radius:4px;padding:2px 7px;margin:2px;display:inline-block;color:#64748b;font-weight:700;font-size:11px">Joining Date</span>
          <span style="background:#1e293b;border-radius:4px;padding:2px 7px;margin:2px;display:inline-block;color:#64748b;font-weight:700;font-size:11px">Date of Birth</span>
        </span>
      </div>
      <div style="margin-top:10px;font-size:11px;color:var(--muted2);line-height:1.8">
        <b style="color:#f97316">🟠 Name, Employee Code, Machine:</b> अनिवार्य<br>
        <b style="color:#22c55e">🟢 Role, Weekly Off, Phone:</b> जरूरी (खाली छोड़ सकते हैं, default लगेगा)<br>
        <b style="color:#fbbf24">🟡 Monthly Salary:</b> Optional — Cost calculation के लिए (only numbers, e.g. 15000)<br>
        <b style="color:#64748b">⚫ Joining Date, DOB:</b> Optional<br><br>
        <b style="color:#fff">Role के लिए मान्य values:</b> Operator, Assistant, Supervisor, Manager, Engineer<br>
        <b style="color:#fff">Weekly Off:</b> MON, TUE, WED, THU, FRI, SAT, SUN<br>
        <b style="color:#fff">Machine:</b> M-1, M-2, S-1, S-2, ALL<br><br>
        <b style="color:#22c55e">✅ Existing Employee Code मिलने पर:</b> Details UPDATE होंगी<br>
        <b style="color:#3b82f6">🆕 New Employee Code:</b> नया कर्मचारी ADD होगा
      </div>
    </div>

    <!-- FILE UPLOAD AREA -->
    <div onclick="document.getElementById('empUploadFileInput').click()"
      style="border:2px dashed rgba(249,115,22,.4);border-radius:14px;padding:24px;text-align:center;cursor:pointer;background:rgba(249,115,22,.04);margin-bottom:12px"
      ondragover="event.preventDefault()" ondrop="_empUploadDrop(event)">
      <div style="font-size:32px;margin-bottom:8px">📁</div>
      <div style="font-size:14px;font-weight:800;color:#f97316">File चुनें या यहाँ Drop करें</div>
      <div style="font-size:11px;color:var(--muted2);margin-top:4px">.xlsx, .xls, .csv supported</div>
    </div>
    <input type="file" id="empUploadFileInput" accept=".xlsx,.xls,.csv" style="display:none" onchange="_empUploadFileChosen(this)">

    <div id="empUploadStatus" style="display:none;padding:10px;border-radius:10px;font-size:12px;margin-bottom:8px"></div>

    <button class="cancel-btn" onclick="closeModal()">रद्द करें</button>
  `);
}

function _empUploadDrop(e){
  e.preventDefault();
  const file = e.dataTransfer?.files?.[0];
  if(file) _parseEmpUploadFile(file);
}

function _empUploadFileChosen(input){
  const file = input.files?.[0];
  if(file) _parseEmpUploadFile(file);
}

async function _parseEmpUploadFile(file){
  const statusEl = document.getElementById('empUploadStatus');
  statusEl.style.display = 'block';
  statusEl.style.background = 'rgba(59,130,246,.08)';
  statusEl.style.border = '1px solid rgba(59,130,246,.2)';
  statusEl.innerHTML = '⏳ फ़ाइल पढ़ी जा रही है...';

  try{
    // Load SheetJS if needed
    if(!window.XLSX){
      await new Promise((res,rej)=>{
        const s=document.createElement('script');
        s.src='https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js';
        s.onload=res; s.onerror=rej;
        document.head.appendChild(s);
      });
    }

    const buf = await file.arrayBuffer();
    let rows;

    if(file.name.toLowerCase().endsWith('.csv')){
      // CSV: decode as text
      const text = new TextDecoder('utf-8').decode(buf);
      rows = text.trim().split('\n').map(r =>
        r.split(',').map(c => c.trim().replace(/^"|"$/g,''))
      );
    } else {
      const wb = XLSX.read(buf,{type:'array',cellDates:true});
      const ws = wb.Sheets[wb.SheetNames[0]];
      rows = XLSX.utils.sheet_to_json(ws,{header:1,raw:false,defval:''});
    }

    if(!rows || rows.length < 2){
      statusEl.style.background = 'rgba(239,68,68,.1)';
      statusEl.innerHTML = '❌ File में कोई data नहीं मिला';
      return;
    }

    // ── Map header columns ──
    const rawHeader = rows[0].map(h => String(h||'').toLowerCase().trim());
    const colIdx = {};
    const colAliases = {
      name:          ['name','नाम','employee name','emp name','full name'],
      empId:         ['employee code','emp code','empid','employee id','emp id','code','id'],
      machine:       ['machine','mc','machine/section','section machine'],
      role:          ['role','designation','position','post'],
      woff:          ['weekly off','weekly off day','woff','week off','off day'],
      phone:         ['phone','mobile','mobile no','phone no','contact','ph no'],
      salary:        ['monthly salary','salary','basic salary','ctc','monthly ctc','basic pay','मासिक वेतन','वेतन','sal','gross','gross salary','net salary','net pay','wage','wages','pay'],
      joiningDate:   ['joining date','joining','date of joining','doj'],
      dob:           ['date of birth','dob','birth date','d.o.b'],
    };
    Object.entries(colAliases).forEach(([key, aliases])=>{
      colIdx[key] = rawHeader.findIndex(h => aliases.some(a => h.includes(a)));
    });

    // Validate required columns
    if(colIdx.name < 0 || colIdx.empId < 0){
      statusEl.style.background = 'rgba(239,68,68,.1)';
      statusEl.innerHTML = '❌ "Name" और "Employee Code" columns नहीं मिले। Headers check करें।';
      return;
    }

    // ── Show detected columns feedback ──
    const detectedCols = Object.entries(colIdx).filter(([k,v])=>v>=0).map(([k])=>k);
    const salaryFound = colIdx.salary >= 0;
    statusEl.style.background = 'rgba(34,197,94,.08)';
    statusEl.style.border = '1px solid rgba(34,197,94,.2)';
    statusEl.innerHTML = `✅ Columns मिले: ${detectedCols.join(', ')} ${salaryFound?'<b style="color:#fbbf24">💰 Salary detected!</b>':'<span style="color:#f97316">⚠️ Salary column नहीं मिला</span>'}`;
    const existingEmps = getEmps();
    const parsed = [];
    const errors  = [];

    for(let i = 1; i < rows.length; i++){
      const row = rows[i];
      if(!row || row.every(c=>!c)) continue; // skip blank rows

      const name    = String(row[colIdx.name]||'').trim().toUpperCase();
      const empCode = String(row[colIdx.empId]||'').trim();
      if(!name || !empCode){ errors.push(`Row ${i+1}: Name/Code खाली`); continue; }

      const machineRaw = colIdx.machine >= 0 ? String(row[colIdx.machine]||'').trim() : '';
      const roleRaw    = colIdx.role    >= 0 ? String(row[colIdx.role]||'').trim().toLowerCase() : '';
      const woffRaw    = colIdx.woff    >= 0 ? String(row[colIdx.woff]||'').trim().toUpperCase() : '';
      const phoneRaw   = colIdx.phone   >= 0 ? String(row[colIdx.phone]||'').trim().replace(/\D/g,'') : '';
      const salaryRaw  = colIdx.salary  >= 0 ? String(row[colIdx.salary]||'').trim().replace(/[^0-9.]/g,'') : '';
      const joinRaw    = colIdx.joiningDate >= 0 ? String(row[colIdx.joiningDate]||'').trim() : '';
      const dobRaw     = colIdx.dob     >= 0 ? String(row[colIdx.dob]||'').trim() : '';

      // ── Determine sec from role + machine ──
      let sec = ROLE_TO_SEC[roleRaw] || null;
      if(!sec){
        sec = MC_TO_SEC[machineRaw.toLowerCase()] || 'M1';
      }

      // ── Match existing employee (needed for preserving data) ──
      const existing = existingEmps.find(e =>
        e.empId && e.empId.trim().toUpperCase() === empCode.toUpperCase()
      );

      // ── Determine resp (responsibility) from Machine column ──
      // Rule: Specific machine (M-1, M-2, S-1, S-2) = Main Operator (Operation)
      //       Combined machine (M-1&2, S-1&2) = Reliever/Team Member (Setup)
      //       SUP/ENGG = Supervisor, MGR = Manager
      const mcLower = machineRaw.toLowerCase().trim();
      let resp;
      if(mcLower === 'sup' || mcLower === 'engg' || mcLower === 'engineer'){
        resp = 'P,Q,M';
      } else if(mcLower === 'mgr' || mcLower === 'manager'){
        resp = 'Manager';
      } else if(mcLower === 'm-1' || mcLower === 'm1' || mcLower === 'm-2' || mcLower === 'm2' ||
                mcLower === 's-1' || mcLower === 's1' || mcLower === 's-2' || mcLower === 's2'){
        resp = 'Operation'; // Specific machine = Main Operator
      } else if(mcLower.includes('&') || mcLower.includes('/') || mcLower === 'met' || mcLower === 'slitter'){
        resp = 'Setup'; // Combined machine = Reliever/Team Member
      } else {
        const r = roleRaw.toLowerCase();
        if(r.includes('supervisor') || r.includes('engg') || r.includes('engineer')) resp = 'P,Q,M';
        else if(r.includes('manager')) resp = 'Manager';
        else resp = existing?.resp || 'Operation';
      }

      // ── Joining date — use robust parser ──
      const joiningDate = _parseExcelDate(joinRaw);
      const dob = _parseExcelDate(dobRaw);

      // ── Determine woff ──
      const woff = WOFF_VALUES.includes(woffRaw) ? woffRaw :
                   WOFF_VALUES.includes(woffRaw.substring(0,3)) ? woffRaw.substring(0,3) :
                   (existing?.woff || 'SUN');

      // ── Phone validation ──
      const phone = (phoneRaw.length === 10) ? phoneRaw :
                    (phoneRaw.length === 12 && phoneRaw.startsWith('91')) ? phoneRaw.slice(2) :
                    phoneRaw.replace(/\D/g,'').slice(-10) || '';

      // ── Designation — keep from Excel ──
      const desig = roleRaw ? (roleRaw.charAt(0).toUpperCase() + roleRaw.slice(1)) : (existing?.designation || 'Team Member');

      // ── Duplicate mobile: already used by another employee / other team ──
      let phoneConflict = null;
      if(phone && phone.length === 10){
        phoneConflict = _findPhoneConflict(phone, existing?.id, empCode);
      }

      parsed.push({
        _isNew:    !existing,
        id:        existing ? existing.id : ('eu_' + Date.now() + '_' + Math.random().toString(36).slice(2,5)),
        name, empId: empCode, sec, mc: machineRaw || (existing?.mc || '—'),
        resp,
        woff, phone,
        designation: desig,
        joiningDate, dob,
        monthlySalary: salaryRaw ? parseFloat(salaryRaw) : (existing?.monthlySalary || null),
        status:    existing ? (existing.status || 'active') : 'active',
        ms:        existing ? (existing.ms || Array(31).fill('D')) : Array(31).fill('D'),
        _rowNum:   i + 1,
        _phoneConflict: !!phoneConflict,
        _otherTeam: !!(phoneConflict && phoneConflict.otherTeam),
        _conflictWith: phoneConflict ? (phoneConflict.emp.name || phoneConflict.emp.empId || '') : '',
        _conflictMgr: phoneConflict && phoneConflict.emp.managerId ? phoneConflict.emp.managerId : '',
        _skipSave: !!phoneConflict, // do not add/update if phone belongs to someone else
      });
    }

    // Within-file duplicate phones: mark later rows as conflict
    const seenPhone = new Map();
    parsed.forEach(p => {
      if(!p.phone || p.phone.length !== 10) return;
      if(seenPhone.has(p.phone)){
        p._phoneConflict = true;
        p._otherTeam = p._otherTeam || false;
        p._conflictWith = p._conflictWith || ('Row ' + seenPhone.get(p.phone));
        p._skipSave = true;
        p._fileDup = true;
      } else {
        seenPhone.set(p.phone, p._rowNum);
      }
    });

    _empUploadParsed = parsed;

    if(parsed.length === 0){
      statusEl.style.background = 'rgba(239,68,68,.1)';
      statusEl.innerHTML = `❌ कोई valid row नहीं मिली।${errors.length ? ' Errors: ' + errors.join(', ') : ''}`;
      return;
    }

    // ── Show preview ──
    _showEmpUploadPreview(parsed, errors);

  }catch(err){
    statusEl.style.background = 'rgba(239,68,68,.1)';
    statusEl.innerHTML = '❌ Error: ' + escHtml(err.message);
  }
}

function _showEmpUploadPreview(parsed, errors){
  const okRows = parsed.filter(p => !p._skipSave);
  const conflictRows = parsed.filter(p => p._skipSave);
  const newCount = okRows.filter(p => p._isNew).length;
  const updCount = okRows.length - newCount;
  const isEn = (typeof _lang !== 'undefined' && _lang === 'en');

  const rows = parsed.map(p => {
    const conflict = !!p._skipSave;
    const badge = conflict
      ? (p._otherTeam
          ? `<span style="font-size:10px;font-weight:800;padding:2px 8px;border-radius:6px;background:rgba(244,63,94,.2);color:#fb7185">🚫 ${isEn?'Other team':'दूसरी team'}</span>`
          : p._fileDup
            ? `<span style="font-size:10px;font-weight:800;padding:2px 8px;border-radius:6px;background:rgba(244,63,94,.2);color:#fb7185">🚫 ${isEn?'Dup in file':'File में Dup'}</span>`
            : `<span style="font-size:10px;font-weight:800;padding:2px 8px;border-radius:6px;background:rgba(244,63,94,.2);color:#fb7185">🚫 ${isEn?'Phone taken':'Phone लिया'}</span>`)
      : `<span style="font-size:10px;font-weight:800;padding:2px 8px;border-radius:6px;${p._isNew?'background:rgba(34,197,94,.15);color:#22c55e':'background:rgba(59,130,246,.15);color:#60a5fa'}">${p._isNew ? '🆕 New' : '✏️ Update'}</span>`;
    const tip = conflict
      ? (isEn
          ? `Mobile ${p.phone} already used by ${p._conflictWith||'another member'}${p._otherTeam?' (other team)':''}. Will NOT be saved.`
          : `मोबाइल ${p.phone} पहले से ${p._conflictWith||'दूसरे member'} के पास है${p._otherTeam?' (दूसरी team)':''}. Save नहीं होगा।`)
      : '';
    const secMeta = getSectionMeta(p.sec || p.section);
    return `
    <tr style="border-bottom:1px solid var(--border2);${conflict?'background:rgba(244,63,94,.12);outline:1px solid rgba(244,63,94,.35);':''}" title="${escHtml(tip)}">
      <td style="padding:6px 8px;font-size:11px;font-weight:700;color:${conflict?'#fda4af':'#fff'}">${escHtml(p.name)}${conflict?' ⚠️':''}</td>
      <td style="padding:6px 4px;font-size:10px;color:var(--muted2)">${escHtml(p.empId)}</td>
      <td style="padding:6px 4px;font-size:10px">
        <span style="background:${secMeta.bg};color:${secMeta.color};border-radius:4px;padding:1px 6px;font-size:10px;font-weight:700">${escHtml(p.sec||p.section||'—')}</span>
      </td>
      <td style="padding:6px 4px;font-size:10px;color:var(--muted2)">${escHtml(p.mc)}</td>
      <td style="padding:6px 4px;font-size:10px;color:var(--muted2)">${p.woff}</td>
      <td style="padding:6px 4px;font-size:10px;font-weight:${conflict?'800':'400'};color:${conflict?'#fb7185':'var(--muted2)'}">${p.phone||'—'}${conflict?' ⛔':''}</td>
      <td style="padding:6px 4px;font-size:10px;color:${p.monthlySalary?'#fbbf24':'var(--muted2)'};font-weight:${p.monthlySalary?'700':'400'}">${p.monthlySalary?'₹'+Number(p.monthlySalary).toLocaleString('en-IN'):'—'}</td>
      <td style="padding:6px 4px;font-size:10px;color:${p.joiningDate?'#34d399':'var(--muted2)'}">${p.joiningDate ? new Date(p.joiningDate+'T00:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}) : '—'}</td>
      <td style="padding:6px 4px;text-align:center">${badge}</td>
    </tr>`;
  }).join('');

  openModal(`<div class="modal-handle"></div>
    <div class="modal-title">👁️ Preview — Save करने से पहले देखें</div>

    <!-- Summary strip -->
    <div style="display:flex;gap:8px;margin-bottom:14px">
      <div style="flex:1;background:rgba(34,197,94,.1);border:1px solid rgba(34,197,94,.2);border-radius:10px;padding:10px;text-align:center">
        <div style="font-size:22px;font-weight:900;color:#22c55e">${newCount}</div>
        <div style="font-size:10px;color:var(--muted2)">नए कर्मचारी</div>
      </div>
      <div style="flex:1;background:rgba(59,130,246,.1);border:1px solid rgba(59,130,246,.2);border-radius:10px;padding:10px;text-align:center">
        <div style="font-size:22px;font-weight:900;color:#60a5fa">${updCount}</div>
        <div style="font-size:10px;color:var(--muted2)">Update होंगे</div>
      </div>
      <div style="flex:1;background:rgba(249,115,22,.1);border:1px solid rgba(249,115,22,.2);border-radius:10px;padding:10px;text-align:center">
        <div style="font-size:22px;font-weight:900;color:#f97316">${okRows.length}</div>
        <div style="font-size:10px;color:var(--muted2)">${isEn?'OK to save':'सेव होंगे'}</div>
      </div>
      ${conflictRows.length?`<div style="flex:1;background:rgba(244,63,94,.1);border:1px solid rgba(244,63,94,.3);border-radius:10px;padding:10px;text-align:center">
        <div style="font-size:22px;font-weight:900;color:#fb7185">${conflictRows.length}</div>
        <div style="font-size:10px;color:var(--muted2)">${isEn?'Blocked':'ब्लॉक'}</div>
      </div>`:''}
    </div>

    ${errors.length ? `<div style="background:rgba(239,68,68,.1);border:1px solid rgba(239,68,68,.2);border-radius:8px;padding:10px;font-size:11px;color:#f87171;margin-bottom:12px">⚠️ ${errors.length} row(s) skip हुई: ${escHtml(errors.slice(0,3).join(', '))}${errors.length>3?' ...':''}</div>` : ''}
    ${conflictRows.length ? `<div style="background:rgba(244,63,94,.12);border:1.5px solid rgba(244,63,94,.4);border-radius:10px;padding:12px;font-size:12px;color:#fda4af;margin-bottom:12px;line-height:1.5">
      <b style="color:#fb7185">🚫 ${conflictRows.length} ${isEn?'row(s) blocked — mobile already used':'row(s) ब्लॉक — मोबाइल पहले से इस्तेमाल'}</b><br>
      ${isEn
        ? 'These members will <b>not</b> be added/updated because their mobile number belongs to another employee (often another team). Highlighted in red below.'
        : 'ये members <b>add/update नहीं</b> होंगे क्योंकि उनका मोबाइल नंबर दूसरे employee (अक्सर दूसरी team) के पास है। नीचे red में highlight हैं।'}
      <div style="margin-top:6px;font-size:11px;opacity:.9">${conflictRows.slice(0,5).map(p=>escHtml(p.name)+' ('+(p.phone||'')+') → '+escHtml(p._conflictWith||'?')).join('<br>')}${conflictRows.length>5?'<br>…':''}</div>
    </div>` : ''}

    <!-- Data table -->
    <div style="overflow-x:auto;overflow-y:auto;max-height:280px;border:1px solid var(--border2);border-radius:10px;margin-bottom:14px">
      <table style="width:100%;border-collapse:collapse;font-size:11px">
        <thead>
          <tr style="background:#1e293b;position:sticky;top:0">
            <th style="padding:8px;text-align:left;color:#94a3b8;font-size:10px">Name</th>
            <th style="padding:8px;text-align:left;color:#94a3b8;font-size:10px">Code</th>
            <th style="padding:8px;text-align:left;color:#94a3b8;font-size:10px">Sec</th>
            <th style="padding:8px;text-align:left;color:#94a3b8;font-size:10px">Machine</th>
            <th style="padding:8px;text-align:left;color:#94a3b8;font-size:10px">Off</th>
            <th style="padding:8px;text-align:left;color:#94a3b8;font-size:10px">Phone</th>
            <th style="padding:8px;text-align:left;color:#fbbf24;font-size:10px">Salary</th>
            <th style="padding:8px;text-align:left;color:#34d399;font-size:10px">Joining</th>
            <th style="padding:8px;text-align:center;color:#94a3b8;font-size:10px">Action</th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    </div>

    <div style="font-size:11px;color:var(--muted2);margin-bottom:12px;background:rgba(0,0,0,.2);border-radius:8px;padding:8px">
      ⚠️ <b>Note:</b> यह action केवल <b>Name, Machine, Role, Phone, Monthly Salary, Joining Date, DOB</b> update करेगी।
      Shift schedule, leaves, reports, device approvals — कोई change नहीं होगा।
    </div>

    <div style="display:flex;gap:8px">
      <button class="submit-btn" style="flex:1" onclick="_confirmEmpUpload()">✅ Confirm करें — Firebase में Save</button>
      <button class="cancel-btn" style="flex:1" onclick="openEmpUploadWizard()">← वापस</button>
    </div>
  `);
}

async function _confirmEmpUpload(){
  if(!_empUploadParsed.length){ toast('⚠️ कोई data नहीं'); return; }
  const btn = document.querySelector('#overlay .submit-btn');
  if(btn){ btn.disabled=true; btn.textContent='⏳ Saving...'; }

  // Fetch current data to preserve blank fields
  const existingEmps = getEmps();

  let saved = 0, failed = 0, skipped = 0;
  for(const emp of _empUploadParsed){
    if(emp._skipSave){ skipped++; continue; }
    try{
      const existing = existingEmps.find(e => e.id === emp.id) || {};

      // ── Only update fields that have actual values from Excel ──
      // Blank column = keep existing Firebase value
      const update = {
        id:     emp.id,
        empId:  emp.empId,
        name:   emp.name || existing.name,
        ms:     existing.ms || emp.ms || Array(31).fill('D'),
        status: existing.status || emp.status || 'active',
      };

      if(emp.mc && emp.mc !== '—')   update.mc          = emp.mc;
      else if(existing.mc)            update.mc          = existing.mc;

      if(emp.sec)                     update.sec         = emp.sec;
      else if(existing.sec)           update.sec         = existing.sec;

      const validResp = ['Operation','Setup','P,Q,M','Manager'];
      if(emp.resp && validResp.includes(emp.resp)) update.resp = emp.resp;
      else if(existing.resp)          update.resp        = existing.resp;
      else if(emp.resp)               update.resp        = emp.resp; // fallback

      if(emp.woff)                    update.woff        = emp.woff;
      else if(existing.woff)          update.woff        = existing.woff;

      if(emp.designation)             update.designation = emp.designation;
      else if(existing.designation)   update.designation = existing.designation;

      if(emp.phone)                   update.phone       = emp.phone;
      else if(existing.phone)         update.phone       = existing.phone;

      if(emp.joiningDate)             update.joiningDate = emp.joiningDate;
      else if(existing.joiningDate)   update.joiningDate = existing.joiningDate;

      if(emp.dob)                     update.dob         = emp.dob;
      else if(existing.dob)           update.dob         = existing.dob;

      if(emp.monthlySalary)           update.monthlySalary = emp.monthlySalary;
      else if(existing.monthlySalary) update.monthlySalary = existing.monthlySalary;

      await fbUpdate('employees/' + emp.id, update);
      saved++;
    }catch(e){
      failed++;
      console.error('Emp upload error:', emp.name, e);
    }
  }

  _empUploadParsed = [];
  closeModal();
  const isEn = (typeof _lang !== 'undefined' && _lang === 'en');
  let msg = isEn ? `✅ ${saved} employees saved!` : `✅ ${saved} कर्मचारी save हो गए!`;
  if(skipped) msg += isEn ? ` ${skipped} blocked (duplicate mobile).` : ` ${skipped} ब्लॉक (duplicate mobile)।`;
  if(failed) msg += isEn ? ` ${failed} failed.` : ` ${failed} failed.`;
  toast(msg);
}

// ════════════════════════════════════════
// BULK IMPORT TEAM FROM EXCEL (creates NEW employees — unlike Emp Upload which only updates existing)
// ════════════════════════════════════════
let _bulkImportParsed = [];

function openBulkImportTeam(){
  openModal(`<div class="modal-handle"></div>
  <div class="modal-title">📊 Excel से पूरी Team Import करें</div>
  <div style="font-size:12px;color:#94a3b8;line-height:1.7;margin-bottom:14px">
    अपनी Excel/CSV file अपलोड करें जिसमें ये columns हों (कोई भी क्रम में, नाम केस-असंवेदनशील):<br>
    <b style="color:var(--text)">Name</b> (जरूरी) · <b style="color:var(--text)">E Code</b> (जरूरी) ·
    <b style="color:var(--text)">Section</b> (जरूरी — Line-1 / Warehouse / ICU आदि) ·
    <b style="color:var(--text)">Designation</b> · <b style="color:var(--text)">Machine</b> ·
    <b style="color:var(--text)">Responsibility</b> · <b style="color:var(--text)">Salary</b> (वैकल्पिक) ·
    <b style="color:var(--text)">Mobile Number</b> (वैकल्पिक — दिया तो वो OTP से सीधे Login कर पाएंगे) ·
    <b style="color:var(--text)">Joining Date</b> (वैकल्पिक) · <b style="color:var(--text)">Weekly Off</b> (वैकल्पिक) ·
    <b style="color:var(--text)">Date of Birth</b> (वैकल्पिक)
  </div>
  <button class="cancel-btn" style="margin-bottom:12px" onclick="downloadBulkImportTemplate()">⬇️ Sample Template Download करें</button>
  <input type="file" id="bulkImportFile" accept=".xlsx,.xls,.csv" style="display:none" onchange="handleBulkImportFile(this.files[0])">
  <button class="submit-btn" onclick="document.getElementById('bulkImportFile').click()">📁 Excel/CSV File चुनें</button>
  <div id="bulkImportPreview" style="margin-top:14px"></div>
  <button class="cancel-btn" style="margin-top:10px" onclick="closeModal()">रद्द करें</button>`);
}

function downloadBulkImportTemplate(){
  const csv='Name,E Code,Section,Designation,Machine,Responsibility,Salary,Mobile Number,Joining Date,Weekly Off,Date of Birth\nRAM KUMAR,30001001,Line-1,Operator,M-1,Operation,25000,9876543210,01-04-2024,Sunday,15-06-1995\nSHYAM LAL,30001002,Warehouse,Supervisor,ALL,Quality Check,,,,Monday,\n';
  const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url; a.download='team_import_template.csv';
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function handleBulkImportFile(file){
  if(!file) return;
  const previewEl=document.getElementById('bulkImportPreview');
  previewEl.innerHTML='<div class="empty-text" style="padding:12px">Reading file...</div>';

  const parseWorkbook=(data)=>{
    const wb=XLSX.read(data,{type:'array',cellDates:true});
    const sheet=wb.Sheets[wb.SheetNames[0]];
    const rows=XLSX.utils.sheet_to_json(sheet,{defval:''});
    _processBulkImportRows(rows);
  };

  const reader=new FileReader();
  reader.onload=e=>{
    try{
      if(typeof XLSX==='undefined'){
        const s=document.createElement('script');
        s.src='https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js';
        s.onload=()=>parseWorkbook(new Uint8Array(e.target.result));
        s.onerror=()=>{ previewEl.innerHTML='<div style="color:var(--lv);padding:12px">❌ Library load नहीं हुई। Internet जांचें।</div>'; };
        document.head.appendChild(s);
      }else{
        parseWorkbook(new Uint8Array(e.target.result));
      }
    }catch(err){
      previewEl.innerHTML='<div style="color:var(--lv);padding:12px">❌ Error: '+err.message+'</div>';
    }
  };
  reader.readAsArrayBuffer(file);
}

function _findCol(row,names){
  const keys=Object.keys(row);
  for(const n of names){
    const found=keys.find(k=>k.toString().trim().toLowerCase()===n);
    if(found!==undefined && row[found]!=='') return row[found];
  }
  return '';
}

function _parseImportDate(val){
  if(!val) return '';
  if(val instanceof Date && !isNaN(val)) return val.toISOString().split('T')[0];
  const s=val.toString().trim();
  if(!s) return '';
  const parsed=new Date(s);
  if(!isNaN(parsed)) return parsed.toISOString().split('T')[0];
  return s; // keep as-is if unparseable, don't block the row
}
const _WOFF_MAP={SUN:'SUN',SUNDAY:'SUN',MON:'MON',MONDAY:'MON',TUE:'TUE',TUESDAY:'TUE',WED:'WED',WEDNESDAY:'WED',THU:'THU',THURSDAY:'THU',FRI:'FRI',FRIDAY:'FRI',SAT:'SAT',SATURDAY:'SAT'};
function _parseImportWoff(val){
  const s=(val||'').toString().trim().toUpperCase();
  return _WOFF_MAP[s]||'SUN';
}

function _isDateHeaderCol(key){
  const s = String(key||'').trim();
  if(!s) return false;
  // Skip known non-date employee columns
  const lower = s.toLowerCase();
  if(/^(name|emp|e\s*code|code|id|designation|weekly|mobile|phone|joining|birth|dob|machine|resp|salary|section)/i.test(lower)) return false;
  // 01-Jan-26, 1-Jan-2026, 01/01/2026, 2026-01-01, 01-Jan-2025 … up to 2+ years of columns
  if(/^\d{1,2}[-/ .](?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*[-/ .]\d{2,4}$/i.test(s)) return true;
  if(/^\d{1,2}[-/]\d{1,2}[-/]\d{2,4}$/.test(s)) return true;
  if(/^\d{4}-\d{2}-\d{2}/.test(s)) return true;
  if(/^(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*[-/ .]\d{1,2}[, ]+\d{2,4}$/i.test(s)) return true;
  // Excel may emit Date objects stringified
  if(!isNaN(Date.parse(s)) && /\d{4}/.test(s) && (s.includes('-')||s.includes('/')||s.includes(' '))) return true;
  return false;
}

function _parseHeaderDate(key){
  const s = String(key||'').trim();
  if(!s) return null;
  // Prefer day-first for dd-MMM-yy / dd-MMM-yyyy
  const m1 = s.match(/^(\d{1,2})[-/ ]([A-Za-z]{3,9})[-/ ](\d{2,4})$/);
  if(m1){
    const day = parseInt(m1[1],10);
    const monMap = {jan:0,feb:1,mar:2,apr:3,may:4,jun:5,jul:6,aug:7,sep:8,oct:9,nov:10,dec:11};
    const mon = monMap[m1[2].substring(0,3).toLowerCase()];
    let year = parseInt(m1[3],10);
    if(year < 100) year += 2000;
    if(mon==null || day<1 || day>31) return null;
    const d = new Date(year, mon, day);
    if(isNaN(d)) return null;
    return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
  }
  const m2 = s.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{2,4})$/);
  if(m2){
    let day=parseInt(m2[1],10), mon=parseInt(m2[2],10), year=parseInt(m2[3],10);
    if(year<100) year+=2000;
    // if first number >12 treat as day-month-year else prefer day-month (IN format)
    if(mon>12 && day<=12){ const t=day; day=mon; mon=t; }
    const d=new Date(year, mon-1, day);
    if(isNaN(d)) return null;
    return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
  }
  if(/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  const d = new Date(s);
  if(!isNaN(d) && d.getFullYear()>2000){
    return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
  }
  return null;
}
function _normShiftCode(val){
  let s = String(val==null?'':val).trim().toUpperCase();
  if(!s) return '';
  // Excel sometimes gives formulas or spaces
  s = s.replace(/\s+/g,'');
  const map = {
    'DAY':'D','D':'D','NIGHT':'N','N':'N',
    'A':'A','B':'B','C':'C',
    'O':'O','OFF':'O','WO':'O','W/OFF':'O','WEEKLYOFF':'O',
    'L':'L','LEAVE':'L','SL':'L','CL':'L','EL':'L',
    'C/O':'C/O','CO':'C/O','C-OFF':'C/O','COMPOFF':'C/O','COMP':'C/O',
    'G':'G','GENERAL':'G','GEN':'G',
    'GP':'GP','GATEPASS':'GP',
    'HLF':'HLF','HALF':'HLF','½':'HLF','1/2':'HLF',
    'AB':'Ab','ABS':'Ab','ABSENT':'Ab',
    'H':'H','HOLIDAY':'H','OD':'OD'
  };
  return map[s] || (s.length<=3 ? s : '');
}
/** True if value is a role code (MGR/SUP) wrongly used as Section — not a real plant section. */
function _isRoleOnlySec(v){
  const k = String(v||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
  return k==='MGR'||k==='MANAGER'||k==='SUP'||k==='SUPERVISOR'||k==='STAFF';
}

/**
 * Map machine code only — NEVER map Designation (Manager/Engineer) to Section.
 * Section must come from Excel "Section" column (Metalliser, Slitter, MetProd, …).
 */
function _mapMachineToSec(machine, designation){
  const raw = String(machine||'').trim();
  const u = raw.toUpperCase().replace(/\s+/g,'');
  if(!raw) return '';
  if(/^M-?1$/.test(u) || /METALLISER-?1/.test(u)) return 'M1';
  if(/^M-?2$/.test(u) || /METALLISER-?2/.test(u)) return 'M2';
  if(/^S-?1$/.test(u) || /SLITTER-?1/.test(u)) return 'S1';
  if(/^S-?2$/.test(u) || /SLITTER-?2/.test(u)) return 'S2';
  if(/METALLISER|^MET$/.test(u)) return 'MET';
  if(/SLITTER|^SLIT$/.test(u)) return 'SLIT';
  // Do NOT map designation Manager→MGR or Engineer→SUP — those are Designation, not Section
  if(/SUP|SUPERVISOR|ENGINEER|SHIFTENG/.test(u)) return 'SUP';
  if(/MGR|MANAGER/.test(u)) return 'MGR';
  return raw;
}

function _processBulkImportRows(rows){
  const previewEl=document.getElementById('bulkImportPreview');
  if(!rows || !rows.length){
    previewEl.innerHTML='<div style="color:var(--lv);padding:12px;font-size:12px">❌ No rows found in file.</div>';
    return;
  }

  const existingByCode = {};
  getEmps().forEach(e=>{
    const c=(e.empId||'').toString().trim();
    if(c) existingByCode[c]=e;
  });

  // Detect date columns from first row keys
  const sampleKeys = Object.keys(rows[0]||{});
  const dateCols = [];
  sampleKeys.forEach(k=>{
    if(_isDateHeaderCol(k)){
      const iso = _parseHeaderDate(k);
      if(iso) dateCols.push({ key:k, iso });
    }
  });
  // sort by date
  dateCols.sort((a,b)=>a.iso.localeCompare(b.iso));

  _bulkImportParsed=[];
  let invalidCount=0, updateCount=0, createCount=0;
  const seenInFile=new Set();

  rows.forEach(row=>{
    const name=(_findCol(row,['name','naam','नाम'])||'').toString().trim().toUpperCase();
    const code=(_findCol(row,['emp id','empid','e code','ecode','emp code','employee code','employee id','code','id'])||'').toString().trim();
    const designation=(_findCol(row,['designation','position','role','desig'])||'').toString().trim();
    const machine=(_findCol(row,['machine','mc','machine name','मशीन'])||'').toString().trim();
    const sectionCol=(_findCol(row,['section','sec','department section','सेक्शन','area','unit'])||'').toString().trim();
    const resp=(_findCol(row,['responsibility','resp'])||'').toString().trim();
    const salaryRaw=(_findCol(row,['salary','monthly salary','salary (₹/month)','salary (rs/month)','salary(₹/month)'])||'').toString().trim().replace(/[^0-9.]/g,'');
    let mobile=(_findCol(row,['mobile','mobile number','phone','phone number','contact'])||'').toString().trim().replace(/[^0-9]/g,'');
    if(mobile.length===12 && mobile.startsWith('91')) mobile=mobile.slice(2);
    if(mobile.length!==10) mobile='';
    const joiningDate=_parseImportDate(_findCol(row,['joining date','joining','date of joining','doj']));
    const dob=_parseImportDate(_findCol(row,['date of birth','dob','birth date','birthday']));
    const woff=_parseImportWoff(_findCol(row,['weekly off','week off','weekly holiday','woff','w-off','w off']));

    if(!name || !code){ invalidCount++; return; }
    if(seenInFile.has(code)){ return; }
    seenInFile.add(code);

    // Collect shifts by date
    const shiftsByDate = {};
    dateCols.forEach(dc=>{
      const raw = row[dc.key];
      const sh = _normShiftCode(raw);
      if(sh) shiftsByDate[dc.iso] = sh;
    });

    const existing = existingByCode[code];

    // Block mobiles already used by another employee / other team
    let phoneConflict = null;
    if(mobile){
      phoneConflict = _findPhoneConflict(mobile, existing?.id, code);
    }

    if(phoneConflict){
      invalidCount++;
      _bulkImportParsed.push({
        name, code, designation, machine, resp,
        salary: salaryRaw, mobile, joiningDate, dob, woff,
        sec: (sectionCol || (!_isRoleOnlySec(_mapMachineToSec(machine, designation)) ? _mapMachineToSec(machine, designation) : (machine||'General'))),
        section: sectionCol || '',
        shiftsByDate,
        existingId: existing ? existing.id : null,
        _skipSave: true,
        _phoneConflict: true,
        _otherTeam: !!phoneConflict.otherTeam,
        _conflictWith: phoneConflict.emp.name || phoneConflict.emp.empId || ''
      });
      return;
    }

    if(existing) updateCount++; else createCount++;

    _bulkImportParsed.push({
      name, code, designation, machine, resp,
      salary: salaryRaw, mobile, joiningDate, dob, woff,
      sec: (sectionCol || (!_isRoleOnlySec(_mapMachineToSec(machine, designation)) ? _mapMachineToSec(machine, designation) : (machine||'General'))),
        section: sectionCol || '',
      shiftsByDate,
      existingId: existing ? existing.id : null
    });
  });

  // Within-file mobile dups
  const seenMob = new Map();
  _bulkImportParsed.forEach(p=>{
    if(!p.mobile) return;
    if(seenMob.has(p.mobile)){
      p._skipSave = true; p._phoneConflict = true; p._fileDup = true;
      p._conflictWith = p._conflictWith || ('file:'+seenMob.get(p.mobile));
    } else seenMob.set(p.mobile, p.code);
  });

  if(!_bulkImportParsed.filter(p=>!p._skipSave).length){
    const blocked = _bulkImportParsed.filter(p=>p._skipSave);
    previewEl.innerHTML=`<div style="color:var(--lv);padding:12px;font-size:12px">
      ❌ No valid rows. ${invalidCount?invalidCount+' missing Name/Emp ID or blocked mobile. ':''}
      ${blocked.length?`<br>🚫 ${blocked.length} blocked (duplicate mobile): `+blocked.slice(0,5).map(b=>b.name+' ('+b.mobile+')').join(', '):''}
    </div>`;
    return;
  }

  const okBulk = _bulkImportParsed.filter(e=>!e._skipSave);
  const blockedBulk = _bulkImportParsed.filter(e=>e._skipSave);
  const withShifts = okBulk.filter(e=>Object.keys(e.shiftsByDate||{}).length).length;
  const months = new Set();
  okBulk.forEach(e=>Object.keys(e.shiftsByDate||{}).forEach(d=>months.add(d.substring(0,7))));
  const mobileCount=okBulk.filter(e=>e.mobile).length;

  previewEl.innerHTML=`
    <div style="font-size:13px;font-weight:800;color:#22c55e;margin-bottom:8px">
      ✅ ${okBulk.length} employees ready${blockedBulk.length?` · <span style="color:#fb7185">🚫 ${blockedBulk.length} blocked</span>`:''}
    </div>
    ${blockedBulk.length?`<div style="background:rgba(244,63,94,.12);border:1px solid rgba(244,63,94,.35);border-radius:8px;padding:10px;font-size:11px;color:#fda4af;margin-bottom:10px;line-height:1.5">
      🚫 Mobile already used (other team / duplicate) — will NOT import:<br>
      ${blockedBulk.slice(0,6).map(e=>`<b style="color:#fb7185">${e.name}</b> (${e.mobile}) → ${e._conflictWith||'?'}`).join('<br>')}
      ${blockedBulk.length>6?'<br>…':''}
    </div>`:''}
    <div style="font-size:12px;color:var(--text);line-height:1.6;margin-bottom:10px">
      🆕 Create: <b>${createCount}</b> &nbsp;·&nbsp; 🔄 Update: <b>${updateCount}</b><br>
      ${dateCols.length?`📅 Shift date columns: <b>${dateCols.length}</b> (${dateCols[0].iso} → ${dateCols[dateCols.length-1].iso})<br>`:''}
      ${months.size?`📆 Months to write: <b>${[...months].sort().join(', ')}</b><br>`:''}
      ${withShifts?`👥 Rows with shifts: <b>${withShifts}</b><br>`:''}
      ${mobileCount?`📱 Mobile (OTP login ready): <b>${mobileCount}</b>`:''}
    </div>
    <div style="max-height:160px;overflow:auto;font-size:11px;color:var(--muted2);margin-bottom:12px;border:1px solid var(--border);border-radius:8px;padding:8px">
      ${_bulkImportParsed.slice(0,12).map(e=>`<div>${e.existingId?'🔄':'🆕'} <b style="color:var(--text)">${e.name}</b> · ${e.code} · ${e.sec||'—'} · ${Object.keys(e.shiftsByDate||{}).length} days</div>`).join('')}
      ${_bulkImportParsed.length>12?`<div>… +${_bulkImportParsed.length-12} more</div>`:''}
    </div>
    <button class="submit-btn" onclick="confirmBulkImportTeam()">💾 Import Team + Shifts</button>
  `;
}

let _bulkImportInProgress=false;
async function confirmBulkImportTeam(){
  if(_bulkImportInProgress) return;
  if(!_bulkImportParsed.length) return;
  _bulkImportInProgress=true;

  const cid = (typeof myCompanyId==='function') ? myCompanyId() : (SESSION.companyId||'');
  const label = SESSION.company || SESSION.companyLabel || '';
  const mgrId = (SESSION.role==='manager' && SESSION.mobile) ? _normMobileKey(SESSION.mobile) : (SESSION.managerId||'');

  let saved=0, updated=0, created=0, failed=0, registered=0;
  const schedByMonth = {}; // mk -> { empId/internalId: [31] }

  const empIdToInternal = {};
  getEmps().forEach(e=>{ if(e.empId) empIdToInternal[String(e.empId).trim()]=e.id; });

  let skippedPhone=0;
  for(let i=0;i<_bulkImportParsed.length;i++){
    const e=_bulkImportParsed[i];
    if(e._skipSave){ skippedPhone++; continue; }
    try{
      let id = e.existingId;
      // Section from Excel Section column only (already resolved in parse); never designation→MGR
      let sec = e.sec || '';
      if(!sec || (typeof _isRoleOnlySec==='function' && _isRoleOnlySec(sec))){
        const m = (typeof _mapMachineToSec==='function') ? _mapMachineToSec(e.machine, '') : '';
        sec = (m && !(typeof _isRoleOnlySec==='function' && _isRoleOnlySec(m))) ? m : (e.machine || 'General');
      }
      const rec = {
        name: e.name,
        empId: e.code,
        sec: sec,
        section: sec, // keep Section text for filters (Metalliser / Slitter / MetProd)
        mc: e.machine || '',
        machine: e.machine || '',
        designation: e.designation || '',
        resp: e.resp || '',
        monthlySalary: e.salary ? Number(e.salary)||0 : 0,
        woff: e.woff || 'SUN',
        status: 'active',
      };
      if(e.joiningDate) rec.joiningDate=e.joiningDate;
      if(e.dob) rec.dob=e.dob;
      if(e.mobile) rec.phone=e.mobile;
      if(cid){ rec.companyId=cid; rec.companyLabel=label; }
      if(mgrId) rec.managerId=mgrId;

      if(id){
        // Update existing — merge only provided fields
        const patch = { ...rec };
        await fbUpdate('employees/'+id, patch);
        updated++;
      } else {
        id = 'e'+Date.now().toString(36)+i+Math.random().toString(36).slice(2,5);
        rec.id = id;
        rec.ms = Array(31).fill('');
        await fbSet('employees/'+id, rec);
        created++;
        empIdToInternal[e.code] = id;
      }
      saved++;

      // Build schedule arrays per month
      Object.entries(e.shiftsByDate||{}).forEach(([iso, sh])=>{
        const mk = iso.substring(0,7).replace('-','_');
        const dayIdx = parseInt(iso.split('-')[2],10)-1;
        if(dayIdx<0 || dayIdx>30) return;
        if(!schedByMonth[mk]) schedByMonth[mk] = {};
        const daysInMonth = new Date(parseInt(iso.slice(0,4),10), parseInt(iso.slice(5,7),10), 0).getDate();
        if(!schedByMonth[mk][e.code]) schedByMonth[mk][e.code] = new Array(daysInMonth).fill('');
        schedByMonth[mk][e.code][dayIdx] = sh;
        // also by internal id
        if(id){
          if(!schedByMonth[mk][id]) schedByMonth[mk][id] = new Array(daysInMonth).fill('');
          schedByMonth[mk][id][dayIdx] = sh;
        }
      });

      if(e.mobile){
        try{
          const existing=await fbGet('mobileUsers/'+e.mobile);
          if(!existing){
            await fbSet('mobileUsers/'+e.mobile,{
              role:'member', name:e.name, mobile:'+91'+e.mobile, company:label,
              status:'approved', empCode:e.code, managerId:mgrId||'',
              registeredAt:new Date().toISOString(),
              approvedAt:new Date().toISOString(), approvedBy:(SESSION.name||'Manager')+' (Excel Import)'
            });
            registered++;
          }
        }catch(ex){ console.warn('mobileUsers pre-approve skipped',e.mobile,ex); }
      }
    }catch(err){
      failed++;
      console.error('Bulk import error', e.name, err);
    }
  }

  // Save schedules (supports up to 2+ years of daily columns across many months)
  let monthsSaved=0;
  const monthKeys = Object.keys(schedByMonth).sort();
  for(const mk of monthKeys){
    try{
      const existing = (getSchedules()[mk]||{});
      const merged = { ...existing };
      Object.entries(schedByMonth[mk]).forEach(([empKey, arr])=>{
        // merge day-by-day so we don't wipe other days already in Firebase
        const prev = Array.isArray(merged[empKey]) ? merged[empKey].slice() : [];
        const out = new Array(Math.max(prev.length, arr.length, 31)).fill('');
        for(let d=0; d<out.length; d++){
          out[d] = (arr[d] != null && arr[d] !== '') ? arr[d] : (prev[d] || '');
        }
        merged[empKey] = out;
      });
      await fbSet('schedules/'+mk, merged);
      // update local cache if present
      try{
        if(_cache && _cache.schedules) _cache.schedules[mk] = merged;
      }catch(e){}
      monthsSaved++;
    }catch(err){
      console.error('Schedule save error', mk, err);
    }
  }

  _bulkImportParsed=[];
  _bulkImportInProgress=false;
  closeModal();
  toast(`✅ Team import: ${created} new, ${updated} updated` +
    (monthsSaved?`, ${monthsSaved} month(s) schedule`:``) +
    (registered?`, ${registered} login ready`:``) +
    (failed?`, ${failed} failed`:``));
  try{ renderTeam(); }catch(e){}
  try{ refreshAll(); }catch(e){}
  try{ if(typeof renderSchedule==='function') renderSchedule(); }catch(e){}
}

function _normalizeMachineLabel(raw){
  const s = String(raw||'').trim();
  if(!s) return '';
  // M1 / m1 / M-1 → M-1; S2 → S-2
  let m = s.match(/^M[\s\-]?(\d+)$/i);
  if(m) return 'M-'+m[1];
  m = s.match(/^S[\s\-]?(\d+)$/i);
  if(m) return 'S-'+m[1];
  // Metalliser / Slitter umbrella keep title-case
  if(/^metalliser$/i.test(s) || /^met$/i.test(s)) return 'Metalliser';
  if(/^slitter$/i.test(s) || /^slit$/i.test(s)) return 'Slitter';
  if(/^s\.?i\.?$/i.test(s) || /^supervisor$/i.test(s) || /^engg$/i.test(s) || /^engineer$/i.test(s)) return 'S.I.';
  if(/^manager$/i.test(s) || /^mgr$/i.test(s)) return 'Manager';
  return s;
}

/** Derive internal section key (M1, S2, SUP, MGR…) from machine label. */
function _secFromMachine(machine, designation){
  if(typeof _mapMachineToSec === 'function'){
    const s = _mapMachineToSec(machine, designation||'');
    if(s && s !== 'STAFF') return s;
  }
  const u = String(machine||'').trim().toUpperCase().replace(/\s+/g,'');
  if(/^M-?1$/.test(u) || u==='METALLISER' || u==='MET') return 'M1';
  if(/^M-?2$/.test(u)) return 'M2';
  if(/^M-?(\d+)$/.test(u)) return 'M'+RegExp.$1;
  if(/^S-?1$/.test(u) || u==='SLITTER' || u==='SLIT') return 'S1';
  if(/^S-?2$/.test(u)) return 'S2';
  if(/^S-?(\d+)$/.test(u)) return 'S'+RegExp.$1;
  if(/S\.?I|SUP|ENGG|ENGINEER/.test(u)) return 'SUP';
  if(/MGR|MANAGER/.test(u)) return 'MGR';
  return 'M1';
}

function _buildSecOptions(selectedSec){
  const cfg=getShiftConfigSync();
  const opts=[];
  // Kept for edit form fallback / admin — prefer Machine field in Add form
  (cfg.metallisers||[]).forEach(m=>{
    const key = String(m).replace(/^M[\s\-]?(\d+)$/i,'M$1').toUpperCase().replace(/[^A-Z0-9]/g,'') || m;
    opts.push(`<option value="${key}"${selectedSec===key||selectedSec===m?' selected':''}>${secName(key)||_normalizeMachineLabel(m)}</option>`);
  });
  (cfg.slitters||[]).forEach(s=>{
    const key = String(s).replace(/^S[\s\-]?(\d+)$/i,'S$1').toUpperCase().replace(/[^A-Z0-9]/g,'') || s;
    opts.push(`<option value="${key}"${selectedSec===key||selectedSec===s?' selected':''}>${secName(key)||_normalizeMachineLabel(s)}</option>`);
  });
  opts.push(`<option value="SUP"${selectedSec==='SUP'?' selected':''}>${secName('SUP')||'Engineers / Supervisor'}</option>`);
  opts.push(`<option value="MGR"${selectedSec==='MGR'?' selected':''}>${secName('MGR')||'Manager'}</option>`);
  return opts.join('');
}

/**
 * Machine dropdown — ONLY machines from manager Profile (Shift & Machine Settings).
 * Display: M-1, M-2, Metalliser, S-1, S-2, Slitter (no hardcoded S-3/S-4, no M1+M-1 duplicates).
 */
function _buildMachineOptions(selectedMc){
  const cfg=getShiftConfigSync();
  const ordered = [];
  const seen = new Set();
  const add = (label) => {
    const L = _normalizeMachineLabel(label);
    if(!L || seen.has(L)) return;
    seen.add(L);
    ordered.push(L);
  };
  const mets = (cfg.metallisers||[]).map(m=>String(m||'').trim()).filter(Boolean);
  const slits = (cfg.slitters||[]).map(s=>String(s||'').trim()).filter(Boolean);
  mets.forEach(m=>add(m));
  if(mets.length) add('Metalliser');
  slits.forEach(s=>add(s));
  if(slits.length) add('Slitter');
  // Supervisor / Engineer machine only if no machines at all (still allow assigning eng staff)
  if(!ordered.length){
    add('M-1'); add('M-2'); add('Metalliser'); add('S-1'); add('S-2'); add('Slitter');
  }
  // Always allow S.I. for engineers/supervisors (not fake S-3/S-4)
  add('S.I.');
  // If editing and current value not in list, keep it selectable
  if(selectedMc){
    const cur = _normalizeMachineLabel(selectedMc) || selectedMc;
    if(cur && !seen.has(cur)){ ordered.unshift(cur); seen.add(cur); }
  }
  return ordered.map(m=>{
    const sel = selectedMc && (_normalizeMachineLabel(selectedMc)===m || selectedMc===m) ? ' selected' : '';
    return `<option value="${m}"${sel}>${m}</option>`;
  }).join('');
}
function _buildDesignationOptions(selected){
  const list=['Operator','Ass. Operator','Team Member','Sr. Team Member','Jr. Team Member','Trainee','Engineer','Jr. Engineer','Officer','Supervisor','Sr. Supervisor','Manager','Shift Engineer','Admin'];
  return list.map(r=>`<option value="${r}"${selected===r?' selected':''}>${r}</option>`).join('');
}
function _buildRespOptions(selected){
  const list=['Operation','Assistant','Trainee','Engineer','Manager','Setup','5S','P,Q,M','Quality','Maintenance'];
  return list.map(r=>`<option value="${r}"${selected===r?' selected':''}>${r}</option>`).join('');
}
