function toggleInst(id){
  const el=document.getElementById(id);
  if(!el) return;
  el.classList.toggle('open');
  const i=id.replace('inst-','');
  const arr=document.getElementById('arr-'+i);
  if(arr) arr.textContent=el.classList.contains('open')?'▲':'▼';
}

