// ── Comp Off Details Modal ──
function openCompOffDetails(empId, empName, coDate, currentShift){
  closeModal();
  const emp = getEmps().find(e=>e.id===empId);
  const woff = emp?.woff||'SUN';
  
  // Build last 31 days: show only W-OFF/Holiday dates where emp actually worked (D or N shift)
  const today = new Date();
  const dateOpts = [];
  for(let i=1;i<=31;i++){
    const d = new Date(today);
    d.setDate(d.getDate()-i);
    const ds = d.toISOString().slice(0,10);
    const dayName = ['SUN','MON','TUE','WED','THU','FRI','SAT'][d.getDay()];
    const isWoff = dayName===woff;
    const isHoli = !!MET_HOLIDAYS[ds];
    // Only show if it was a W-off or holiday AND employee actually came to duty (D or N)
    if(isWoff || isHoli){
      const actualShift = getShift(emp, ds);
      if(['D','N','G'].includes(actualShift)){
        dateOpts.push({
          ds, 
          label: d.toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})+' ('+dayName+')',
          isHoli,
          isWoff,
          holiName: MET_HOLIDAYS[ds]||null,
          shift: actualShift
        });
      }
    }
  }
  
  const coDateFmt = new Date(coDate).toLocaleDateString('hi-IN',{day:'numeric',month:'short',year:'numeric'});
  
  const modalDiv = document.createElement('div');
  modalDiv.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.88);z-index:9998;display:flex;align-items:flex-end;justify-content:center;padding:0';
  modalDiv.id='compOffModal';
  modalDiv.innerHTML=`
    <div style="background:#1e293b;border:1px solid #334155;border-radius:20px 20px 0 0;padding:20px 18px 30px;width:100%;max-width:480px;max-height:90vh;overflow-y:auto">
      <div style="width:36px;height:4px;background:#334155;border-radius:2px;margin:0 auto 18px"></div>
      <div style="display:flex;align-items:center;gap:12px;margin-bottom:18px">
        <div style="width:42px;height:42px;background:#713f12;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:18px;font-weight:900;color:#fde68a;flex-shrink:0">CO</div>
        <div>
          <div style="font-size:18px;font-weight:900;color:#fff">Comp Off Details</div>
          <div style="font-size:14px;color:#94a3b8;font-weight:600">${empName} · ${coDateFmt}</div>
        </div>
      </div>

      <div style="font-size:14px;font-weight:800;color:#e2e8f0;letter-spacing:.5px;margin-bottom:8px">किस दिन काम किया था? * <span style="font-weight:600;color:#f97316">(31 दिन की सीमा)</span></div>
      <div id="coWorkedDateSel" style="margin-bottom:14px">
        ${dateOpts.length===0?'<div style="color:#fca5a5;font-size:14px;padding:10px;background:rgba(244,63,94,.12);border-radius:8px;border:1px solid rgba(244,63,94,.3)">⚠️ पिछले 31 दिनों में कोई W-Off/Holiday पर Duty नहीं मिली जो C-Off के योग्य हो</div>':''}
        <input type="hidden" id="coWorkedDate" value="">
        <input type="hidden" id="coWorkedIsHoli" value="">
        <input type="hidden" id="coWorkedHoliName" value="">
        <div id="coDateCards" style="display:flex;flex-direction:column;gap:6px;max-height:180px;overflow-y:auto;padding:2px">
          ${dateOpts.map(o=>`<div class="co-date-card" onclick="selectCoDate(this,'${o.ds}',${o.isHoli},'${(o.holiName||'').replace(/'/g,'\\&#39;')}',${o.isWoff})" data-val="${o.ds}"
            style="padding:14px 16px;border-radius:12px;border:2px solid #475569;background:#0f172a;cursor:pointer;display:flex;align-items:center;gap:12px;transition:all .15s">
            <span style="font-size:22px;flex-shrink:0">${o.isHoli?'🎉':'📅'}</span>
            <div>
              <span style="font-size:16px !important;font-weight:900 !important;color:#fde68a !important;display:block">${o.isHoli?o.holiName:'W-OFF'} — ${o.label.split('(')[0].trim()}</span>
              <span style="font-size:14px !important;color:#22c55e !important;font-weight:700;display:block;margin-top:3px">✅ ${o.shift} Shift worked</span>
            </div>
          </div>`).join('')}
          <div class="co-date-card" onclick="selectCoDate(this,'OTHER',false,'',false)" data-val="OTHER"
            style="padding:14px 16px;border-radius:12px;border:2px solid #475569;background:#0f172a;cursor:pointer;display:flex;align-items:center;gap:12px">
            <span style="font-size:22px">📝</span>
            <span style="font-size:16px !important;font-weight:800 !important;color:#cbd5e1 !important">Other (manually enter)</span>
          </div>
        </div>
        <div id="coManualDate" style="display:none;margin-top:8px">
          <input type="date" id="coManualDateInput" style="width:100%;padding:12px;border-radius:10px;background:#0f172a !important;border:1.5px solid #475569;color:#fff !important;font-size:15px" max="${new Date().toISOString().slice(0,10)}">
        </div>
      </div>

      <div style="font-size:14px;font-weight:800;color:#e2e8f0;letter-spacing:.5px;margin-bottom:8px">कारण / Reason *</div>
      <div id="coReasonArea" style="margin-bottom:14px">
        <div id="coReasonBtns" style="display:flex;flex-wrap:wrap;gap:7px;margin-bottom:8px">
          <button onclick="selectCoReason(this,'W-Off पर बुलाया गया')" style="padding:10px 14px;border-radius:10px;border:1.5px solid #475569;background:#0f172a;color:#e2e8f0;font-size:14px;font-weight:700;cursor:pointer">🔔 W-Off पर बुलाया</button>
          <button onclick="selectCoReason(this,'Holiday पर काम किया')" style="padding:10px 14px;border-radius:10px;border:1.5px solid #475569;background:#0f172a;color:#e2e8f0;font-size:14px;font-weight:700;cursor:pointer">🎉 Holiday काम किया</button>
          <button onclick="selectCoReason(this,'Extra shift ली')" style="padding:10px 14px;border-radius:10px;border:1.5px solid #475569;background:#0f172a;color:#e2e8f0;font-size:14px;font-weight:700;cursor:pointer">⏰ Extra Shift</button>
          <button onclick="selectCoReason(this,'Emergency duty')" style="padding:10px 14px;border-radius:10px;border:1.5px solid #475569;background:#0f172a;color:#e2e8f0;font-size:14px;font-weight:700;cursor:pointer">🚨 Emergency</button>
        </div>
        <input id="coReasonText" placeholder="या कारण लिखें..." style="width:100%;padding:12px;border-radius:10px;background:#0f172a !important;border:1.5px solid #475569;color:#fff !important;font-size:15px;box-sizing:border-box;font-weight:600">
      </div>

      <div id="coSummary" style="display:none;background:rgba(113,63,18,.15);border:1px solid rgba(253,230,138,.2);border-radius:10px;padding:12px;margin-bottom:16px;font-size:12px;color:#fde68a;line-height:1.7"></div>

      <div style="display:flex;gap:10px">
        <button onclick="document.getElementById('compOffModal')?.remove()" style="flex:1;padding:13px;border-radius:10px;border:1px solid #334155;background:none;color:#64748b;font-size:14px;cursor:pointer">रद्द करें</button>
        <button onclick="confirmCompOff('${empId}','${empName}','${coDate}','${currentShift}')" style="flex:2;padding:13px;border-radius:10px;border:none;background:linear-gradient(135deg,#713f12,#92400e);color:#fde68a;font-size:14px;font-weight:900;cursor:pointer">✅ C-Off Mark करें</button>
      </div>
    </div>`;
  document.body.appendChild(modalDiv);
}

function selectCoDate(card, val, isHoli, holiName, isWoff){
  // Deselect all
  document.querySelectorAll('.co-date-card').forEach(c=>{
    c.style.borderColor='#334155'; c.style.background='#0f172a';
  });
  // Select this one
  card.style.borderColor='rgba(253,230,138,.6)'; card.style.background='rgba(113,63,18,.25)';
  document.getElementById('coWorkedDate').value = val;
  // Store metadata in hidden fields so confirmCompOff/updateCoSummary can read them
  const ihEl = document.getElementById('coWorkedIsHoli');
  const hnEl = document.getElementById('coWorkedHoliName');
  if(ihEl) ihEl.value = isHoli ? 'true' : 'false';
  if(hnEl) hnEl.value = holiName || '';
  // Show/hide manual date
  document.getElementById('coManualDate').style.display = val==='OTHER' ? 'block' : 'none';
  // Auto-fill reason
  if(isHoli && holiName){
    const re = document.getElementById('coReasonText');
    if(re && !re.value) re.value = holiName+' पर काम किया';
  }
  updateCoSummary();
}

function onCoWorkedDateChange(){
  const sel = document.getElementById('coWorkedDate');
  const manDiv = document.getElementById('coManualDate');
  if(sel.value==='OTHER'){
    manDiv.style.display='block';
  } else {
    manDiv.style.display='none';
    const isHoli = false;
    const holiName = '';
    if(isHoli && holiName){
      const reasonEl = document.getElementById('coReasonText');
      if(reasonEl && !reasonEl.value) reasonEl.value = holiName+' पर काम किया';
      // Highlight the Holiday reason button
      document.querySelectorAll('#coReasonBtns button').forEach(b=>{
        if(b.textContent.includes('Holiday')) b.click();
      });
    }
    updateCoSummary();
  }
}

function selectCoReason(btn, reason){
  document.querySelectorAll('#coReasonBtns button').forEach(b=>{
    b.style.background='#0f172a'; b.style.color='#e2e8f0'; b.style.borderColor='#475569';
  });
  btn.style.background='rgba(113,63,18,.5)'; btn.style.color='#fde68a'; btn.style.borderColor='rgba(253,230,138,.5)';
  document.getElementById('coReasonText').value = reason;
  updateCoSummary();
}

function updateCoSummary(){
  const sel = document.getElementById('coWorkedDate');
  const reason = document.getElementById('coReasonText')?.value||'';
  const summaryEl = document.getElementById('coSummary');
  if(!summaryEl) return;
  let workedDate = sel?.value==='OTHER' ? (document.getElementById('coManualDateInput')?.value||'') : sel?.value||'';
  if(workedDate && workedDate!=='OTHER'){
    const isHoli = document.getElementById('coWorkedIsHoli')?.value === 'true';
    const holiName = document.getElementById('coWorkedHoliName')?.value || '';
    const wdFmt = new Date(workedDate).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});
    summaryEl.style.display='block';
    summaryEl.innerHTML=`<b>📋 C-Off Summary:</b><br>
      काम किया: ${isHoli?'🎉 '+holiName+' — ':'📅 W-OFF — '}${wdFmt}<br>
      ${reason?'कारण: '+reason:''}`;
  } else {
    summaryEl.style.display='none';
  }
}

function confirmCompOff(empId, empName, coDate, currentShift){
  const sel = document.getElementById('coWorkedDate');
  let workedDate = sel?.value==='OTHER' ? (document.getElementById('coManualDateInput')?.value||'') : sel?.value||'';
  const reason = document.getElementById('coReasonText')?.value?.trim()||'';
  
  if(!workedDate||workedDate==='OTHER'){
    alert('कृपया वो दिन चुनें जब काम किया था'); return;
  }
  
  // Get holiday name if applicable (stored in hidden field by selectCoDate)
  const holiName = document.getElementById('coWorkedHoliName')?.value || null;
  
  // Close modal
  document.getElementById('compOffModal')?.remove();
  
  // Stage the C/O with metadata
  stageSingleShiftChange(empId, empName, coDate, currentShift, 'C/O', {
    workedDate, reason: reason||(holiName?holiName+' पर काम किया':'W-Off पर काम किया'), holiName
  });
}

// Stage a shift change — adds to pending, updates cell in table visually, shows save bar
// ── OD (Other Department) Details Modal ──
function openODDetails(empId, empName, odDate, currentShift){
  const fmtD = new Date(odDate).toLocaleDateString('hi-IN',{day:'numeric',month:'short',year:'numeric'});
  const emps = getEmps().filter(e=>e.status!=='resigned');
  const machines = [...new Set(emps.map(e=>e.mc||'Other'))].sort();
  const machineOpts = machines.map(m=>`<option value="${m}">${m}</option>`).join('');

  openModal(`<div class="modal-handle"></div>
    <div style="display:flex;align-items:center;gap:12px;margin-bottom:16px">
      <div style="width:42px;height:42px;background:#0d9488;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:16px;font-weight:900;color:#ccfbf1;flex-shrink:0">OD</div>
      <div>
        <div style="font-size:16px;font-weight:900;color:#fff">Other Department</div>
        <div style="font-size:12px;color:var(--muted2)">${empName} · ${fmtD}</div>
      </div>
    </div>
    <div class="field">
      <label>किस Machine / Department में गए? *</label>
      <select class="inp-field" id="odDept">
        <option value="">-- चुनें --</option>
        ${machineOpts}
        <option value="__OTHER__">✏️ Other (type करें)</option>
      </select>
    </div>
    <div id="odCustomDeptWrap" style="display:none" class="field">
      <label>Department / Machine का नाम</label>
      <input class="inp-field" id="odCustomDept" placeholder="e.g. Packing, Store, M-9">
    </div>
    <div class="field">
      <label>कारण (Reason)</label>
      <input class="inp-field" id="odReason" placeholder="e.g. Manpower shortage, Training">
    </div>
    <button class="submit-btn" onclick="submitOD('${empId}','${empName}','${odDate}','${currentShift}')">✅ OD Mark करें</button>
    <button class="cancel-btn" onclick="closeModal()">रद्द करें</button>`);
  setTimeout(()=>{
    const sel=document.getElementById('odDept');
    if(sel) sel.addEventListener('change',function(){
      document.getElementById('odCustomDeptWrap').style.display=this.value==='__OTHER__'?'block':'none';
    });
  },100);
}

async function submitOD(empId, empName, date, currentShift){
  const deptSel = document.getElementById('odDept').value;
  const customDept = (document.getElementById('odCustomDept')?.value||'').trim();
  const reason = (document.getElementById('odReason')?.value||'').trim();
  const toDept = deptSel==='__OTHER__' ? customDept : deptSel;

  if(!toDept){ toast('❌ Department / Machine चुनें'); return; }

  // Save OD record to Firebase under reports (accessible to Manager)
  try{
    await fbPush('reports', {
      type: 'od',
      empId, empName, date,
      toDept, reason,
      markedBy: SESSION.name||'Admin',
      markedAt: new Date().toISOString(),
      status: 'approved',
      aboutName: empName,
      section: (getEmps().find(e=>e.id===empId)||{}).sec || 'M1',
      description: `OD → ${toDept}${reason ? ' | '+reason : ''}`,
      createdAt: new Date().toISOString()
    });
  }catch(e){ console.warn('[OD save]', e.message); }

  // Stage the shift change
  stageSingleShiftChange(empId, empName, date, currentShift, 'OD');
}


/** Count Gate Pass days for emp in YYYY-MM of given dateStr (includes pending GP for same month). */
function _countGPInMonth(empId, dateStr){
  let count = 0;
  try{
    const d0 = new Date(dateStr+'T12:00:00');
    const y = d0.getFullYear(), m = d0.getMonth();
    const emp = getEmps().find(e=>e.id===empId);
    // Walk calendar days of that month
    const daysInMonth = new Date(y, m+1, 0).getDate();
    for(let day=1; day<=daysInMonth; day++){
      const ds = y+'-'+String(m+1).padStart(2,'0')+'-'+String(day).padStart(2,'0');
      // pending override for this day wins
      const pend = _pendingShiftChanges[empId+'__'+ds];
      let sh = pend ? pend.newShift : (emp ? getShift(emp, ds) : null);
      if(sh === 'GP') count++;
    }
  }catch(e){}
  return count;
}

/** Apply notification template placeholders. */
function _fillNotifTemplate(tpl, {name, date, dates, manager, changes, gpCount, gpMax}){
  return String(tpl||'')
    .replace(/\{name\}/g, name||'')
    .replace(/\{date\}/g, date||'')
    .replace(/\{dates\}/g, dates||'')
    .replace(/\{manager\}/g, manager||'')
    .replace(/\{changes\}/g, changes||'')
    .replace(/\{gpCount\}/g, String(gpCount!=null?gpCount:''))
    .replace(/\{gpMax\}/g, String(gpMax!=null?gpMax:''));
}

function stageSingleShiftChange(empId, empName, date, currentShift, newShift, coMeta){
  closeModal();
  const key = empId+'__'+date;
  const isOwn = (SESSION.empObjId && empId===SESSION.empObjId) || (myEmp() && myEmp().id===empId);
  const fromMyShift = (typeof _currentTab!=='undefined' && _currentTab==='myshift');
  const canEdit = (typeof canEditSchedule==='function') && canEditSchedule();

  if(newShift === currentShift){
    delete _pendingShiftChanges[key];
    const cellEl = document.querySelector(`[data-pending="${key}"]`);
    if(cellEl){
      cellEl.innerHTML = `<span class="shc ${cellClass(currentShift)}">${cellDisp(currentShift)}</span>`;
      cellEl.removeAttribute('data-pending');
    }
    _updateSaveBar();
    if(fromMyShift){ try{ renderMyShift(); }catch(e){} }
    return;
  }

  // Gate Pass monthly limit
  if(newShift === 'GP'){
    const cfg = getShiftConfigSync();
    const gpMax = Math.max(1, Number(cfg.gpMaxPerMonth)||2);
    const prev = _pendingShiftChanges[key];
    _pendingShiftChanges[key] = { empId, empName, date, newShift, currentShift, coMeta: coMeta||null };
    const gpCount = _countGPInMonth(empId, date);
    if(gpCount > gpMax){
      if(prev) _pendingShiftChanges[key] = prev;
      else delete _pendingShiftChanges[key];
      toast(`⛔ Gate Pass limit: महीने में अधिकतम ${gpMax} GP। ${empName} के पास पहले से limit पूरी है।`);
      return;
    }
  }

  // ── Member (no schedule authority): request manager approval — stay on My Shift ──
  if(isOwn && !canEdit){
    delete _pendingShiftChanges[key];
    _submitOwnShiftChangeRequest(empId, empName, date, currentShift, newShift, coMeta);
    return;
  }

  // ── Manager / authorized: from My Shift → save here (no jump to Schedule) ──
  if(fromMyShift && canEdit){
    _pendingShiftChanges[key] = { empId, empName, date, newShift, currentShift, coMeta: coMeta||null };
    // Auto-save this change in place; skip WhatsApp when only own shift
    const skipWA = isOwn;
    toast((_lang==='en')?'⏳ Saving shift…':'⏳ Shift save हो रही है…');
    saveAllShiftChanges({ skipWhatsApp: skipWA, stayOnMyShift: true }).catch(e=>{
      toast('❌ '+(e&&e.message||e));
    });
    return;
  }

  // ── Schedule grid path: stage + save bar ──
  _pendingShiftChanges[key] = { empId, empName, date, newShift, currentShift, coMeta: coMeta||null };

  const cellEl = document.querySelector(`td[data-cellkey="${empId}_${date}"]`);
  if(cellEl){
    cellEl.dataset.pending = key;
    cellEl.dataset.origShift = currentShift;
    cellEl.innerHTML = `
      <span class="shc ${cellClass(newShift)}" style="outline:2px solid var(--m1);border-radius:4px;box-shadow:0 0 6px rgba(249,115,22,.5)">${cellDisp(newShift)}</span>
      <div style="font-size:7px;color:var(--m1);text-align:center;line-height:1;margin-top:1px;font-weight:900">NEW</div>`;
  }
  try{
    if(_currentTab==='myshift' && typeof renderMyShift==='function') renderMyShift();
  }catch(e){}

  _updateSaveBar();
  toast(`⚡ ${empName}: ${cellDisp(newShift)} pending — Save दबाएँ`);
}

/** Member requests own shift change → assigned manager only */
async function _submitOwnShiftChangeRequest(empId, empName, date, currentShift, newShift, coMeta){
  const isEn = (typeof _lang!=='undefined' && _lang==='en');
  try{
    toast(isEn?'⏳ Sending request to Manager…':'⏳ Manager को request भेजी जा रही है…');
    try{ await window._fbSignInAnon && window._fbSignInAnon(); }catch(e){}
    const me = myEmp() || {};
    const managerId = SESSION.managerId || me.managerId || '';
    if(!managerId){
      toast(isEn?'❌ No manager linked — ask Admin':'❌ Manager link नहीं है — Admin से संपर्क करें');
      return;
    }
    const req = {
      type: 'shift_change_request',
      empObjId: empId,
      empId: me.empId || SESSION.empId || '',
      empName: empName || SESSION.name || '',
      date,
      currentShift,
      newShift,
      coMeta: coMeta || null,
      managerId: String(managerId),
      phone: SESSION.mobile || me.phone || me.mobile || '',
      status: 'pending',
      requestedAt: new Date().toISOString(),
      requestedBy: SESSION.name || empName || ''
    };
    const reqKey = await fbPush('shiftChangeRequests', req);
    await fbUpdate('shiftChangeRequests/'+reqKey, { _key: reqKey });

    // Notify assigned manager only
    const notif = {
      type: 'shift_change_request',
      title: isEn ? '📅 Shift change request' : '📅 Shift बदलने का अनुरोध',
      body: (empName||'')+' · '+date+' · '+(currentShift||'—')+' → '+(newShift||''),
      reqKey, empObjId: empId, date, newShift, currentShift,
      managerId: String(managerId),
      read: false, at: new Date().toISOString()
    };
    const targets = new Set([String(managerId)]);
    try{
      const allMu = await fbGet('mobileUsers') || {};
      Object.entries(allMu).forEach(([mobKey, u])=>{
        if(!u || u.role!=='manager' || u.status!=='approved') return;
        const mid = String(managerId);
        if(u.empObjId===mid || u.employeeId===mid || mobKey===(typeof _normMobileKey==='function'?_normMobileKey(mid):mid) ||
           (typeof _normMobileKey==='function' && _normMobileKey(u.mobile||'')===_normMobileKey(mid))){
          targets.add(mobKey);
          if(u.empObjId) targets.add(u.empObjId);
          if(u.mobile) targets.add(_normMobileKey(u.mobile));
        }
      });
    }catch(e){}
    for(const t of targets){
      if(!t) continue;
      try{ await fbPush('userNotifications/'+t, notif); }catch(e){}
    }

    toast(isEn
      ? ('✅ Request sent to Manager — wait for approval')
      : ('✅ Manager को request भेज दी — Approve के बाद shift अपडेट होगी'));
    // WhatsApp to manager if template enabled (in-app already sent above)
    try{
      await _notifyMappedManagerAfterMemberAction('shift', {
        managerId: managerId,
        empObjId: empId,
        name: empName || SESSION.name,
        date: date,
        dates: date,
        currentShift: currentShift,
        newShift: newShift,
        reqKey: reqKey,
        skipInApp: true,
        notifBody: (empName||'')+' · '+date+' · '+(currentShift||'—')+' → '+(newShift||'')
      });
    }catch(e2){ console.warn('[shift WA]', e2); }
    try{ renderMyShift(); }catch(e){}
  }catch(e){
    console.error('[shift change request]', e);
    toast('❌ '+(e&&e.message||e));
  }
}


async function _renderPendingShiftChangeRequests(){
  if(!(typeof isAdminOrMgr==='function' && isAdminOrMgr()) && !(typeof canEditSchedule==='function' && canEditSchedule())) return;
  let host = document.getElementById('pendingShiftChangeReqs');
  if(!host){
    // Create container above device pending if possible
    const parent = document.getElementById('pendingLoginRequests') || document.getElementById('adminOnlyPendingBlock') || document.getElementById('pendingRegs');
    if(!parent || !parent.parentNode) return;
    host = document.createElement('div');
    host.id = 'pendingShiftChangeReqs';
    parent.parentNode.insertBefore(host, parent.nextSibling);
  }
  try{
    const data = await fbGet('shiftChangeRequests') || {};
    let list = Object.entries(data).filter(([k,v])=>v && v.status==='pending');
    if(typeof isAdmin==='function' && isAdmin()){
      // all
    } else {
      list = list.filter(([k,v])=> _isMyTeamLoginRequest({ managerId: v.managerId, type:'manager_login_approval' }) ||
        (SESSION.empObjId && v.managerId===SESSION.empObjId) || (SESSION.uid && v.managerId===SESSION.uid));
    }
    if(!list.length){ host.innerHTML=''; return; }
    const isEn = (typeof _lang!=='undefined' && _lang==='en');
    host.innerHTML = `<div style="font-size:13px;font-weight:900;color:#38bdf8;margin:12px 0 8px">📅 ${isEn?'Shift change requests':'Shift बदलने के अनुरोध'}</div>` +
      list.map(([k,v])=>`
        <div class="card" style="margin-bottom:8px;border-left:3px solid #38bdf8">
          <div class="card-name">${(v.empName||'').replace(/</g,'')}</div>
          <div class="card-sub">${v.date||''} · <b>${v.currentShift||'—'}</b> → <b style="color:#38bdf8">${v.newShift||''}</b></div>
          <div class="card-meta">${v.requestedAt?new Date(v.requestedAt).toLocaleString('hi-IN'):''}</div>
          <div class="action-row" style="margin-top:8px;display:flex;gap:8px">
            <button class="act-btn approve" onclick="approveShiftChangeRequest('${k}')">✅ Approve</button>
            <button class="act-btn reject" onclick="rejectShiftChangeRequest('${k}')">❌ Reject</button>
          </div>
        </div>`).join('');
  }catch(e){ console.warn('[pending shift reqs]', e); }
}

async function approveShiftChangeRequest(reqKey){
  try{
    const rec = await fbGet('shiftChangeRequests/'+reqKey);
    if(!rec || rec.status!=='pending'){ toast('Already handled'); return; }
    if(!canEditSchedule() && !(typeof isAdmin==='function' && isAdmin())){
      toast('❌ Permission नहीं है'); return;
    }
    const okAuth = await _ensureWriteAuth();
    if(!okAuth){ toast('❌ Phone verify करें'); return; }
    const ovKey = rec.empObjId+'_'+rec.date;
    await fbUpdate('overrides', { [ovKey]: rec.newShift });
    try{
      _cache.overrides = {...(getOverrides()||{}), [ovKey]: rec.newShift};
    }catch(e){}
    await fbUpdate('shiftChangeRequests/'+reqKey, {
      status: 'approved',
      approvedAt: new Date().toISOString(),
      approvedBy: SESSION.name||''
    });
    // Notify member
    try{
      if(rec.empObjId){
        await fbPush('userNotifications/'+rec.empObjId, {
          type: 'shift_change_approved',
          title: '✅ Shift change approved',
          body: (rec.date||'')+' → '+(rec.newShift||''),
          read: false, at: new Date().toISOString()
        });
      }
    }catch(e){}
    toast('✅ Shift updated');
    try{ if(typeof renderPending==='function') renderPending(); }catch(e){}
    try{ if(typeof renderSchedule==='function') renderSchedule(); }catch(e){}
    try{ if(typeof renderMyShift==='function') renderMyShift(); }catch(e){}
  }catch(e){ toast('❌ '+(e.message||e)); }
}

async function rejectShiftChangeRequest(reqKey){
  try{
    await fbUpdate('shiftChangeRequests/'+reqKey, {
      status: 'rejected',
      rejectedAt: new Date().toISOString(),
      rejectedBy: SESSION.name||''
    });
    toast('Request rejected');
    try{ if(typeof renderPending==='function') renderPending(); }catch(e){}
  }catch(e){ toast('❌ '+(e.message||e)); }
}

// Legacy single-call — now just a wrapper used by resetShiftOverride
async function applyShiftChange(){ /* unused — replaced by stageSingleShiftChange */ }

async function resetShiftOverride(empId, date){
  closeModal();
  try{
    const existing = {...getOverrides()};
    delete existing[empId+'_'+date];
    await fbSet('overrides', existing);
    toast('🔄 Original shift restore हो गई');
    renderSchedule();
  }catch(e){ toast('❌ Error: '+e.message); }
}


// ════════════════════════════════════════════════════════
// DYNAMIC SCHEDULE BUILDER — Admin
// ════════════════════════════════════════════════════════

const SHIFT_QUICK = ['D','N','A','B','C','O','L','G','C/O','HLF','Ab'];

function openScheduleBuilder(){
  const now = new Date();
  const nextMonth = new Date(now.getFullYear(), now.getMonth()+1, 1);
  // FIX: Use local date parts — toISOString() converts to UTC which shifts months in IST
  const defaultKey = nextMonth.getFullYear()+'-'+String(nextMonth.getMonth()+1).padStart(2,'0');
  const months = [];
  for(let i=-1; i<=6; i++){
    const d = new Date(now.getFullYear(), now.getMonth()+i, 1);
    const key = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
    const label = d.toLocaleDateString(_lang==='en'?'en-IN':'hi-IN',{month:'long',year:'numeric'});
    months.push({key, label});
  }
  const monthOpts = months.map(m=>`<option value="${m.key}"${m.key===defaultKey?' selected':''}>${m.label}</option>`).join('');
  const isEn = (typeof _lang !== 'undefined' && _lang === 'en');
  const L = {
    title: isEn ? '📋 Schedule Builder' : '📋 Schedule Builder',
    month: isEn ? 'Select Month' : 'महीना चुनें',
    section: isEn ? 'Section' : 'Section',
    allSec: isEn ? 'All Sections' : 'सभी Section',
    dateRange: isEn ? 'Date Range' : 'तारीख रेंज',
    fullMonth: isEn ? '📅 Full Month' : '📅 पूरा महीना',
    customDates: isEn ? '🗓️ Custom Dates' : '🗓️ कस्टम तारीख',
    from: isEn ? 'From' : 'से (From)',
    to: isEn ? 'To' : 'तक (To)',
    hint: isEn ? 'e.g. 11 to 20 — only these days will appear in the schedule' : 'उदा. 11 से 20 — केवल ये दिन Schedule में दिखेंगे',
    open: isEn ? '📋 Open Schedule' : '📋 Schedule खोलें',
    cancel: isEn ? 'Cancel' : 'रद्द करें',
  };
  const secOpts = Object.entries(SEC).map(([k,v])=>{
    const name = isEn ? (v.label||k) : (v.hi||v.label||k);
    return `<option value="${k}">${name}</option>`;
  }).join('');
  
  openModal(`<div class="modal-handle"></div>
    <div class="modal-title">${L.title}</div>
    <div class="field" style="margin-bottom:14px">
      <label>${L.month}</label>
      <select class="inp-field" id="sb_month" onchange="_sbUpdateDayOptions()">${monthOpts}</select>
    </div>
    <div class="field" style="margin-bottom:14px">
      <label>${L.section}</label>
      <select class="inp-field" id="sb_sec">
        <option value="ALL">${L.allSec}</option>
        ${secOpts}
      </select>
    </div>
    <div class="field" style="margin-bottom:10px">
      <label>${L.dateRange}</label>
      <div style="display:flex;gap:8px;margin-top:6px">
        <button type="button" id="sbRangeFull" class="sb-range-btn on" onclick="_sbSetRangeMode('full')"
          style="flex:1;padding:10px 8px;border-radius:10px;border:1.5px solid var(--m1);background:rgba(249,115,22,.12);color:var(--m1);font-size:13px;font-weight:800;cursor:pointer">${L.fullMonth}</button>
        <button type="button" id="sbRangeCustom" class="sb-range-btn" onclick="_sbSetRangeMode('custom')"
          style="flex:1;padding:10px 8px;border-radius:10px;border:1.5px solid var(--border2);background:var(--card);color:var(--muted2);font-size:13px;font-weight:800;cursor:pointer">${L.customDates}</button>
      </div>
    </div>
    <div id="sbCustomRangeFields" style="display:none;margin-bottom:14px">
      <div style="display:flex;gap:10px;align-items:flex-end">
        <div class="field" style="flex:1;margin:0">
          <label style="font-size:12px">${L.from}</label>
          <select class="inp-field" id="sb_dayFrom"></select>
        </div>
        <div style="padding-bottom:12px;color:var(--muted2);font-weight:800">→</div>
        <div class="field" style="flex:1;margin:0">
          <label style="font-size:12px">${L.to}</label>
          <select class="inp-field" id="sb_dayTo"></select>
        </div>
      </div>
      <div style="font-size:11px;color:var(--muted2);margin-top:6px">${L.hint}</div>
    </div>
    <button class="submit-btn" onclick="loadScheduleBuilder()">${L.open}</button>
    <button class="cancel-btn" onclick="closeModal()">${L.cancel}</button>`);
  setTimeout(_sbUpdateDayOptions, 30);
}

let _sbRangeMode = 'full'; // 'full' | 'custom'

function _sbSetRangeMode(mode){
  _sbRangeMode = mode;
  const fullBtn = document.getElementById('sbRangeFull');
  const custBtn = document.getElementById('sbRangeCustom');
  const fields = document.getElementById('sbCustomRangeFields');
  if(!fullBtn || !custBtn || !fields) return;
  if(mode === 'custom'){
    fullBtn.style.borderColor = 'var(--border2)';
    fullBtn.style.background = 'var(--card)';
    fullBtn.style.color = 'var(--muted2)';
    custBtn.style.borderColor = 'var(--m1)';
    custBtn.style.background = 'rgba(249,115,22,.12)';
    custBtn.style.color = 'var(--m1)';
    fields.style.display = 'block';
    _sbUpdateDayOptions();
  } else {
    custBtn.style.borderColor = 'var(--border2)';
    custBtn.style.background = 'var(--card)';
    custBtn.style.color = 'var(--muted2)';
    fullBtn.style.borderColor = 'var(--m1)';
    fullBtn.style.background = 'rgba(249,115,22,.12)';
    fullBtn.style.color = 'var(--m1)';
    fields.style.display = 'none';
  }
}

function _sbUpdateDayOptions(){
  const monthEl = document.getElementById('sb_month');
  const fromEl = document.getElementById('sb_dayFrom');
  const toEl = document.getElementById('sb_dayTo');
  if(!monthEl || !fromEl || !toEl) return;
  const [yr, mo] = monthEl.value.split('-').map(Number);
  const dim = new Date(yr, mo, 0).getDate();
  const curFrom = parseInt(fromEl.value, 10) || 1;
  const curTo = parseInt(toEl.value, 10) || dim;
  fromEl.innerHTML = Array.from({length: dim}, (_,i) => {
    const d = i + 1;
    return `<option value="${d}"${d===Math.min(curFrom,dim)?' selected':''}>${d}</option>`;
  }).join('');
  toEl.innerHTML = Array.from({length: dim}, (_,i) => {
    const d = i + 1;
    return `<option value="${d}"${d===Math.min(Math.max(curTo,1),dim)?' selected':''}>${d}</option>`;
  }).join('');
  // sensible default for custom: mid-month example 11–20 if available
  if(_sbRangeMode === 'custom' && !fromEl.dataset.inited){
    fromEl.value = String(Math.min(11, dim));
    toEl.value = String(Math.min(20, dim));
    fromEl.dataset.inited = '1';
  }
}

const WOFF_DOW = {SUN:0,MON:1,TUE:2,WED:3,THU:4,FRI:5,SAT:6};

async function loadScheduleBuilder(){
  try{
  _sbSelStart=null; _sbSelEnd=null; _sbSelectedCells=[]; _sbSelecting=false;
  const monthKey = document.getElementById('sb_month').value;
  const secFilter = document.getElementById('sb_sec').value;
  if(!monthKey){toast('⚠️ महीना चुनें');return;}
  const [yr, mo] = monthKey.split('-').map(Number);
  const daysInMonth = new Date(yr, mo, 0).getDate();
  // Custom date range support (e.g. 11–20 Oct)
  let dayFrom = 1, dayTo = daysInMonth;
  if(typeof _sbRangeMode !== 'undefined' && _sbRangeMode === 'custom'){
    const fEl = document.getElementById('sb_dayFrom');
    const tEl = document.getElementById('sb_dayTo');
    dayFrom = Math.max(1, Math.min(daysInMonth, parseInt(fEl && fEl.value, 10) || 1));
    dayTo   = Math.max(1, Math.min(daysInMonth, parseInt(tEl && tEl.value, 10) || daysInMonth));
    if(dayFrom > dayTo){ const tmp=dayFrom; dayFrom=dayTo; dayTo=tmp; }
  }
  window._sbDayFrom = dayFrom;
  window._sbDayTo = dayTo;
  window._sbDaysInMonth = daysInMonth;
  const dayNums = Array.from({length: dayTo - dayFrom + 1}, (_,i)=> dayFrom + i);

  // Load existing saved schedule if any — guard against null/undefined
  const allScheds = getSchedules() || {};
  const saved = allScheds[monthKey.replace('-','_')] || {};
  
  // Ensure custom order is loaded so sequence matches main Schedule view
  try{ await loadCustomEmpOrder(); }catch(e){}

  let emps = (getEmps() || []).filter(e => e && e.status !== 'resigned');
  if(secFilter !== 'ALL') emps = emps.filter(e => e.sec === secFilter);

  // ── Sort employees in same order as main Schedule view ──
  // Mirror DISPLAY_ORDER from renderSchedule(): Main Ops → Relievers → Team,
  // grouped by Metalliser → Slitter → Supervisor → Manager
  const _GROUP_RANK = (e) => {
    const role = getEmpRole(e).role;
    if(['M1','M2'].includes(e.sec)){
      if(role==='main')     return 1;
      if(role==='reliever') return 2;
      return 3; // assist/team
    }
    if(['S1','S2'].includes(e.sec)){
      if(role==='main')     return 4;
      if(role==='slit_rel') return 5;
      return 6; // team
    }
    if(e.sec==='SUP'){
      if(role==='sup_slit') return 7;
      if(role==='sup_met')  return 8;
      return 9;
    }
    if(e.sec==='MGR') return 10;
    return 99;
  };
  emps.sort((a,b) => {
    const rA = _GROUP_RANK(a), rB = _GROUP_RANK(b);
    if(rA !== rB) return rA - rB;
    return getEmpDisplayOrder(a) - getEmpDisplayOrder(b);
  });

  // Build grid — date header is a SEPARATE sticky row (table thead sticky breaks under overflow-x)
  const headerDays = dayNums.map(d=>{
    const dt = new Date(yr, mo-1, d);
    const dow = ['S','M','T','W','T','F','S'][dt.getDay()];
    const sun = dt.getDay()===0;
    return `<div data-sb-date-col="${d}" style="flex:0 0 32px;width:32px;min-width:32px;text-align:center;padding:4px 2px;font-size:10px;font-weight:800;color:${sun?'#f87171':'#94a3b8'};line-height:1.15">${d}<br><span style="font-size:9px;font-weight:700">${dow}</span></div>`;
  }).join('');

  const rows = emps.map((emp,rowIdx) => {
    if(!emp || !emp.id) return '';
    // Ensure empSaved is always an array (Firebase converts arrays to objects)
    let empSaved = saved[emp.id];
    if(empSaved && !Array.isArray(empSaved)){
      empSaved = Array.from({length: daysInMonth}, (_,i) => empSaved[i] || empSaved[String(i)] || '');
    }
    if(!empSaved) empSaved = Array(daysInMonth).fill('');
    
    const empWoffDow = emp.woff ? (WOFF_DOW[emp.woff] ?? -1) : -1;
    
    // Build approved leave dates for this employee in this month
    const empLeaves = new Set();
    try{
      (getLeaves()||[]).filter(l => l && l.status === 'approved' && l.empId === emp.id && l.from && l.to).forEach(l => {
        const fromD = new Date(l.from);
        const toD = new Date(l.to);
        if(isNaN(fromD.getTime()) || isNaN(toD.getTime())) return;
        for(let dd = new Date(fromD); dd <= toD; dd.setDate(dd.getDate() + 1)){
          empLeaves.add(dd.toISOString().slice(0, 10));
        }
      });
    }catch(leaveErr){ console.warn('Leave parse error for', emp.id, leaveErr); }
    
    const cells = dayNums.map((d,i) => {
      const dayIdx = d - 1; // always 0-based index in full month array
      const dateStr = `${yr}-${String(mo).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
      const isLeaveDate = empLeaves.has(dateStr);
      let val = empSaved[dayIdx] || (function(){
        const mk2 = monthKey.replace('-','_');
        if(typeof EXCEL_SCHEDULES !== 'undefined' && EXCEL_SCHEDULES[mk2] && EXCEL_SCHEDULES[mk2][emp.id]){
          return EXCEL_SCHEDULES[mk2][emp.id][dayIdx] || '';
        }
        if(yr===2026 && mo===3 && emp.ms) return emp.ms[dayIdx]||'';
        return '';
      })();
      // If approved leave exists and cell is empty or not already L, mark as L
      if(isLeaveDate && val !== 'L') val = 'L';
      const cls = val ? cellClass(val) : '';
      const isWoffDay = empWoffDow !== -1 && new Date(yr, mo-1, d).getDay() === empWoffDow;
      const leaveStyle = isLeaveDate ? 'outline:2px solid #f43f5e;border-radius:4px;box-shadow:0 0 4px rgba(244,63,94,.5);' : '';
      const leaveClick = isLeaveDate ? ` onclick="_confirmLeaveOverride(this,'${emp.id}',${dayIdx},'${dateStr}')"` : '';
      return `<td style="padding:2px;${isWoffDay?'background:rgba(249,115,22,0.06);':''}" title="${isLeaveDate?'🛡️ Approved Leave':isWoffDay?emp.woff+' (Weekly Off)':''}">
        <div class="shc ${cls}" style="width:28px;height:24px;font-size:10px;cursor:pointer;min-width:unset;touch-action:none;user-select:none;${leaveStyle}${isWoffDay&&!val&&!isLeaveDate?'border:1px dashed rgba(249,115,22,0.3);':''}"${leaveClick}
          data-empid="${emp.id}" data-day="${dayIdx}" data-row="${rowIdx}" data-val="${val}" data-isleave="${isLeaveDate?'1':'0'}">
          ${val ? cellDisp(val) : '—'}
        </div>
      </td>`;
    }).join('');
    const s = SEC[emp.sec];
    return `<tr>
      <td style="padding:4px 8px;font-size:11px;font-weight:700;color:#fff;white-space:nowrap;position:sticky;left:0;background:#0f172a;z-index:1;min-width:90px">
        <span style="display:inline-block;width:6px;height:6px;border-radius:50%;background:${s?.color||'#fff'};margin-right:4px"></span>
        ${emp.name.split(' ')[0]}
        ${emp.woff?`<span style="font-size:8px;color:#f97316;font-weight:600;display:block;margin-top:1px">${emp.woff} off</span>`:''}
      </td>
      ${cells}
    </tr>`;
  }).join('');

  const monthLabel = new Date(yr, mo-1, 1).toLocaleDateString(_lang==='en'?'en-IN':'hi-IN',{month:'long',year:'numeric'});
  const rangeLabel = (dayFrom === 1 && dayTo === daysInMonth)
    ? monthLabel
    : `${dayFrom}–${dayTo} ${monthLabel}`;

  openModal(`<div class="modal-handle"></div>
    <div id="sbStickyHeader" style="position:sticky;top:0;z-index:10;background:var(--bg);padding-bottom:6px">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px">
        <div class="modal-title" style="margin:0">📅 ${rangeLabel}</div>
        <button onclick="openScheduleBuilder()" style="background:none;border:1px solid var(--border2);border-radius:8px;color:var(--muted);padding:5px 10px;cursor:pointer;font-size:12px">← बदलें</button>
      </div>
      <div style="display:flex;gap:8px;align-items:center">
        <div id="sbCellLegend" style="font-size:11px;color:var(--muted2);flex:1">🖱️ Drag करके Cells चुनें · Double-tap करके Copy/Select करें</div>
        <button onclick="autoGenSchedule('${monthKey}')"
          style="background:linear-gradient(135deg,#7c3aed,#4f46e5);border:none;border-radius:10px;
          color:#fff;font-size:12px;font-weight:800;padding:8px 14px;cursor:pointer;white-space:nowrap;
          display:flex;align-items:center;gap:5px;font-family:inherit">
          🤖 Auto बनाएं
        </button>
      </div>
    </div>
    <div id="sbToolbar" style="display:none"></div>
    <!-- Sticky date/day header (synced horizontal scroll with body) -->
    <div id="sbDateHdrWrap" style="position:sticky;z-index:8;background:var(--bg);overflow-x:auto;overflow-y:hidden;scrollbar-width:none;-ms-overflow-style:none;border:1px solid var(--border2);border-bottom:none;border-radius:8px 8px 0 0">
      <div id="sbDateHdr" style="display:flex;align-items:stretch;background:#1e293b;min-width:max-content">
        <div id="sbCornerHeader" style="position:sticky;left:0;z-index:4;flex:0 0 90px;width:90px;min-width:90px;padding:6px 8px;font-size:11px;font-weight:800;color:#94a3b8;background:#1e293b;display:flex;align-items:center;box-shadow:2px 0 6px rgba(0,0,0,.35)">कर्मचारी</div>
        ${headerDays}
      </div>
    </div>
    <div id="sbBodyScroll" style="overflow-x:auto;margin-bottom:14px;border:1px solid var(--border2);border-top:none;border-radius:0 0 8px 8px">
      <table style="border-collapse:collapse;width:max-content;min-width:100%">
        <tbody id="sb_tbody">${rows}</tbody>
      </table>
    </div>
    <div id="sbSaveBar">
      <button class="submit-btn" style="flex:1" onclick="saveScheduleBuilder('${monthKey}')">💾 Save करें</button>
      <button class="cancel-btn" style="flex:1" onclick="closeModal()">रद्द करें</button>
    </div>`);
  setTimeout(initSBSelection, 50);
  setTimeout(_sbPositionStickyTableHeader, 60);
  setTimeout(_sbSyncDateHdrScroll, 70);
  }catch(err){console.error('loadScheduleBuilder error:',err);toast('❌ Error: '+err.message);}
}

// _sbData holds current edits: { empId: [array of shifts] }
let _sbData = {};

function cycleSBCell(el, empId, dayIdx, monthKey){
  const order = ['D','N','O','L','G','C/O','H','OD','HLF','Ab',''];
  const cur = el.dataset.val || '';
  const next = order[(order.indexOf(cur)+1) % order.length];
  _sbSetCellValue(el, next);
}

// ════════════════════════════════════════════════════════════════
// SCHEDULE BUILDER — Excel-like drag-select, copy, paste, quick-fill
// ════════════════════════════════════════════════════════════════
let _sbSelecting=false;
let _sbSelStart=null;   // {row,day}
let _sbSelEnd=null;     // {row,day}
let _sbSelectedCells=[];
let _sbClipboard=null;  // {grid:[[val,...],...], rows, cols}

function _sbSetCellValue(cell, val){
  const empId=cell.dataset.empid;
  const dayIdx=+cell.dataset.day;
  cell.dataset.val=val;
  const selected=cell.classList.contains('sb-selected');
  cell.className='shc '+(val?cellClass(val):'')+(selected?' sb-selected':'');
  cell.textContent=val?cellDisp(val):'—';
  const dim = window._sbDaysInMonth || 31;
  if(!_sbData[empId] || _sbData[empId].length < dim){
    const base = Array.isArray(_sbData[empId]) ? _sbData[empId].slice() : new Array(dim).fill('');
    while(base.length < dim) base.push('');
    // Seed from visible cells (data-day is full-month index)
    const sbTbody=document.getElementById('sb_tbody');
    const allCells=sbTbody?sbTbody.querySelectorAll(`[data-empid="${empId}"]`):[];
    allCells.forEach(c=>{
      const di=+c.dataset.day;
      if(!isNaN(di) && di>=0 && di<dim) base[di]=c.dataset.val||'';
    });
    _sbData[empId]=base;
  }
  if(dayIdx>=0 && dayIdx < _sbData[empId].length) _sbData[empId][dayIdx]=val;
}

function _sbPositionStickyTableHeader(){
  const headerEl=document.getElementById('sbStickyHeader');
  const toolbarEl=document.getElementById('sbToolbar');
  const dateHdrWrap=document.getElementById('sbDateHdrWrap');
  if(!headerEl) return;
  const headerH=headerEl.offsetHeight || 0;
  if(toolbarEl){
    toolbarEl.style.position='sticky';
    toolbarEl.style.top=headerH+'px';
    toolbarEl.style.zIndex='9';
    toolbarEl.style.background='var(--bg)';
  }
  const toolbarVisible = toolbarEl && toolbarEl.style.display!=='none' && toolbarEl.offsetHeight>0;
  const toolbarH = toolbarVisible ? toolbarEl.offsetHeight : 0;
  // Date/day row sticks just under title + selection toolbar
  if(dateHdrWrap){
    dateHdrWrap.style.position='sticky';
    dateHdrWrap.style.top=(headerH + toolbarH)+'px';
    dateHdrWrap.style.zIndex='8';
  }
}

function _sbSyncDateHdrScroll(){
  const hdr = document.getElementById('sbDateHdrWrap');
  const body = document.getElementById('sbBodyScroll');
  if(!hdr || !body) return;
  // hide duplicate scrollbar on header
  hdr.style.scrollbarWidth = 'none';
  if(hdr._sbSyncBound) return;
  hdr._sbSyncBound = true;
  let lock = false;
  body.addEventListener('scroll', ()=>{
    if(lock) return; lock = true;
    hdr.scrollLeft = body.scrollLeft;
    lock = false;
  }, {passive:true});
  hdr.addEventListener('scroll', ()=>{
    if(lock) return; lock = true;
    body.scrollLeft = hdr.scrollLeft;
    lock = false;
  }, {passive:true});
}

function initSBSelection(){
  const tbody=document.getElementById('sb_tbody');
  if(!tbody) return;
  // Inject selection highlight style once
  if(!document.getElementById('sbSelectionStyle')){
    const style=document.createElement('style');
    style.id='sbSelectionStyle';
    style.textContent='.sb-selected{outline:2px solid #3b82f6 !important;box-shadow:0 0 0 2px rgba(59,130,246,.3) !important;position:relative;z-index:2;}';
    document.head.appendChild(style);
  }
  tbody.querySelectorAll('.shc[data-isleave="0"]').forEach(cell=>{
    cell.addEventListener('pointerdown', e=>{
      e.preventDefault();
      _sbSelecting=true;
      _sbSelStart={row:+cell.dataset.row, day:+cell.dataset.day};
      _sbSelEnd={row:+cell.dataset.row, day:+cell.dataset.day};
      _sbUpdateSelectionVisual();
    });
    cell.addEventListener('dblclick', e=>{
      e.preventDefault();
      _sbHandleDoubleClick(cell);
    });
  });
  tbody.addEventListener('pointermove', e=>{
    if(!_sbSelecting) return;
    const el=document.elementFromPoint(e.clientX, e.clientY);
    const cellEl=el?.closest('.shc[data-isleave="0"]');
    if(cellEl){
      const r=+cellEl.dataset.row, d=+cellEl.dataset.day;
      if(!_sbSelEnd || _sbSelEnd.row!==r || _sbSelEnd.day!==d){
        _sbSelEnd={row:r, day:d};
        _sbUpdateSelectionVisual();
      }
    }
  });
  document.addEventListener('pointerup', _sbFinishSelection);
}

function _sbFinishSelection(){
  if(!_sbSelecting) return;
  _sbSelecting=false;
  _sbShowToolbar();
}

function _sbUpdateSelectionVisual(){
  if(!_sbSelStart || !_sbSelEnd) return;
  const r1=Math.min(_sbSelStart.row,_sbSelEnd.row), r2=Math.max(_sbSelStart.row,_sbSelEnd.row);
  const d1=Math.min(_sbSelStart.day,_sbSelEnd.day), d2=Math.max(_sbSelStart.day,_sbSelEnd.day);
  const tbody=document.getElementById('sb_tbody');
  if(!tbody) return;
  _sbSelectedCells=[];
  tbody.querySelectorAll('.shc').forEach(cell=>{
    const row=+cell.dataset.row, day=+cell.dataset.day;
    if(row>=r1&&row<=r2&&day>=d1&&day<=d2){
      cell.classList.add('sb-selected');
      _sbSelectedCells.push(cell);
    }else{
      cell.classList.remove('sb-selected');
    }
  });
}

function _sbClearSelectionOnly(){
  _sbSelStart=null; _sbSelEnd=null;
  document.querySelectorAll('#sb_tbody .sb-selected').forEach(c=>c.classList.remove('sb-selected'));
  _sbSelectedCells=[];
  _sbShowToolbar();
}

function _sbShowToolbar(){
  const bar=document.getElementById('sbToolbar');
  if(!bar) return;
  if(!_sbSelectedCells.length){ bar.innerHTML=''; bar.style.display='none'; setTimeout(_sbPositionStickyTableHeader,10); return; }
  const cfgShifts=(getShiftConfigSync().shifts||[{code:'D',label:'D'},{code:'N',label:'N'}]);
  const values=[
    ...cfgShifts.map(s=>({v:s.code,l:s.code})),
    {v:'O',l:'O'},{v:'L',l:'L'},
    {v:'G',l:'G'},{v:'C/O',l:'CO'},{v:'H',l:'H'},{v:'OD',l:'OD'},
    {v:'HLF',l:'½'},{v:'Ab',l:'Ab'},{v:'',l:'✖ साफ'}
  ];
  bar.style.display='block';
  bar.innerHTML=`
    <div style="background:rgba(59,130,246,.08);border:1px solid rgba(59,130,246,.3);border-radius:10px;padding:10px;margin-bottom:10px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;flex-wrap:wrap;gap:6px">
        <span style="font-size:12px;font-weight:800;color:var(--text)">${_sbSelectedCells.length} Cell चुने गए</span>
        <div style="display:flex;gap:6px">
          <button onclick="_sbCopySelection()" style="background:rgba(34,197,94,.12);color:#22c55e;border:1px solid rgba(34,197,94,.3);border-radius:8px;padding:5px 10px;font-size:11px;font-weight:700;cursor:pointer">📋 Copy</button>
          ${_sbClipboard?`<button onclick="_sbPasteSelection()" style="background:rgba(96,165,250,.12);color:#60a5fa;border:1px solid rgba(96,165,250,.3);border-radius:8px;padding:5px 10px;font-size:11px;font-weight:700;cursor:pointer">📥 Paste (${_sbClipboard.rows}×${_sbClipboard.cols})</button>`:''}
          <button onclick="_sbClearSelectionOnly()" style="background:none;color:#64748b;border:1px solid var(--border2);border-radius:8px;padding:5px 10px;font-size:11px;cursor:pointer">✕</button>
        </div>
      </div>
      <div style="font-size:10px;color:#64748b;margin-bottom:6px">यहाँ tap करके सीधे भरें:</div>
      <div style="display:flex;gap:5px;flex-wrap:wrap">
        ${values.map(o=>`<button onclick="_sbFillSelection('${o.v}')" style="min-width:34px;padding:6px 8px;border-radius:6px;border:1px solid var(--border2);background:var(--card);color:var(--text);font-size:11px;font-weight:800;cursor:pointer">${o.l}</button>`).join('')}
      </div>
    </div>`;
  setTimeout(_sbPositionStickyTableHeader,10);
}

function _sbFillSelection(val){
  _sbSelectedCells.forEach(cell=>_sbSetCellValue(cell,val));
  toast(val?`✅ ${_sbSelectedCells.length} cells में '${cellDisp(val)}' भरा गया`:'✅ Cells साफ हो गए');
}

function _sbCopySelection(){
  if(!_sbSelStart || !_sbSelEnd || !_sbSelectedCells.length) return;
  const r1=Math.min(_sbSelStart.row,_sbSelEnd.row), r2=Math.max(_sbSelStart.row,_sbSelEnd.row);
  const d1=Math.min(_sbSelStart.day,_sbSelEnd.day), d2=Math.max(_sbSelStart.day,_sbSelEnd.day);
  const grid=[];
  for(let r=r1;r<=r2;r++){
    const rowVals=[];
    for(let d=d1;d<=d2;d++){
      const cell=document.querySelector(`#sb_tbody .shc[data-row="${r}"][data-day="${d}"]`);
      rowVals.push(cell?cell.dataset.val||'':'');
    }
    grid.push(rowVals);
  }
  _sbClipboard={grid, rows:r2-r1+1, cols:d2-d1+1};
  toast(`📋 ${_sbClipboard.rows}×${_sbClipboard.cols} Cells Copy हुए`);
  _sbShowToolbar();
}

function _sbPasteSelection(){
  if(!_sbClipboard || !_sbSelStart || !_sbSelEnd) return;
  const r1=Math.min(_sbSelStart.row,_sbSelEnd.row), r2=Math.max(_sbSelStart.row,_sbSelEnd.row);
  const d1=Math.min(_sbSelStart.day,_sbSelEnd.day), d2=Math.max(_sbSelStart.day,_sbSelEnd.day);
  for(let r=r1;r<=r2;r++){
    for(let d=d1;d<=d2;d++){
      const srcVal=_sbClipboard.grid[(r-r1)%_sbClipboard.rows][(d-d1)%_sbClipboard.cols];
      const cell=document.querySelector(`#sb_tbody .shc[data-row="${r}"][data-day="${d}"][data-isleave="0"]`);
      if(cell) _sbSetCellValue(cell, srcVal);
    }
  }
  toast('✅ Paste हो गया');
}

function _sbHandleDoubleClick(cell){
  const row=+cell.dataset.row, day=+cell.dataset.day;
  _sbSelStart={row,day};
  _sbSelEnd={row,day};
  _sbUpdateSelectionVisual();
  if(cell.dataset.val){
    _sbCopySelection(); // has a value — copy it for quick reuse elsewhere
  }else{
    _sbShowToolbar(); // empty — show quick-value picker
  }
}


// ════════════════════════════════════════════════════════════════
// AUTO SCHEDULE GENERATOR
// Logic: Each employee gets weekly off on their woff day (every week).
// Between off days: 6 working days alternating D ↔ N per block.
// Manager (MGR sec) gets G (General) shift.
// Starting shift is determined from last known D/N before the month.
// ════════════════════════════════════════════════════════════════

function findLastShiftBeforeMonth(emp, targetYr, targetMo, validShiftCodes){
  // Search backwards through months to find last valid shift code (from config).
  // ALSO counts how many off-days (O) were encountered between that
  // last shift and the target month, so caller can advance rotation correctly.
  // Returns: { shift, offsAfter: number }
  const shiftSet = new Set(validShiftCodes || ['D','N']);
  const MONTH_ORDER = [
    '2026_04','2026_03','2026_02','2026_01',
    '2025_12','2025_11','2025_10','2025_09','2025_08'
  ];

  // Also check Firebase schedules (may have future months saved)
  const fbScheds = getSchedules() || {};

  // Build list of months to scan backwards from (targetYr_targetMo - 1)
  let scanYr = targetYr, scanMo = targetMo - 1;
  if(scanMo === 0){ scanMo = 12; scanYr--; }

  // Track off-days seen while walking backwards from target month
  // (i.e. days AFTER the last shift, chronologically)
  let offsAfter = 0;

  for(let attempt = 0; attempt < 18; attempt++){
    const mk = `${scanYr}_${String(scanMo).padStart(2,'0')}`;
    const daysInScanMo = new Date(scanYr, scanMo, 0).getDate();

    // Helper: scan a month array backwards, counting offs and returning shift
    const scanArr = (arr) => {
      for(let d = daysInScanMo - 1; d >= 0; d--){
        const sh = arr[d];
        if(shiftSet.has(sh)) return { shift: sh, offsAfter };
        if(sh === 'O') offsAfter++;
      }
      return null;
    };

    // Check Firebase saved first
    if(fbScheds[mk] && fbScheds[mk][emp.id]){
      let arr = fbScheds[mk][emp.id];
      if(arr && !Array.isArray(arr)) arr = Object.values(arr);
      if(arr){
        const res = scanArr(arr);
        if(res) return res;
      }
    }

    // Check EXCEL_SCHEDULES
    if(typeof EXCEL_SCHEDULES !== 'undefined' && EXCEL_SCHEDULES[mk] && EXCEL_SCHEDULES[mk][emp.id]){
      const res = scanArr(EXCEL_SCHEDULES[mk][emp.id]);
      if(res) return res;
    }

    // Also check emp.ms (March 2026 hardcoded in employee object)
    if(scanYr === 2026 && scanMo === 3 && emp.ms && emp.ms.length){
      for(let d = emp.ms.length - 1; d >= 0; d--){
        const sh = emp.ms[d];
        if(shiftSet.has(sh)) return { shift: sh, offsAfter };
        if(sh === 'O') offsAfter++;
      }
    }

    // Go back one more month
    scanMo--;
    if(scanMo === 0){ scanMo = 12; scanYr--; }
    if(scanYr < 2025) break;
  }
  return { shift: (validShiftCodes&&validShiftCodes[0])||'D', offsAfter: 0 }; // default fallback
}

function autoGenSchedule(monthKey){
  const [yr, mo] = monthKey.split('-').map(Number);
  const daysInMonth = new Date(yr, mo, 0).getDate();
  const emps = getEmps().filter(e => e.status !== 'resigned');

  // FIX: scope to modal tbody only — background schedule grid also has
  // cells with [data-empid] which would pollute the result and shift values
  const sbTbody = document.getElementById('sb_tbody');
  if(!sbTbody){ toast('⚠️ पहले Schedule खोलें'); return; }

  // Check if any cells exist in the grid (modal must be open)
  const firstEmp = emps[0];
  const testCells = firstEmp ? sbTbody.querySelectorAll(`[data-empid="${firstEmp.id}"]`) : [];
  if(!testCells.length){ toast('⚠️ पहले Schedule खोलें'); return; }

  // ── Build approved leave map: { empId: Set of 'YYYY-MM-DD' strings } ──
  const leaveMap = {};
  (getLeaves()||[]).filter(l => l && l.status === 'approved' && l.empId && l.from && l.to).forEach(l => {
    if(!leaveMap[l.empId]) leaveMap[l.empId] = new Set();
    const fromD = new Date(l.from);
    const toD = new Date(l.to);
    if(isNaN(fromD.getTime()) || isNaN(toD.getTime())) return;
    for(let d = new Date(fromD); d <= toD; d.setDate(d.getDate() + 1)){
      leaveMap[l.empId].add(d.toISOString().slice(0, 10));
    }
  });

  let generated = 0;
  let leaveProtected = 0;

  emps.forEach(emp => {
    const cells = sbTbody.querySelectorAll(`[data-empid="${emp.id}"]`);
    if(!cells.length) return;

    const woffDow = (emp.woff && WOFF_DOW[emp.woff] !== undefined) ? WOFF_DOW[emp.woff] : -1;
    const isMgrEmp = emp.sec === 'MGR';
    const empLeaves = leaveMap[emp.id] || new Set();

    // Special: no-rotation employees (MGR = G shift)
    if(isMgrEmp){
      const schedule = Array.from({length: daysInMonth}, (_, i) => {
        const dateStr = `${yr}-${String(mo).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;
        const dow = new Date(yr, mo-1, i+1).getDay();
        if(empLeaves.has(dateStr)){ leaveProtected++; return 'L'; }
        return (woffDow !== -1 && dow === woffDow) ? 'O' : 'G';
      });
      _applyScheduleToGrid(emp.id, schedule, cells, empLeaves, yr, mo);
      generated++;
      return;
    }

    // Find last shift before month to determine starting shift, AND count off-days
    // between that shift and the target month — for each off encountered,
    // the rotation advances to the next shift in rotationOrder.
    // Only shifts marked active in Profile → Shift Settings (D+N or A+B+C etc.)
    const configShiftCodes = getActiveRotationCodes();
    // 3-shift: rotate 1st → 3rd → 2nd (e.g. A→C→B→A). 2-shift: natural D→N→D.
    const rotationOrder = configShiftCodes.length===3
      ? [configShiftCodes[0], configShiftCodes[2], configShiftCodes[1]]
      : configShiftCodes;

    // ── Check the currently-open grid for already-filled days first ──
    // (manually set, or from a previous partial generation). If found, PRESERVE
    // those days untouched and continue the rotation correctly from the last
    // filled day, instead of blindly regenerating the whole month from scratch.
    const cellsArr = Array.from(cells).sort((a,b)=>(+a.dataset.day)-(+b.dataset.day));
    let lastFilledDayIdx = -1;
    let lastFilledShift = null;
    let offsSinceLastShift = 0;
    cellsArr.forEach((c,i)=>{
      const v = c.dataset.val || '';
      if(v){
        lastFilledDayIdx = i;
        if(configShiftCodes.includes(v)){ lastFilledShift = v; offsSinceLastShift = 0; }
        else if(v === 'O'){ offsSinceLastShift++; }
      }
    });

    let curShiftIdx, startDay;
    if(lastFilledDayIdx >= 0 && lastFilledShift){
      // Continue from already-filled data already sitting in this month's grid
      curShiftIdx = rotationOrder.indexOf(lastFilledShift);
      if(curShiftIdx===-1) curShiftIdx=0;
      for(let i=0;i<offsSinceLastShift;i++){ curShiftIdx=(curShiftIdx+1)%rotationOrder.length; }
      startDay = lastFilledDayIdx + 1; // only generate days AFTER the last already-filled day
    }else{
      // Nothing filled yet this month at all — fall back to previous month's continuation
      const lastInfo = findLastShiftBeforeMonth(emp, yr, mo, configShiftCodes);
      curShiftIdx = rotationOrder.indexOf(lastInfo.shift);
      if(curShiftIdx===-1) curShiftIdx=0;
      for(let i = 0; i < (lastInfo.offsAfter || 0); i++){
        curShiftIdx = (curShiftIdx+1) % rotationOrder.length;
      }
      startDay = 0;
    }

    // Generate — preserve already-filled days as-is, protect approved leaves,
    // and only auto-fill days from startDay onwards
    const schedule = [];
    for(let d = 0; d < daysInMonth; d++){
      if(d < startDay){
        schedule.push(cellsArr[d] ? (cellsArr[d].dataset.val || '') : '');
        continue;
      }
      const dateStr = `${yr}-${String(mo).padStart(2,'0')}-${String(d+1).padStart(2,'0')}`;
      const dow = new Date(yr, mo-1, d+1).getDay();

      if(empLeaves.has(dateStr)){
        // ── APPROVED LEAVE — do not overwrite ──
        schedule.push('L');
        leaveProtected++;
      } else if(woffDow !== -1 && dow === woffDow){
        schedule.push('O');
        curShiftIdx = (curShiftIdx+1) % rotationOrder.length;
      } else {
        schedule.push(rotationOrder[curShiftIdx]);
      }
    }

    _applyScheduleToGrid(emp.id, schedule, cells, empLeaves, yr, mo);
    generated++;
  });

  let msg = `✅ ${generated} कर्मचारियों की Schedule auto-generate हो गई!`;
  if(leaveProtected > 0) msg += ` · 🛡️ ${leaveProtected} approved leave दिन सुरक्षित रहे`;
  msg += ' Save करें।';
  toast(msg);
}

function _applyScheduleToGrid(empId, schedule, cells, empLeaves, yr, mo){
  cells.forEach((cell, i) => {
    const val = schedule[i] || '';
    const dateStr = (yr && mo) ? `${yr}-${String(mo).padStart(2,'0')}-${String(i+1).padStart(2,'0')}` : '';
    const isLeaveProtected = empLeaves && dateStr && empLeaves.has(dateStr);

    cell.dataset.val = val;
    cell.className = 'shc ' + (val ? cellClass(val) : '');
    cell.style.cssText = 'width:28px;height:24px;font-size:10px;cursor:pointer;min-width:unset;touch-action:none;user-select:none'
      + (isLeaveProtected ? ';outline:2px solid #f43f5e;border-radius:4px;box-shadow:0 0 4px rgba(244,63,94,.5)' : '');
    cell.textContent = val ? cellDisp(val) : '—';

    if(isLeaveProtected){
      // Make leave cells show confirmation before changing
      cell.onclick = function(){ _confirmLeaveOverride(this, empId, i, dateStr); };
    }
  });
  // Store in _sbData memory
  _sbData[empId] = [...schedule];
}

function _confirmLeaveOverride(cell, empId, dayIdx, dateStr){
  const fmtD = new Date(dateStr).toLocaleDateString('hi-IN',{day:'numeric',month:'short',year:'numeric'});
  const empName = (getEmps().find(e=>e.id===empId)||{}).name || empId;

  openModal(`<div class="modal-handle"></div>
    <div style="text-align:center;padding:10px 0">
      <div style="font-size:40px;margin-bottom:10px">⚠️</div>
      <div style="font-size:18px;font-weight:900;color:var(--lv);margin-bottom:6px">Approved Leave है!</div>
      <div style="font-size:13px;color:var(--muted2);margin-bottom:4px"><b style="color:#fff">${empName}</b></div>
      <div style="font-size:13px;color:var(--muted2);margin-bottom:16px">${fmtD} को approved छुट्टी है</div>
      <div style="background:rgba(244,63,94,.08);border:1px solid rgba(244,63,94,.2);border-radius:10px;padding:12px;margin-bottom:16px;font-size:12px;color:var(--lv);line-height:1.6">
        🛡️ इस दिन की approved leave है।<br>
        अगर बदलना है तो पहले <b>Leave Section</b> में reject करें,<br>
        फिर यहाँ shift change करें।
      </div>
      <button class="big-btn" onclick="closeModal();_forceOverrideLeaveCell('${empId}',${dayIdx})" style="margin-bottom:8px;background:linear-gradient(135deg,#dc2626,#9f1239)">
        ⚠️ फिर भी बदलें (Leave हटेगी)
      </button>
      <button class="cancel-btn" onclick="closeModal()">रहने दो — Leave रखो</button>
    </div>`);
}

function _forceOverrideLeaveCell(empId, dayIdx){
  // Re-enable normal cycling on this cell — scope to modal tbody only
  const sbTbody = document.getElementById('sb_tbody');
  const queryRoot = sbTbody || document;
  const cell = queryRoot.querySelectorAll(`[data-empid="${empId}"]`)[dayIdx];
  if(!cell) return;
  cell.style.outline = 'none';
  cell.style.boxShadow = 'none';
  cell.onclick = null;
  // Set to first non-leave option
  cell.dataset.val = 'D';
  cell.className = 'shc ' + cellClass('D');
  cell.textContent = cellDisp('D');
  if(!_sbData[empId]){
    const allCells = queryRoot.querySelectorAll(`[data-empid="${empId}"]`);
    _sbData[empId] = Array.from(allCells).map(c => c.dataset.val || '');
  }
  _sbData[empId][dayIdx] = 'D';
  toast('⚠️ Leave override — D shift set। Save करने पर लागू होगा।');
}

async function saveScheduleBuilder(monthKey){
  const [yr, mo] = monthKey.split('-').map(Number);
  const daysInMonth = (window._sbDaysInMonth) || new Date(yr, mo, 0).getDate();
  
  // FIX: scope to modal tbody only — background schedule grid also has
  // cells with [data-empid] which would corrupt saved data
  const sbTbody = document.getElementById('sb_tbody');
  if(!sbTbody){ toast('⚠️ Schedule Builder open नहीं है'); return; }

  // Merge with existing saved data (for sections / days not loaded)
  const existing = (getSchedules() || {})[monthKey.replace('-','_')] || {};
  const merged = {...existing};
  const emps = getEmps().filter(e => e.status !== 'resigned');

  emps.forEach(emp => {
    const cells = Array.from(sbTbody.querySelectorAll(`[data-empid="${emp.id}"]`));
    if(!cells.length) return;
    // Start from existing full-month array (or blank)
    const arr = Array.isArray(merged[emp.id])
      ? merged[emp.id].slice()
      : new Array(daysInMonth).fill('');
    // Ensure length covers full month
    while(arr.length < daysInMonth) arr.push('');
    cells.forEach(c => {
      const dayIdx = parseInt(c.dataset.day, 10);
      if(!isNaN(dayIdx) && dayIdx >= 0 && dayIdx < daysInMonth){
        arr[dayIdx] = c.dataset.val || 'O';
      }
    });
    merged[emp.id] = arr;
  });
  
  try{
    await fbSet('schedules/' + monthKey.replace('-','_'), merged);
    const from = window._sbDayFrom || 1;
    const to = window._sbDayTo || daysInMonth;
    const rangeMsg = (from === 1 && to === daysInMonth) ? '' : ` (${from}–${to})`;
    toast('✅ Schedule save हो गई!' + rangeMsg);
    closeModal();
    renderSchedule();
  } catch(e){
    toast('❌ Error: ' + e.message);
  }
}

// ── PRINT SYSTEM ─────────────────────────────────────────
// openPrintModal → user picks sections → _execPrint()
// ─────────────────────────────────────────────────────────
function printSched(){
  // Print modal = ONLY current on-screen view groups (Section / Machine / Resp / Designation)
  const roster = getSchedFilteredEmps().filter(e=>e.status!=='resigned' && Array.isArray(e.ms) && e.ms.length>0);
  const viewGroups = _buildSchedDisplayGroups(roster);
  const mode = _schedGroupMode();
  const modeHint = {section:'Sections', machine:'Machines', responsibility:'Responsibility', designation:'Designation'}[mode]||mode;
  const isEn = _lang==='en';

  try{ window._printViewGroups = viewGroups; }catch(e){}

  // One checkbox per on-screen subsection (all checked by default)
  let activeGroups = viewGroups.map((g,i)=>({
    id: 'view_'+i,
    label: g.label,
    checked: true,
    filter: g.filter
  }));
  if(!activeGroups.length){
    activeGroups = [{
      id:'current',
      label: isEn ? '📋 Current View' : '📋 वर्तमान दृश्य',
      checked:true,
      filter:e=>getSchedFilteredEmps().some(x=>x.id===e.id)
    }];
  }

  const rowsHtml = activeGroups.map(g=>`
    <label style="display:flex;align-items:center;gap:10px;padding:10px 12px;
      background:var(--card);border:1px solid var(--border);border-radius:10px;cursor:pointer;margin-bottom:4px">
      <input type="checkbox" class="prtchk" id="prtchk_${g.id}" data-prtid="${g.id}" ${g.checked?'checked':''}
        style="width:18px;height:18px;accent-color:#0ea5e9;cursor:pointer;flex-shrink:0">
      <span style="font-size:13px;font-weight:700;color:var(--text)">${String(g.label).replace(/</g,'&lt;')}</span>
    </label>`).join('');

  openModal(`<div class="modal-handle"></div>
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:14px">
      <div style="font-size:28px">🖨️</div>
      <div>
        <div style="font-size:17px;font-weight:900;color:var(--text)">${isEn?'Print — Current View':'Print — वर्तमान दृश्य'}</div>
        <div style="font-size:11px;color:var(--muted2);margin-top:2px">${isEn?'Grouped by':'ग्रुप'}: <b style="color:var(--m1)">${modeHint}</b> — ${isEn?'same as screen':'स्क्रीन जैसा'}</div>
      </div>
    </div>
    <div style="display:flex;gap:8px;margin-bottom:10px">
      <button type="button" onclick="document.querySelectorAll('.prtchk').forEach(c=>c.checked=true)"
        style="flex:1;padding:8px;border-radius:8px;border:1px solid var(--border2);background:var(--card2);color:var(--text);font-size:12px;font-weight:700;cursor:pointer">✅ ${isEn?'All':'सभी'}</button>
      <button type="button" onclick="document.querySelectorAll('.prtchk').forEach(c=>c.checked=false)"
        style="flex:1;padding:8px;border-radius:8px;border:1px solid var(--border2);background:var(--card2);color:var(--text);font-size:12px;font-weight:700;cursor:pointer">⬜ ${isEn?'None':'कोई नहीं'}</button>
    </div>
    <div style="max-height:50vh;overflow-y:auto;margin-bottom:14px">${rowsHtml}</div>
    <div style="display:flex;gap:10px">
      <button type="button" onclick="_execPrint()" style="flex:1;padding:14px;border-radius:12px;border:none;
        background:linear-gradient(135deg,#0ea5e9,#0369a1);color:#fff;
        font-family:'Noto Sans Devanagari',sans-serif;font-size:15px;font-weight:800;cursor:pointer">🖨️ ${isEn?'Print':'Print करें'}</button>
      <button type="button" onclick="closeModal()" style="padding:12px 16px;border-radius:12px;
        border:1px solid var(--border2);background:var(--card);color:var(--muted2);
        font-family:'Noto Sans Devanagari',sans-serif;font-size:13px;font-weight:700;cursor:pointer">${isEn?'Cancel':'रद्द'}</button>
    </div>`);
}

async function _execPrint(){
  // Gather selected group ids BEFORE closing modal (DOM still present)
  let selectedIds = [...document.querySelectorAll('.prtchk, [id^=prtchk_]')]
    .filter(c=>c.checked)
    .map(c=>c.dataset.prtid || c.id.replace('prtchk_',''));
  // Fallback: if UI had no checkboxes or none checked, print current on-screen filter
  if(!selectedIds.length){
    selectedIds = ['current'];
  }
  if(typeof html2canvas !== 'function'){
    toast('❌ Print library load नहीं हुई — page refresh करके फिर try करें');
    return;
  }
  closeModal();

  // Build print groups from current on-screen subsections (view_0, view_1, …)
  const roster = getSchedFilteredEmps().filter(e=>e.status!=='resigned' && Array.isArray(e.ms) && e.ms.length>0);
  const viewGroups = (window._printViewGroups && window._printViewGroups.length)
    ? window._printViewGroups
    : _buildSchedDisplayGroups(roster);
  const ALL_PRINT_GROUPS = viewGroups.map((g,i)=>({
    id: 'view_'+i,
    label: g.label,
    color: g.color||'#0ea5e9',
    filter: (function(fn){ return function(e){ return getSchedFilteredEmps().some(x=>x.id===e.id) && fn(e); }; })(g.filter)
  }));
  ALL_PRINT_GROUPS.push({
    id:'current',
    label:'📋 CURRENT VIEW',
    color:'#0ea5e9',
    filter:e=>getSchedFilteredEmps().some(x=>x.id===e.id)
  });
  let PRINT_GROUPS = ALL_PRINT_GROUPS.filter(g=>selectedIds.includes(g.id));
  // If nothing checked or only legacy ids — print full current view groups
  if(!PRINT_GROUPS.length){
    PRINT_GROUPS = ALL_PRINT_GROUPS.filter(g=>String(g.id).startsWith('view_'));
  }
  if(!PRINT_GROUPS.length){
    PRINT_GROUPS = [{ id:'current', label:'📋 CURRENT VIEW', color:'#0ea5e9', filter:e=>getSchedFilteredEmps().some(x=>x.id===e.id) }];
  }

  // Date range
  let dates;
  if(_customRangeActive && _customDateFrom && _customDateTo){
    const d=new Date(_customDateFrom),e=new Date(_customDateTo);
    dates=[];let cur=new Date(d);
    while(cur<=e){dates.push(cur.toISOString().split('T')[0]);cur.setDate(cur.getDate()+1);}
  } else {
    dates=Array.from({length:(typeof _schedDayCount==='function'?_schedDayCount():21)},(_,i)=>addDays(TODAY_STR,schedOff+i));
  }

  const allEmps = getEmps().filter(e=>e.status!=='resigned');
  const lbl = document.getElementById('schedLbl').textContent;

  // Auto orientation: >10 date columns → landscape
  const orientation = dates.length > 10 ? 'landscape' : 'portrait';

  // Section label for title
  const sectionLabel = PRINT_GROUPS.map(g=>g.label).join(' · ') || 'Current View';

  // Shift colours
  const SBG={D:'#f59e0b',N:'#4f46e5',A:'#16a34a',B:'#db2777',C:'#0891b2',O:'#dcfce7',L:'#fee2e2','C/O':'#ede9fe',G:'#e0f2fe',H:'#ffedd5',OD:'#ccfbf1',HLF:'#fed7aa',Ab:'#fecaca',GP:'#fdf4ff'};
  const SCL={D:'#000',N:'#fff',A:'#fff',B:'#fff',C:'#fff',O:'#16a34a',L:'#dc2626','C/O':'#7c3aed',G:'#0369a1',H:'#c2410c',OD:'#0d9488',HLF:'#c2410c',Ab:'#991b1b',GP:'#9333ea'};

  // Build tbody
  let tbodyHtml='';
  let totalEmpCount=0;
  PRINT_GROUPS.forEach(grp=>{
    const members=allEmps.filter(grp.filter).sort((a,b)=>getEmpDisplayOrder(a)-getEmpDisplayOrder(b));
    if(!members.length) return;
    totalEmpCount+=members.length;
    tbodyHtml+=`<tr><td colspan="${dates.length+1}" style="background:#1e293b;color:#fff;font-weight:900;font-size:10.5px;padding:5px 10px;text-align:left;letter-spacing:.6px;border:1px solid #334155">${grp.label}</td></tr>`;
    members.forEach(emp=>{
      const isMain=getEmpRole(emp).role==='main';
      tbodyHtml+=`<tr style="background:${isMain?'#fffbeb':'#fff'}">
        <td style="background:${isMain?'#fefce8':'#f8fafc'};text-align:left;padding:3px 6px;white-space:nowrap;border-right:2px solid #334155;border-bottom:1px solid #e2e8f0">
          <div style="font-weight:${isMain?'900':'700'};font-size:10px;color:#000">${isMain?'⭐ ':''}${emp.name}</div>
          <div style="font-size:8px;color:#555;margin-top:1px">${emp.empId||''}</div>
        </td>
        ${dates.map(d=>{
          const sh=getShift(emp,d)||'';
          const isT=d===TODAY_STR;
          const bg=SBG[sh]||'#f1f5f9', cl=SCL[sh]||'#475569';
          const disp=sh==='C/O'?'CO':sh==='HLF'?'½':sh;
          return `<td style="text-align:center;padding:2px;border:1px solid #e2e8f0;${isT?'background:rgba(249,115,22,.07)':''}">
            <span style="display:inline-block;width:22px;height:18px;line-height:18px;border-radius:3px;font-weight:900;font-size:10px;background:${bg};color:${cl};border:1px solid rgba(0,0,0,.15)">${disp}</span>
          </td>`;
        }).join('')}
      </tr>`;
    });
  });

  // Summary rows D/N/L + Total Manpower (filtered roster)
  const printedEmps=PRINT_GROUPS.flatMap(g=>allEmps.filter(g.filter));
  ['D','N','L'].forEach(s=>{
    const lbRow=s==='D'?'☀️ Day':s==='N'?'🌙 Night':'🏖️ Leave';
    const cl=s==='D'?'#b45309':s==='N'?'#3730a3':'#be123c';
    tbodyHtml+=`<tr style="border-top:2px solid #334155">
      <td style="font-size:9px;font-weight:800;color:${cl};padding:3px 6px;background:#f8fafc;border-right:2px solid #334155">${lbRow}</td>
      ${dates.map(d=>{
        const cnt=printedEmps.filter(e=>{const sh=getShift(e,d);return s==='L'?(sh==='L'||sh==='Ab'):sh===s;}).length;
        return `<td style="text-align:center;font-weight:900;font-size:10px;color:${cl};border:1px solid #e2e8f0">${cnt||'—'}</td>`;
      }).join('')}
    </tr>`;
  });
  // Total Manpower row (same roster size under each date — matches on-screen 👥 Total)
  const _printTotalMP = printedEmps.length;
  tbodyHtml+=`<tr style="border-top:2px solid #16a34a">
    <td style="font-size:9px;font-weight:900;color:#15803d;padding:4px 6px;background:#f0fdf4;border-right:2px solid #334155">👥 Total</td>
    ${dates.map(()=>`<td style="text-align:center;font-weight:900;font-size:11px;color:#15803d;background:#f0fdf4;border:1px solid #bbf7d0">${_printTotalMP||'—'}</td>`).join('')}
  </tr>`;

  // Date header cells
  const dateHdrCells=dates.map(d=>{
    const dO=new Date(d),isT=d===TODAY_STR;
    return `<th style="text-align:center;padding:4px 2px;background:${isT?'#fff7ed':'#1e293b'};border:1px solid #334155;min-width:30px;max-width:40px">
      <div style="font-size:8px;font-weight:800;color:${isT?'#c2410c':'#94a3b8'};letter-spacing:.3px">${DAYS_EN[dO.getDay()]}</div>
      <div style="font-size:13px;font-weight:900;color:${isT?'#c2410c':'#fff'}">${dO.getDate()}</div>
    </th>`;
  }).join('');

  // Legend
  const _pcfg = (typeof getShiftConfigSync==='function') ? getShiftConfigSync() : {};
  let LI=[{bg:'#f59e0b',c:'#000',t:'D = Day',code:'D'},{bg:'#4f46e5',c:'#fff',t:'N = Night',code:'N'},{bg:'#16a34a',c:'#fff',t:'A = A Shift',code:'A'},{bg:'#db2777',c:'#fff',t:'B = B Shift',code:'B'},{bg:'#0891b2',c:'#fff',t:'C = C Shift',code:'C'},{bg:'#dcfce7',c:'#16a34a',t:'O = Weekly Off'},{bg:'#fee2e2',c:'#dc2626',t:'L = Leave'},{bg:'#ede9fe',c:'#7c3aed',t:'C/O = Comp Off'},{bg:'#e0f2fe',c:'#0369a1',t:'G = General'},{bg:'#ffedd5',c:'#c2410c',t:'H = Holiday'},{bg:'#ccfbf1',c:'#0d9488',t:'OD = Other Dept'},{bg:'#ede9fe',c:'#6d28d9',t:'GP = Gate Pass'},{bg:'#fed7aa',c:'#c2410c',t:'½ = Half Day'},{bg:'#fecaca',c:'#991b1b',t:'Ab = Absent'}];
  LI = LI.filter(i=>{
    if(!i.code) return true;
    const sh = (_pcfg.shifts||[]).find(s=>String(s.code).toUpperCase()===i.code);
    if(sh && sh.active===false) return false;
    return true;
  });
  const legendHtml=LI.map(i=>`<span style="display:inline-flex;align-items:center;gap:3px">
    <span style="display:inline-block;width:19px;height:15px;background:${i.bg};color:${i.c};border-radius:2px;font-weight:900;font-size:9px;text-align:center;line-height:15px;border:1px solid rgba(0,0,0,.2)">${i.t.split(' ')[0]}</span>
    <span style="color:#444;font-size:9px">${i.t.split('= ')[1]}</span>
  </span>`).join('');

  // ── Build printable div for html2canvas JPEG download ──
  const imgWidth = orientation === 'landscape' ? 1400 : 900;

  const printDiv = document.createElement('div');
  printDiv.style.cssText = `position:fixed;top:-99999px;left:0;background:#fff;padding:14px;font-family:Arial,sans-serif;width:${imgWidth}px;`;

  // Title with VKS Tech branding header
  printDiv.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;padding-bottom:10px;border-bottom:3px solid #1e293b">
      <div style="display:flex;align-items:center;gap:12px">
        <img src="vkslogo512.png" crossorigin="anonymous" alt="VKS Tech" style="width:52px;height:52px;border-radius:12px;object-fit:contain;background:#fff;border:1px solid #e2e8f0;padding:2px" onerror="this.style.display='none'"/>
        <div>
          <div style="font-size:18px;font-weight:900;color:#1e293b;line-height:1.15;letter-spacing:0.2px">VKS Tech — Technology is power</div>
          <div style="font-size:10px;color:#64748b;font-weight:600">vkstech.com · Made by VKS Tech</div>
        </div>
      </div>
      <div style="text-align:right">
        <div style="font-size:16px;font-weight:900;color:#1e293b">Man Power — Shift Schedule</div>
        <div style="font-size:12px;color:#475569;font-weight:700;margin-top:2px">${lbl}</div>
      </div>
    </div>
    <div style="text-align:center;font-size:9px;color:#64748b;margin-bottom:10px">
      Sections: <b>${sectionLabel}</b> &nbsp;·&nbsp; ${totalEmpCount} employees &nbsp;·&nbsp; ${dates.length} days &nbsp;·&nbsp; ${orientation.charAt(0).toUpperCase()+orientation.slice(1)} &nbsp;·&nbsp; Generated: ${new Date().toLocaleString('en-IN',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})}
    </div>
    <table style="width:100%;border-collapse:collapse;font-size:10px">
      <thead>
        <tr>
          <th style="text-align:left;padding:5px 8px;background:#1e293b;color:#fff;font-size:10px;min-width:110px;border:1px solid #334155;white-space:nowrap">Employee</th>
          ${dateHdrCells}
        </tr>
      </thead>
      <tbody>${tbodyHtml}</tbody>
    </table>
    <div style="display:flex;flex-wrap:wrap;gap:8px 14px;margin-top:8px;padding-top:6px;border-top:2px solid #e2e8f0">${legendHtml}</div>
    <div style="display:flex;align-items:center;justify-content:center;gap:6px;margin-top:10px;padding-top:8px;border-top:1px solid #e2e8f0;font-size:10px;color:#64748b;font-weight:600">
      <img src="vkslogo512.png" crossorigin="anonymous" alt="VKS Tech" style="width:16px;height:16px;border-radius:4px;object-fit:contain" onerror="this.style.display='none'"/>
      <span>Made by <b style="color:#1e293b">VKS Tech</b> · vkstech.com</span>
    </div>`;

  document.body.appendChild(printDiv);

  toast('📸 Image बन रही है... रुकिए');
  try{
    // Wait for logo images to load before capturing (else they appear blank)
    const imgs = printDiv.querySelectorAll('img');
    await Promise.all(Array.from(imgs).map(img => {
      if(img.complete && img.naturalWidth > 0) return Promise.resolve();
      return new Promise(res => {
        img.onload = res;
        img.onerror = res;  // don't block on load failure
        setTimeout(res, 2000);  // safety timeout
      });
    }));
    await new Promise(r=>setTimeout(r,300));
    const canvas = await html2canvas(printDiv, {
      scale: 2,
      useCORS: true,
      backgroundColor: '#ffffff',
      width: imgWidth,
      logging: false
    });
    const link = document.createElement('a');
    const safeLbl = lbl.replace(/[^a-zA-Z0-9]/g,'_');
    link.download = `METPower_Schedule_${safeLbl}_${sectionLabel.replace(/[^a-zA-Z0-9]/g,'_')}.jpg`;
    link.href = canvas.toDataURL('image/jpeg', 0.95);
    link.click();
    toast('✅ Schedule image download हो गई!');
  }catch(e){
    console.error(e);
    toast('❌ Error: '+e.message);
  }finally{
    document.body.removeChild(printDiv);
  }
}

// ════════════════════════════════════════
// EXCEL EXPORT — Shift Schedule
// ════════════════════════════════════════
/** Load logo as data-URL for Excel branding (same asset as print). */
async function _loadVksLogoDataUrl(){
  try{
    const res = await fetch('vkslogo512.png', { cache: 'force-cache' });
    if(!res.ok) return null;
    const blob = await res.blob();
    return await new Promise((resolve)=>{
      const fr = new FileReader();
      fr.onload = ()=> resolve(fr.result);
      fr.onerror = ()=> resolve(null);
      fr.readAsDataURL(blob);
    });
  }catch(e){ return null; }
}

/**
 * Download Schedule Excel — same fixed columns & order as Team Import template,
 * then daily shift columns. Branding: VKS Tech – Technology is power + logo (like print).
 */
async function exportSchedExcel(){
  if(!isAdminOrMgr()){ toast('❌ Only Admin/Manager can export'); return; }

  let dates;
  if(_customRangeActive && _customDateFrom && _customDateTo){
    const d=new Date(_customDateFrom), e2=new Date(_customDateTo);
    dates=[]; let cur=new Date(d);
    while(cur<=e2){ dates.push(cur.toISOString().split('T')[0]); cur.setDate(cur.getDate()+1); }
  } else {
    dates=Array.from({length:(typeof _schedDayCount==='function'?_schedDayCount():21)},(_,i)=>addDays(TODAY_STR,schedOff+i));
  }

  const allEmps = getEmps().filter(e=>e.status!=='resigned' && e.status!=='left');
  const dayNames = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  const lbl = (document.getElementById('schedLbl')||{}).textContent || '';
  const genAt = new Date().toLocaleString('en-IN',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});

  // Column sequence matches Manager's working Excel (Name…Section…DOB then dates)
  const FIXED = [
    'Name','Emp ID','Designation','Weekly Off','Mobile','Section',
    'Machine','Responsibility','Salary (₹/month)','Joining Date','Date of Birth'
  ];

  const headerDates = dates.map(d=>{
    const dt = new Date(d+'T00:00:00');
    return String(dt.getDate()).padStart(2,'0')+'-'+dt.toLocaleString('en',{month:'short'})+'-'+String(dt.getFullYear()).slice(2);
  });
  const weekdayRow = dates.map(d=>{
    const dt = new Date(d+'T00:00:00');
    return dayNames[dt.getDay()];
  });

  const sorted = allEmps.slice().sort((a,b)=>{
    const sa = (a.sec||'').toString();
    const sb = (b.sec||'').toString();
    if(sa!==sb) return sa.localeCompare(sb);
    return (a.name||'').localeCompare(b.name||'');
  });

  const dataRows = sorted.map(e=>{
    const mobile = (e.phone||e.mobile||'').toString().replace(/\D/g,'').slice(-10);
    const machine = e.machine || e.mc || '';
    const desig = e.designation || e.desig || '';
    const resp = e.responsibility || e.resp || '';
    const section = (typeof getEmpSection==='function' ? getEmpSection(e) : '') || e.section || e.sec || '';
    const salary = (e.monthlySalary != null && e.monthlySalary !== '') ? e.monthlySalary
      : (e.salary != null && e.salary !== '' ? e.salary : '');
    const shifts = dates.map(d => {
      try{ return getShift(e, d) || ''; }catch(err){ return ''; }
    });
    // Order: Name, Emp ID, Designation, Weekly Off, Mobile, Section, Machine, Responsibility, Salary, Joining Date, Date of Birth, [dates…]
    return [
      e.name||'',
      e.empId||'',
      desig,
      e.woff||'',
      mobile,
      section,
      machine,
      resp,
      salary,
      e.joiningDate||e.doj||'',
      e.dob||'',
      ...shifts
    ];
  });

  toast('⏳ Excel तैयार हो रहा है…');
  const logoDataUrl = await _loadVksLogoDataUrl();
  const fileBase = 'VKS-Tech-ManPower-Schedule-'+(dates[0]||'export')+'-to-'+(dates[dates.length-1]||'');

  // 1) Branded HTML table (Excel opens this) — includes vkslogo512 like print
  try{
    const escH = (s)=> String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
    const thFixed = FIXED.map(h=>'<th style="background:#1e293b;color:#fff;padding:6px 8px;border:1px solid #334155;font-size:11px;white-space:nowrap">'+escH(h)+'</th>').join('');
    const thDates = headerDates.map(h=>'<th style="background:#1e293b;color:#fff;padding:6px 4px;border:1px solid #334155;font-size:10px;text-align:center">'+escH(h)+'</th>').join('');
    const thWeek = FIXED.map(()=>'<th style="background:#334155;color:#94a3b8;padding:3px 4px;border:1px solid #475569;font-size:9px"></th>').join('')
      + weekdayRow.map(w=>'<th style="background:#334155;color:#e2e8f0;padding:3px 4px;border:1px solid #475569;font-size:9px;text-align:center">'+escH(w)+'</th>').join('');
    const body = dataRows.map(r=>{
      const cells = r.map((c,i)=>{
        const isShift = i >= FIXED.length;
        const val = escH(c);
        const bg = isShift ? (
          c==='D'?'#f59e0b':c==='N'?'#4f46e5':c==='G'?'#0284c7':c==='O'?'#475569':c==='L'?'#be123c':
          (c==='C/O'||c==='CO')?'#92400e':c==='H'?'#ea580c':'#fff'
        ) : '#fff';
        const fg = isShift && (c==='D') ? '#000' : (isShift && c ? '#fff' : '#1e293b');
        return '<td style="padding:4px 6px;border:1px solid #cbd5e1;font-size:11px;text-align:'+(isShift?'center':'left')+';background:'+bg+';color:'+fg+';font-weight:'+(isShift?'800':'600')+'">'+val+'</td>';
      }).join('');
      return '<tr>'+cells+'</tr>';
    }).join('');
    const logoImg = logoDataUrl
      ? '<img src="'+logoDataUrl+'" width="52" height="52" alt="VKS Tech" style="border-radius:12px;border:1px solid #e2e8f0;background:#fff;padding:2px"/>'
      : '';
    const html = `<!DOCTYPE html><html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel"><head><meta charset="utf-8"/>
<title>VKS Tech — Man Power Schedule</title>
<!--[if gte mso 9]><xml><x:ExcelWorkbook><x:ExcelWorksheets><x:ExcelWorksheet><x:Name>Schedule</x:Name></x:ExcelWorksheet></x:ExcelWorksheets></x:ExcelWorkbook></xml><![endif]-->
<style>
  body{font-family:Arial,sans-serif;margin:12px;color:#1e293b}
  table{border-collapse:collapse}
</style></head><body>
  <table style="width:100%;margin-bottom:12px;border:none"><tr>
    <td style="border:none;vertical-align:middle;width:64px">${logoImg}</td>
    <td style="border:none;vertical-align:middle;padding-left:10px">
      <div style="font-size:18px;font-weight:900">VKS Tech — Technology is power</div>
      <div style="font-size:11px;color:#64748b">vkstech.com · Made by VKS Tech</div>
    </td>
    <td style="border:none;text-align:right;vertical-align:middle">
      <div style="font-size:16px;font-weight:900">Man Power — Shift Schedule</div>
      <div style="font-size:12px;color:#475569;font-weight:700">${escH(lbl)}</div>
      <div style="font-size:10px;color:#64748b">Generated: ${escH(genAt)} · ${sorted.length} employees</div>
    </td>
  </tr></table>
  <table>
    <thead>
      <tr>${thFixed}${thDates}</tr>
      <tr>${thWeek}</tr>
    </thead>
    <tbody>${body}</tbody>
  </table>
  <div style="margin-top:12px;padding-top:8px;border-top:1px solid #e2e8f0;font-size:10px;color:#64748b;text-align:center">
    ${logoDataUrl?'<img src="'+logoDataUrl+'" width="16" height="16" style="vertical-align:middle;border-radius:3px"/>':''}
    VKS Tech — Technology is power · vkstech.com
  </div>
</body></html>`;
    const blob = new Blob([html], { type: 'application/vnd.ms-excel;charset=utf-8' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = fileBase + '.xls';
    document.body.appendChild(a);
    a.click();
    setTimeout(()=>{ URL.revokeObjectURL(a.href); a.remove(); }, 800);
    toast('✅ Excel downloaded ('+sorted.length+' members) · VKS Tech branding');
    return;
  }catch(err){
    console.warn('[exportSchedExcel] HTML/xls failed', err);
  }

  // 2) Fallback: .xlsx via SheetJS (text branding, same columns)
  try{
    if(!window.XLSX){
      await new Promise((res,rej)=>{
        const s=document.createElement('script');
        s.src='https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js';
        s.onload=res; s.onerror=rej; document.head.appendChild(s);
      });
    }
    const aoa = [];
    aoa.push(['VKS Tech — Technology is power']);
    aoa.push(['Man Power — Shift Schedule', lbl||'', 'Generated: '+genAt]);
    aoa.push(['vkstech.com · Made by VKS Tech']);
    aoa.push([]);
    aoa.push([...FIXED, ...headerDates]);
    aoa.push([...FIXED.map(()=>''), ...weekdayRow]);
    dataRows.forEach(r=> aoa.push(r));
    const ws = XLSX.utils.aoa_to_sheet(aoa);
    ws['!cols'] = FIXED.map((h,i)=>({ wch: i===0 ? 18 : 14 })).concat(headerDates.map(()=>({ wch: 8 })));
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Schedule');
    XLSX.writeFile(wb, fileBase + '.xlsx');
    toast('✅ Excel downloaded ('+sorted.length+' members)');
  }catch(err2){
    console.warn('[exportSchedExcel] xlsx failed', err2);
    toast('❌ Download failed');
  }
}


function getPrice(plan){
  const fp = (_cache.learnPrices||{})[plan];
  if(fp && typeof fp.price === 'number') return fp.price;
  return (PLAN_INFO[plan]||{}).price || 399;
}

// Admin: edit price for a plan
function editPlanPrice(plan){
  if(!isAdmin()){ toast('Only admin'); return; }
  const pi = PLAN_INFO[plan]||{};
  const cur = getPrice(plan);
  openModal(`<div class="modal-handle"></div>
  <div style="font-size:20px;margin-bottom:4px">${pi.icon} ${pi.name}</div>
  <div style="font-size:13px;color:var(--muted2);margin-bottom:18px">Price Edit करें</div>
  <div style="font-size:12px;color:var(--muted2);margin-bottom:6px">नई कीमत (₹)</div>
  <input id="editPriceVal" type="number" min="0" value="${cur}"
    style="width:100%;padding:12px;border-radius:10px;background:#0f172a;border:1px solid #334155;color:#fff;font-size:18px;font-weight:900;text-align:center;margin-bottom:16px">
  <button class="submit-btn" onclick="savePlanPrice('${plan}')">💾 Save करें</button>
  <button class="cancel-btn" onclick="closeModal()">रद्द करें</button>`);
}

async function savePlanPrice(plan){
  const val = parseInt(document.getElementById('editPriceVal').value);
  if(isNaN(val)||val<0){ toast('सही price डालें'); return; }
  await fbSet('learnPrices/'+plan, {price:val, updatedAt:new Date().toISOString(), updatedBy:SESSION.name});
  toast('✅ Price update हो गई!');
  closeModal();
  renderLearnScreen();
}

// Admin: refresh all price displays on plan cards
function refreshPriceDisplays(){
  const ids = ['met_operation','met_maintenance','ms_office','managerial','combo'];
  ids.forEach(plan=>{
    const el = document.getElementById('priceDisp_'+plan);
    if(el) el.textContent = '₹'+getPrice(plan);
  });
  const total = ['met_operation','met_maintenance','ms_office','managerial'].reduce((s,p)=>s+getPrice(p),0);
  const saveEl = document.getElementById('comboSaveDisp');
  if(saveEl) saveEl.textContent = 'Save ₹'+(total-getPrice('combo'))+'!';
}

function openLearnScreen(){
  document.getElementById('learnScreen').classList.add('show');
  renderLearnScreen();
}
function closeLearnScreen(){
  document.getElementById('learnScreen').classList.remove('show');
  // Also close any open section
  closeLearnSection();
}

// ── LEARN SECTION ROUTER ──
function openLearnSection(section){
  document.getElementById('learnMainButtons').style.display='none';
  const metView       = document.getElementById('learnMetTrainView');
  const comingSoonView= document.getElementById('learnComingSoonView');
  const supSkillView  = document.getElementById('learnSupSkillView');
  const metCostView   = document.getElementById('learnMetCostView');
  const mrSkillView   = document.getElementById('learnMRSkillView');
  const excelView     = document.getElementById('learnExcelExpertView');
  const msaiView      = document.getElementById('learnMSAIView');
  // Hide all views
  if(metView)       metView.style.display='none';
  if(comingSoonView)comingSoonView.style.display='none';
  if(supSkillView)  supSkillView.style.display='none';
  if(metCostView)   metCostView.style.display='none';
  if(mrSkillView)   mrSkillView.style.display='none';
  if(excelView)     excelView.style.display='none';
  if(msaiView)      msaiView.style.display='none';

  if(section === 'metrain'){
    metView.style.display='flex';
    const fr = document.getElementById('learnMetTrainIframe');
    const loader = document.getElementById('metTrainLoading');
    if(fr){
      fr.style.display='none';
      if(loader) loader.style.display='flex';
      setTimeout(()=>{ fr.src=''; setTimeout(()=>{ fr.src='met_train_pro.html'; },100); },50);
    }
  } else if(section === 'supskill'){
    supSkillView.style.display='flex';
    const fr     = document.getElementById('supSkillIframe');
    const loader = document.getElementById('supSkillLoading');
    if(fr){
      fr.style.display='none';
      if(loader) loader.style.display='flex';
      window.updateSupSkillShiftBadge();
      setTimeout(()=>{ fr.src=''; setTimeout(()=>{ fr.src='supskill.html'; },100); },50);
    }
  } else if(section === 'mrskill'){
    if(!isAdminOrMgr()){ toast('⚠️ Manager access only'); document.getElementById('learnMainButtons').style.display='block'; return; }
    mrSkillView.style.display='flex';
  } else if(section === 'metcost'){
    if(!isAdminOrMgr()){ toast('⚠️ Manager access only'); document.getElementById('learnMainButtons').style.display='block'; return; }
    metCostView.style.display='flex';
    const fr     = document.getElementById('metCostIframe');
    const loader = document.getElementById('metCostLoading');
    if(fr){
      fr.style.display='none';
      if(loader) loader.style.display='flex';
      try{ window._generateManpowerForMetCost(); }catch(e){ console.warn('Manpower gen error:', e); }
      // Load iframe immediately — MetCost Pro fetches its own data via REST API
      setTimeout(()=>{ fr.src=''; setTimeout(()=>{ fr.src='metcost_pro.html'; },100); },50);
    }
  } else if(section === 'kpiDashboard'){
    if(!isAdminOrMgr()){ toast('⚠️ Manager access only'); document.getElementById('learnMainButtons').style.display='block'; return; }
    const kpiView = document.getElementById('learnKPIDashboardView');
    if(kpiView) kpiView.style.display='flex';
    const fr     = document.getElementById('kpiDashboardIframe');
    const loader = document.getElementById('kpiDashboardLoading');
    if(fr){
      fr.style.display='none';
      if(loader) loader.style.display='flex';
      // Pre-generate manpower data so it's ready when iframe requests it
      try{ window._generateManpowerForMetCost(); }catch(e){ console.warn('Manpower gen error:', e); }
      setTimeout(()=>{ fr.src=''; setTimeout(()=>{ fr.src='kpi_dashboard.html'; },100); },50);
    }
  } else if(section === 'timeStudy'){
    if(!isAdminOrMgr()){ toast('⚠️ Manager access only'); document.getElementById('learnMainButtons').style.display='block'; return; }
    const tsView = document.getElementById('learnTimeStudyView');
    if(tsView) tsView.style.display='flex';
    const fr     = document.getElementById('timeStudyIframe');
    const loader = document.getElementById('timeStudyLoading');
    if(fr){
      fr.style.display='none';
      if(loader) loader.style.display='flex';
      // Time Study reads raw ZJUMBO from shared IDB / Firebase — no manpower needed
      setTimeout(()=>{ fr.src=''; setTimeout(()=>{ fr.src='time_study.html'; },100); },50);
    }
  } else if(section === 'mrmpres'){
    if(!isAdminOrMgr()){ toast('⚠️ Manager access only'); document.getElementById('learnMainButtons').style.display='block'; return; }
    const mrmView = document.getElementById('learnMRMPresView');
    if(mrmView) mrmView.style.display='flex';
    const fr = document.getElementById('mrmPresIframe');
    const loader = document.getElementById('mrmPresLoading');
    if(fr){
      fr.style.display='none';
      if(loader) loader.style.display='flex';
      setTimeout(()=>{ fr.src=''; setTimeout(()=>{ fr.src='mrm_pres.html'; },100); },50);
    }
  } else if(section === 'excelexpert'){
    excelView.style.display='flex';
    const fr     = document.getElementById('excelExpertIframe');
    const loader = document.getElementById('excelExpertLoading');
    if(fr){
      fr.style.display='none';
      if(loader) loader.style.display='flex';
      // Send admin info to Excel Expert iframe
      const _sendAdminInfo = function(){
        try{
          const frEl = document.getElementById('excelExpertIframe');
          if(frEl && frEl.contentWindow){
            frEl.contentWindow.postMessage({type:'userInfo', name:SESSION.name||'User', role:isAdminOrMgr()?'admin':'user', isAdmin:isAdminOrMgr()}, '*');
          }
        }catch(e){}
      };
      setTimeout(()=>{ fr.src=''; setTimeout(()=>{ fr.src='excel_expert.html'; },100); },50);
      setTimeout(_sendAdminInfo, 2000);
      setTimeout(_sendAdminInfo, 4000);
    }
  } else if(section === 'msai'){
    msaiView.style.display='flex';
  } else {
    comingSoonView.style.display='block';
    const titles = {
      supervisor: {icon:'👔', title:'Supervisor Skills', color:'#fbbf24', sub:'Shift Mgmt · Manpower · Quality · Reporting'},
      managerial: {icon:'🎯', title:'Managerial Skills', color:'#c084fc', sub:'Planning · KPI · Leadership · Cost Control'}
    };
    const info = titles[section]||{icon:'🚀',title:'Coming Soon',color:'#fff',sub:''};
    document.getElementById('learnCSIcon').textContent = info.icon;
    document.getElementById('learnCSTitle').style.color = info.color;
    document.getElementById('learnCSTitle').textContent = info.title;
    document.getElementById('learnCSSub').textContent = info.sub;
  }
}

